/// 菜单的像素尺寸（本机 Excel 365 实测：宽 246、行高 26、图标 16）
const CTX_W: f32 = 246.0;
const CTX_ROW_H: f32 = 26.0;
const CTX_STRIP_H: f32 = 34.0;

fn ctx_menu_height(rows: &[CtxRow]) -> f32 {
    let mut h = 4.0;
    for r in rows {
        h += if r.strip {
            CTX_STRIP_H
        } else if r.is_sep() {
            8.0
        } else {
            CTX_ROW_H
        };
    }
    h + 4.0
}

