    fn open(&mut self) {
        if let Some(path) = rfd::FileDialog::new()
            .add_filter("Excel", &["xlsx", "xlsm", "xls", "ods"])
            .pick_file()
        {
            self.open_any(path);
        }
    }

    /// Ctrl+N / 开始页“新建”：开始页直接进空白文档，否则在新标签里开一份空白。
    fn new_document(&mut self) {
        if self.show_start {
            self.show_start = false;
            self.tabs = vec![TabSlot::Active];
            self.active_tab = 0;
            self.wb = Workbook::new_blank();
            self.manual_calc = false;
            self.reset_editor_state();
        } else {
            self.open_in_new_tab(PathBuf::new());
        }
    }

    /// Ctrl+O / 开始页“打开”：选择文件并在新标签里打开。
    /// 无界面验收可用 SC_OPEN_PATH=路径 只替换系统对话框。
    fn open_dialog(&mut self) {
        let picked = match std::env::var("SC_OPEN_PATH") {
            Ok(p) if !p.trim().is_empty() => Some(PathBuf::from(p)),
            _ => rfd::FileDialog::new()
                .add_filter("Excel 工作簿", &["xlsx", "xlsm", "csv"])
                .pick_file(),
        };
        if let Some(p) = picked {
            self.show_start = false;
            if self.tabs.is_empty() {
                self.tabs = vec![TabSlot::Active];
                self.active_tab = 0;
            }
            self.open_in_new_tab(p);
        }
    }

    /// 打开文件：当前是「没动过的空白标签」就复用，否则开新标签（WPS 的行为）
    fn open_any(&mut self, path: PathBuf) {
        let untouched_blank = self.tabs.len() == 1
            && self.wb.path.is_none()
            && !self.wb.dirty
            && self.wb.sheets.len() == 1
            && self.wb.sheet(0).used_bounds().is_none();
        if untouched_blank {
            self.open_path(path);
        } else {
            self.open_in_new_tab(path);
        }
    }

    fn open_path(&mut self, path: PathBuf) {
        if sheetcore::crypto::needs_password(&path) {
            if let Ok(pw) = std::env::var("SC_PASSWORD") {
                self.open_path_with_password(path, pw);
                return;
            }
            self.pw_prompt = Some((path, String::new(), String::new()));
            return;
        }
        self.open_path_plain(path);
    }

    fn open_path_plain(&mut self, path: PathBuf) {
        // Keep the saving document alive, including its result/error channel.
        if self.tasks.saving.is_some() {
            self.open_in_new_tab(path);
            return;
        }
        self.reset_editor_state();
        self.tasks = DocumentTasks::default();
        let (tx, rx) = std::sync::mpsc::channel();
        self.tasks.open_rx = Some(rx);
        self.tasks.busy = true;
        self.status = format!("正在打开 {}…", path.display());
        std::thread::spawn(move || {
            let tx2 = tx.clone();
            let r = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
            let prof = std::env::var("SC_LOAD_PROF").is_ok();
            let t0 = std::time::Instant::now();
            match sheetcore::xlsx::load_diag(&path) {
                Ok((wb, diag)) => {
                    if prof {
                        eprintln!("[open] load {:.2}s", t0.elapsed().as_secs_f64());
                    }
                    let cells: usize = wb.sheets.iter().map(|s| s.len()).sum();
                    let formulas: usize = wb
                        .sheets
                        .iter()
                        .map(|s| s.iter().filter(|(_, c)| c.formula.is_some()).count())
                        .sum();
                    let big_cells = std::env::var("SC_BIG_CELLS")
                        .ok()
                        .and_then(|v| v.parse().ok())
                        .unwrap_or(400_000usize);
                    let big_formulas = std::env::var("SC_BIG_FORMULAS")
                        .ok()
                        .and_then(|v| v.parse().ok())
                        .unwrap_or(30_000usize);
                    let big = std::env::var("SC_FORCE_RECALC").is_err()
                        && (cells > big_cells || formulas > big_formulas);
                    if big {
                        // 大文件：缓存值是 Excel 上次算好的，先不重算。
                        // 依赖图只需要公式文本，用轻量骨架算，避免整份 clone 把内存翻倍。
                        let t = std::time::Instant::now();
                        let skeleton = formula_skeleton(&wb);
                        if prof {
                            eprintln!(
                                "[open] 骨架 {:.2}s（{} 个公式）",
                                t.elapsed().as_secs_f64(),
                                skeleton.sheets.iter().map(|s| s.len()).sum::<usize>()
                            );
                        }
                        let _ = tx.send(OpenMsg::Loaded(Box::new(wb), true, Box::new(diag.clone())));
                        let t = std::time::Instant::now();
                        let deps = sheetcore::formula::deps::Deps::build(&skeleton);
                        drop(skeleton);
                        if prof {
                            eprintln!("[open] deps {:.2}s（大文件，跳过重算）", t.elapsed().as_secs_f64());
                        }
                        let _ = tx.send(OpenMsg::DepsReady(Box::new(deps)));
                        return;
                    }
                    // 小文件：克隆一份给界面先画，原份留在后台重算
                    let t = std::time::Instant::now();
                    let _ = tx.send(OpenMsg::Loaded(Box::new(wb.clone()), false, Box::new(diag.clone())));
                    if prof {
                        eprintln!("[open] clone+send {:.2}s", t.elapsed().as_secs_f64());
                    }
                    let mut wb2 = wb;
                    let t = std::time::Instant::now();
                    if !wb2.calc_manual {
                        sheetcore::formula::recalc_all(&mut wb2);
                    }
                    if prof {
                        eprintln!("[open] recalc {:.2}s", t.elapsed().as_secs_f64());
                    }
                    let t = std::time::Instant::now();
                    let deps = sheetcore::formula::deps::Deps::build(&wb2);
                    if prof {
                        eprintln!("[open] deps {:.2}s", t.elapsed().as_secs_f64());
                    }
                    let _ = tx.send(OpenMsg::Recalced(Box::new(wb2), Box::new(deps)));
                }
                Err(e) => {
                    let _ = tx.send(OpenMsg::Failed(format!("打开失败: {e:#}")));
                }
            }
                    }));
            if let Err(p) = r {
                let msg = p
                    .downcast_ref::<&str>()
                    .map(|x| x.to_string())
                    .or_else(|| p.downcast_ref::<String>().cloned())
                    .unwrap_or_else(|| "未知 panic".to_string());
                let _ = tx2.send(OpenMsg::Failed(format!(
                    "打开失败：加载线程异常退出（panic）：{msg}"
                )));
            }
});
    }

    fn open_path_with_password(&mut self, path: PathBuf, pw: String) {
        self.reset_editor_state();
        self.tasks = DocumentTasks::default();
        let (tx, rx) = std::sync::mpsc::channel();
        self.tasks.open_rx = Some(rx);
        self.tasks.busy = true;
        self.status = format!("正在解密 {}…", path.display());
        std::thread::spawn(move || {
            match sheetcore::xlsx::load_with_password_diag(&path, &pw) {
                Ok((wb, diag)) => {
                    let _ = tx.send(OpenMsg::Loaded(Box::new(wb.clone()), false, Box::new(diag)));
                    let mut wb2 = wb;
                    if !wb2.calc_manual {
                        sheetcore::formula::recalc_all(&mut wb2);
                    }
                    let deps = sheetcore::formula::deps::Deps::build(&wb2);
                    let _ = tx.send(OpenMsg::Recalced(Box::new(wb2), Box::new(deps)));
                }
                Err(e) => {
                    let _ = tx.send(OpenMsg::Failed(format!("打开失败: {e:#}")));
                }
            }
        });
    }

    /// 手动全量重算：复制一份到后台算，界面不冻结。
    /// 显式 F9/“开始计算”必须绕过 calcMode=manual；算完仍保留手动模式标记。
    fn recalc_all_async(&mut self) {
        self.recalc_async(None);
    }

    /// “计算工作表”：只把当前表及其下游拉进重算范围。
    fn recalc_sheet_async(&mut self, sheet: usize) {
        self.recalc_async(Some(sheet));
    }

    fn recalc_async(&mut self, sheet: Option<usize>) {
        if self.tasks.open_rx.is_some() || self.tasks.busy {
            self.status = "正在加载或重算，稍后再试".into();
            return;
        }
        let wb = self.wb.clone();
        let epoch = self.wb_epoch;
        let (tx, rx) = std::sync::mpsc::channel();
        self.tasks.open_rx = Some(rx);
        self.tasks.busy = true;
        self.status = match sheet {
            Some(_) => "正在后台重算当前工作表…".into(),
            None => "正在后台重算全部公式…".into(),
        };
        std::thread::spawn(move || {
            let mut wb = wb;
            let manual = wb.calc_manual;
            wb.calc_manual = false;
            match sheet {
                Some(si) => { sheetcore::formula::recalc_sheet(&mut wb, si); }
                None => sheetcore::formula::recalc_all_force(&mut wb),
            }
            wb.calc_manual = manual;
            // 单表重算只清该表；全量重算由 recalc_all_force 清空。
            let deps = sheetcore::formula::deps::Deps::build(&wb);
            let _ = tx.send(OpenMsg::RecalcedWb(Box::new(wb), Box::new(deps), epoch));
        });
    }

    /// 打开不完整时的「加载问题」窗口：把每处问题、丢了什么、在哪个部件都列出来。
    fn load_diag_ui(&mut self, ctx: &egui::Context) {
        let Some(diag) = self.load_diag.clone() else {
            self.show_load_diag = false;
            return;
        };
        if diag.is_complete() {
            self.show_load_diag = false;
            return;
        }
        let mut open = self.show_load_diag;
        let mut close = false;
        let fatal = diag.problems.iter().filter(|p| p.fatal).count();
        egui::Window::new("加载问题")
            .open(&mut open)
            .resizable(true)
            .default_width(560.0)
            .show(ctx, |ui| {
                if fatal > 0 {
                    ui.colored_label(
                        egui::Color32::from_rgb(200, 60, 40),
                        format!("这个工作簿没有完整读入：{} 处问题，其中 {fatal} 处会丢数据。", diag.problems.len()),
                    );
                    ui.label("已禁止覆盖保存；需要保留当前内容请用「另存抢救副本」。");
                } else {
                    ui.label(format!("打开时有 {} 处读取问题（不影响保存）。", diag.problems.len()));
                }
                ui.separator();
                egui::ScrollArea::vertical().max_height(260.0).show(ui, |ui| {
                    for p in &diag.problems {
                        let head = format!(
                            "{}{} · {}",
                            p.sheet.as_deref().map(|s| format!("[{s}] ")).unwrap_or_default(),
                            p.what,
                            if p.fatal { "（致命）" } else { "" }
                        );
                        ui.label(egui::RichText::new(head).strong());
                        ui.label(format!("部件：{}", p.part));
                        ui.label(format!("详情：{}", p.detail));
                        ui.add_space(6.0);
                    }
                });
                ui.separator();
                ui.horizontal(|ui| {
                    if ui.button("另存抢救副本…").clicked() {
                        self.save(true);
                        self.show_load_diag = false;
                        close = true;
                    }
                    if ui.button("关闭").clicked() {
                        close = true;
                    }
                });
            });
        self.show_load_diag = open && !close;
    }

    /// 打开密码框：验证后走解密加载
    fn password_prompt_ui(&mut self, ctx: &egui::Context) {
        if self.pw_prompt.is_none() {
            return;
        }
        let mut open = true;
        let mut go = false;
        let mut close = false;
        let path_name = self
            .pw_prompt
            .as_ref()
            .and_then(|(p, _, _)| p.file_name())
            .map(|s| s.to_string_lossy().to_string())
            .unwrap_or_default();
        let err = self.pw_prompt.as_ref().map(|v| v.2.clone()).unwrap_or_default();
        ui_kit::window(ctx, "需要打开密码", 360.0)
            .open(&mut open)
            .show(ctx, |ui| {
                ui.label(format!("{path_name} 设置了打开密码。"));
                ui.add_space(4.0);
                let r = ui.add(
                    egui::TextEdit::singleline(&mut self.pw_prompt.as_mut().unwrap().1)
                        .password(true),
                );
                if !err.is_empty() {
                    ui.label(
                        egui::RichText::new(&err)
                            .color(Color32::from_rgb(196, 43, 28))
                            .size(12.0),
                    );
                }
                if r.lost_focus() && ui.input(|i| i.key_pressed(egui::Key::Enter)) {
                    go = true;
                }
                ui_kit::footer(ui, |ui| {
                    if ui_kit::primary_button(ui, "确定").clicked() {
                        go = true;
                    }
                    if ui_kit::secondary_button(ui, "取消").clicked() {
                        close = true;
                    }
                });
            });
        if go {
            let (path, pw, _) = self.pw_prompt.clone().unwrap();
            match sheetcore::crypto::decrypt(&path, &pw) {
                Ok(_) => {
                    self.pw_prompt = None;
                    self.open_path_with_password(path, pw);
                    return;
                }
                Err(e) => {
                    if let Some(v) = self.pw_prompt.as_mut() {
                        v.2 = format!("{e:#}");
                    }
                }
            }
        }
        if close {
            open = false;
        }
        if !open {
            self.pw_prompt = None;
        }
    }

    /// 文件→信息：设置打开密码
    fn encrypt_dialog_ui(&mut self, ctx: &egui::Context) {
        if self.enc_dlg.is_none() {
            return;
        }
        let mut open = true;
        let mut apply = false;
        let mut close = false;
        let err = self.enc_dlg.as_ref().map(|v| v.2.clone()).unwrap_or_default();
        ui_kit::window(ctx, "用密码加密", 380.0)
            .open(&mut open)
            .show(ctx, |ui| {
                ui.label("打开这个工作簿时需要输入密码；保存时写成 Office 加密文件。");
                ui.add_space(6.0);
                ui.label("密码");
                ui.add(
                    egui::TextEdit::singleline(&mut self.enc_dlg.as_mut().unwrap().0)
                        .password(true),
                );
                ui.label("确认密码");
                let r = ui.add(
                    egui::TextEdit::singleline(&mut self.enc_dlg.as_mut().unwrap().1)
                        .password(true),
                );
                if !err.is_empty() {
                    ui.label(
                        egui::RichText::new(&err)
                            .color(Color32::from_rgb(196, 43, 28))
                            .size(12.0),
                    );
                }
                if r.lost_focus() && ui.input(|i| i.key_pressed(egui::Key::Enter)) {
                    apply = true;
                }
                ui_kit::footer(ui, |ui| {
                    if ui_kit::primary_button(ui, "确定").clicked() {
                        apply = true;
                    }
                    if ui_kit::secondary_button(ui, "取消").clicked() {
                        close = true;
                    }
                });
            });
        if apply {
            let (pw, confirm, _) = self.enc_dlg.clone().unwrap();
            if pw.is_empty() {
                if let Some(v) = self.enc_dlg.as_mut() {
                    v.2 = "密码不能为空".into();
                }
            } else if pw != confirm {
                if let Some(v) = self.enc_dlg.as_mut() {
                    v.2 = "两次输入的密码不一致".into();
                }
            } else {
                self.wb.encryption = Some(sheetcore::crypto::EncryptionSettings::new(pw));
                self.wb.dirty = true;
                self.status = "已设置打开密码，保存后生效".into();
                self.enc_dlg = None;
                self.backstage = false;
                return;
            }
        }
        if close {
            open = false;
        }
        if !open {
            self.enc_dlg = None;
        }
    }

    /// 处理后台打开/重算的结果
    fn poll_open(&mut self) {
        let mut msgs: Vec<OpenMsg> = Vec::new();
        if let Some(rx) = &self.tasks.open_rx {
            while let Ok(m) = rx.try_recv() {
                msgs.push(m);
            }
        }
        let mut finished = false;
        for msg in msgs {
            match msg {
                OpenMsg::Loaded(wb, big, diag) => {
                    self.deps_pending = big;
                    let compat = diag.problems.iter().any(|p| !p.fatal && p.what == "兼容提示");
                    self.load_diag = if diag.is_complete() { None } else { Some(*diag) };
                    if self.load_diag.as_ref().is_some_and(|d| d.has_fatal()) || compat {
                        self.status = self.load_diag.as_ref().map(|d| d.summary()).unwrap_or_default();
                        self.show_load_diag = true;
                    }
                    self.wb = *wb;
                    self.manual_calc = self.wb.calc_manual;
                    self.wb.calc_pending = false;
                    self.wb_epoch += 1;
                    self.deps = sheetcore::formula::deps::Deps::empty();
                    self.sheet_idx = 0;
                    // 调试：SC_SEL=r,c 时保留启动时的选区，便于无界面验证
                    if std::env::var("SC_SEL").is_err() {
                        self.sel = (0, 0);
                    } else {
                        self.ensure_visible();
                    }
                    self.scroll = Vec2::ZERO;
                    self.cancel_edit();
                    self.doc_gen = 0;
                    if let Some(p) = self.wb.path.clone() {
                        recent::touch(&p);
                        self.tree.set_recent(recent::load());
                        // 命令行可能给的是相对路径，文件树要用绝对路径才能挂到盘符下面
                        let abs = plain_path(&p);
                        self.tree.set_current(Some(abs.clone()));
                        self.tree.locate(&abs);
                    }
                    self.rev = self
                        .wb
                        .path
                        .as_ref()
                        .map(|p| sheetcore::revision::load(p, 300))
                        .unwrap_or_default();
                    // 工作表视图（存在本机，按文件路径分）
                    self.views = ui_prefs::load_views(&self.views_key());
                    self.view_active = None;
                    let n: usize = self.wb.sheets.iter().map(|s| s.len()).sum();
                    self.status = if self.manual_calc {
                        format!("已打开（{n} 个非空格，手动计算：按 F9 重算）")
                    } else {
                        format!("已打开（{n} 个非空格），正在后台重算…")
                    };
                    // 不完整时必须压过普通提示：用户第一眼就要知道这份文件没读全
                    if self.load_diag.as_ref().is_some_and(|d| d.has_fatal()) {
                        self.status = self.load_diag.as_ref().map(|d| d.summary()).unwrap_or_default();
                        self.show_load_diag = true;
                    }
                    eprintln!(
                        "[open] 已显示缓存值 {n} 格，距启动 {}ms",
                        self.t0.elapsed().as_millis()
                    );
                    // 无界面验收钩子：SC_FONT=字体名 把字体套到当前选区（走真实的 apply_style，
                    // 含样式去重、撤销事务、协作广播），SC_SAVE=路径 立刻另存一份
                    // 无界面验收：SC_XLINK_REFRESH=1 打开后立刻更新外部链接并重算
                    if std::env::var("SC_XLINK_REFRESH").is_ok() && !self.wb.links.is_empty() {
                        let rep = sheetcore::xlinks::refresh(&mut self.wb);
                        sheetcore::formula::recalc_all(&mut self.wb);
                        // 让还在路上的后台重算作废，别拿旧快照盖掉刷新结果
                        self.doc_gen = self.doc_gen.wrapping_add(1);
                        eprintln!(
                            "[xlink] 更新 {} 个，失败 {:?}，A1={:?}",
                            rep.ok,
                            rep.failed,
                            self.wb.sheets[0].get(0, 0).map(|c| c.value.display())
                        );
                    }
                    // 无界面验收：SC_TRACE=prec|dep 打开后直接画追踪箭头；SC_SHOW_FORMULAS=1 显示公式
                    match std::env::var("SC_TRACE").as_deref() {
                        Ok("prec") => {
                            if let Ok(v) = std::env::var("SC_SEL") {
                                if let Some((a, b)) = v.split_once(',') {
                                    if let (Ok(r), Ok(c)) =
                                        (a.trim().parse::<u32>(), b.trim().parse::<u32>())
                                    {
                                        self.sel = (r, c);
                                        self.sel_end = (r, c);
                                    }
                                }
                            }
                            self.trace_precedents();
                            eprintln!("[trace] arrows={}", self.trace_arrows.len());
                        }
                        Ok("outline") => {
                            let sh = self.wb.sheet(self.sheet_idx);
                            eprintln!(
                                "[outline] rows={} cols={} max={:?}",
                                sh.row_levels.len(),
                                sh.col_levels.len(),
                                sh.row_levels.values().copied().max()
                            );
                        }
                        Ok("dep") => {
                            self.trace_dependents();
                            eprintln!("[trace] arrows={}", self.trace_arrows.len());
                        }
                        _ => {}
                    }
                    if std::env::var("SC_SHOW_FORMULAS").is_ok() {
                        self.show_formulas = true;
                    }
                    // 无界面验收：SC_FILTER=1 打开后按当前区域启用筛选
                    if std::env::var("SC_FILTER").is_ok()
                        && self.wb.sheet(self.sheet_idx).filter.is_none()
                    {
                        self.start_filter();
                        eprintln!("[filter] range={:?}", self.wb.sheet(self.sheet_idx).filter.as_ref().map(|f| f.range));
                    }
                    // 无界面验收：SC_SPARK=line|column|loss 按当前选区建一条迷你图
                    if let Ok(k) = std::env::var("SC_SPARK") {
                        let kind = match k.as_str() {
                            "column" => sheetcore::sparkline::SparkKind::Column,
                            "loss" => sheetcore::sparkline::SparkKind::WinLoss,
                            _ => sheetcore::sparkline::SparkKind::Line,
                        };
                        self.spark_open_create(kind);
                        let d = self.spark_dlg.clone();
                        match d.map(|d| self.spark_commit(&d)) {
                            Some(Ok(n)) => eprintln!(
                                "[spark] 新建 {n} 条，表内共 {} 条，dirty={}",
                                self.wb.sheet(self.sheet_idx).sparklines.len(),
                                self.wb.sheet(self.sheet_idx).sparklines_dirty
                            ),
                            Some(Err(e)) => eprintln!("[spark] 失败：{e}"),
                            None => {}
                        }
                        self.spark_dlg = None;
                    }
                    // 无界面验收：SC_TEXTBOX="x,y,w,h" 在表格原点放一个文本框（文字取 SC_TB_TEXT）
                    if let Ok(spec) = std::env::var("SC_TEXTBOX") {
                        let v: Vec<f32> = spec
                            .split(',')
                            .filter_map(|x| x.trim().parse::<f32>().ok())
                            .collect();
                        if v.len() == 4 {
                            self.tb_create(v[0], v[1], v[2], v[3]);
                            let idx = self.tb_sel.unwrap_or(0);
                            if let Ok(t) = std::env::var("SC_TB_TEXT") {
                                let mut tb = self.wb.sheet(self.sheet_idx).textboxes[idx].clone();
                                tb.text = t;
                                self.tb_commit(idx, tb);
                            }
                            eprintln!(
                                "[tb] 新建 idx={idx} 共 {} 个，rect={:?}",
                                self.wb.sheet(self.sheet_idx).textboxes.len(),
                                self.wb.sheet(self.sheet_idx).textboxes[idx].rect_px(
                                    &sheetcore::layout::Axis::new(sheetcore::layout::DEFAULT_COL_W),
                                    &sheetcore::layout::Axis::new(sheetcore::layout::DEFAULT_ROW_H)
                                )
                            );
                        }
                    }
                    if let Ok(v) = std::env::var("SC_TB_SEL") {
                        if let Ok(i) = v.parse::<usize>() {
                            self.tb_sel = Some(i);
                            eprintln!("[tb] 选中 {i}");
                        }
                    }
                    // 无界面验收：SC_TB_RECT="x,y,w,h" 改选中文本框的位置（走 set_rect_px）
                    if let Ok(spec) = std::env::var("SC_TB_RECT") {
                        let v: Vec<f32> = spec
                            .split(',')
                            .filter_map(|x| x.trim().parse::<f32>().ok())
                            .collect();
                        if v.len() == 4 {
                            if let Some(i) = self.tb_sel {
                                let before = self.wb.sheet(self.sheet_idx).textboxes.clone();
                                let (cols, rows) = self.view_axes();
                                {
                                    let sh = self.wb.sheet_mut(self.sheet_idx);
                                    if let Some(tb) = sh.textboxes.get_mut(i) {
                                        tb.set_rect_px(&cols, &rows, v[0], v[1], v[2], v[3]);
                                        sh.textboxes_dirty = true;
                                    }
                                }
                                let after = self.wb.sheet(self.sheet_idx).textboxes.clone();
                                self.wb.dirty = true;
                                self.doc_gen = self.doc_gen.wrapping_add(1);
                                self.undo.push(sheetcore::undo::Action {
                                    label: "移动文本框".into(),
                                    merges: None,
                                    deltas: Vec::new(),
                                    focus: (self.sheet_idx, self.sel.0, self.sel.1),
                                    snap_before: None,
                                    snap_after: None,
                                    by_site: 0,
                                    shapes: Some(sheetcore::undo::ShapeEdit {
                                        sheet: self.sheet_idx,
                                        before,
                                        after,
                                    }),
                                    refresh_sizes: None,
                                });
                                eprintln!("[tb] 改位置 {spec}");
                            }
                        }
                    }
                    // 无界面验收：SC_HIDE_SHEET=n 隐藏第 n 张表；SC_UNHIDE=1 打开取消隐藏窗口
                    if let Ok(v) = std::env::var("SC_HIDE_SHEET") {
                        if let Ok(i) = v.parse::<usize>() {
                            if i < self.wb.sheets.len() {
                                self.sheet_idx = i;
                                self.hide_current_sheet();
                                eprintln!(
                                    "[hide] {} 隐藏={:?} 当前={}",
                                    i,
                                    self.wb.sheets.iter().map(|s| s.hidden).collect::<Vec<_>>(),
                                    self.sheet_idx
                                );
                            }
                        }
                    }
                    if std::env::var("SC_UNHIDE").is_ok() {
                        self.unhide_open = true;
                        eprintln!(
                            "[unhide] 隐藏表={:?}",
                            self.wb
                                .sheets
                                .iter()
                                .filter(|s| s.hidden)
                                .map(|s| s.name.clone())
                                .collect::<Vec<_>>()
                        );
                    }
                    // 无界面验收：SC_ACTIVE_SHEET=n 切到第 n 张表（0 起）
                    if let Ok(v) = std::env::var("SC_ACTIVE_SHEET") {
                        if let Ok(i) = v.parse::<usize>() {
                            if i < self.wb.sheets.len() {
                                self.sheet_idx = i;
                                eprintln!("[sheet] 切到 {i}（{}）", self.wb.sheets[i].name);
                            }
                        }
                    }
                    // 无界面验收：SC_VIEW_NEW=名字 存一个视图；SC_VIEW_SWITCH=n 切到第 n 个视图
                    if let Ok(name) = std::env::var("SC_VIEW_NEW") {
                        let v = self.view_capture(&name);
                        self.views.retain(|x| x.name != v.name);
                        self.views.push(v);
                        ui_prefs::save_views(&self.views_key(), &self.views);
                        self.status = format!("已保存视图「{name}」");
                        eprintln!(
                            "[view] 新建「{name}」 共 {} 个（文件 {}）",
                            self.views.len(),
                            self.views_key()
                        );
                    }
                    // 无界面验收：SC_VIEW_SWITCH=n 应用第 n 个视图（视图从本机按文件恢复）
                    if let Ok(v) = std::env::var("SC_VIEW_SWITCH") {
                        if let Ok(i) = v.parse::<usize>() {
                            eprintln!(
                                "[view] 载入 {} 个视图：{:?}",
                                self.views.len(),
                                self.views.iter().map(|x| x.name.clone()).collect::<Vec<_>>()
                            );
                            self.view_apply(i);
                            eprintln!(
                                "[view] 应用后 zoom={:.2} freeze={:?} sheet={} sel={:?}",
                                self.zoom,
                                self.wb.sheet(self.sheet_idx).freeze,
                                self.sheet_idx,
                                self.sel
                            );
                        }
                    }
                    // 无界面验收：数据分析四件套
                    if let Ok(spec) = std::env::var("SC_FORECAST") {
                        let mut it = spec.split(',');
                        let range = it.next().unwrap_or("").trim().to_string();
                        let periods = it
                            .next()
                            .and_then(|v| v.trim().parse::<u32>().ok())
                            .unwrap_or(6);
                        match self.forecast_run(&range, periods) {
                            Ok(s) => eprintln!("[forecast] {s}"),
                            Err(e) => eprintln!("[forecast] 失败：{e}"),
                        }
                    }
                    if let Ok(spec) = std::env::var("SC_SUBTOTAL") {
                        let v: Vec<&str> = spec.split(',').collect();
                        if v.len() >= 3 {
                            let f = match v.get(3).map(|s| s.trim()) {
                                Some("avg") => sheetcore::subtotal::SubFn::Average,
                                Some("count") => sheetcore::subtotal::SubFn::Count,
                                Some("max") => sheetcore::subtotal::SubFn::Max,
                                Some("min") => sheetcore::subtotal::SubFn::Min,
                                _ => sheetcore::subtotal::SubFn::Sum,
                            };
                            match self.subtotal_run(v[0].trim(), v[1].trim(), v[2].trim(), f) {
                                Ok(s) => eprintln!("[subtotal] {s}"),
                                Err(e) => eprintln!("[subtotal] 失败：{e}"),
                            }
                        }
                    }
                    if let Ok(spec) = std::env::var("SC_FLASHFILL") {
                        let v: Vec<&str> = spec.split(',').collect();
                        if v.len() >= 3 {
                            match self.flashfill_run(
                                v[0].trim(),
                                v[1].trim(),
                                v[2].trim(),
                                v.get(3).map(|s| s.trim()).unwrap_or(""),
                            ) {
                                Ok(s) => eprintln!("[flashfill] {s}"),
                                Err(e) => eprintln!("[flashfill] 失败：{e}"),
                            }
                        }
                    }
                    if let Ok(spec) = std::env::var("SC_CONSOLIDATE") {
                        // 函数;引用(用 | 分隔多行);行标签;列标签
                        let v: Vec<&str> = spec.split(';').collect();
                        if v.len() >= 2 {
                            let f = match v[0].trim() {
                                "avg" => sheetcore::consolidate::ConsFn::Average,
                                "count" => sheetcore::consolidate::ConsFn::Count,
                                "max" => sheetcore::consolidate::ConsFn::Max,
                                "min" => sheetcore::consolidate::ConsFn::Min,
                                _ => sheetcore::consolidate::ConsFn::Sum,
                            };
                            let src = v[1].replace('|', "\n");
                            let row = v.get(2).map(|s| s.trim() != "0").unwrap_or(true);
                            let col = v.get(3).map(|s| s.trim() != "0").unwrap_or(true);
                            match self.consolidate_run(&src, f, row, col) {
                                Ok(s) => eprintln!("[consolidate] {s}"),
                                Err(e) => eprintln!("[consolidate] 失败：{e}"),
                            }
                        }
                    }
                    // 无界面验收：SC_PIVOT="源区域" 直接生成透视表；SC_SLICER=1 再开切片器
                    if let Ok(spec) = std::env::var("SC_PIVOT") {
                        let rect = SheetApp::parse_rect(&spec).or_else(|| {
                            let (r, c) = self.sel;
                            Some((r, c, r + 20, c + 12))
                        });
                        if let Some(src) = rect {
                            let p = sheetcore::pivot::PivotSpec {
                                source: src,
                                row_field: src.1,
                                col_field: None,
                                value_field: src.3,
                                agg: sheetcore::pivot::Agg::Sum,
                                group: sheetcore::pivot::GroupBy::None,
                                exclude: Vec::new(),
                            };
                            let at = (src.2 + 2, src.1);
                            self.sel = at;
                            self.generate_pivot(&p);
                            eprintln!(
                                "[pivot] 生成 rect={:?} 规格={:?}",
                                self.pivot_last.as_ref().map(|x| x.2),
                                self.pivot_last.is_some()
                            );
                        }
                    }
                    if std::env::var("SC_SLICER").is_ok() {
                        self.slicer_open();
                        eprintln!(
                            "[slicer] 面板={} 项={:?}",
                            self.slicer.is_some(),
                            self.slicer
                                .as_ref()
                                .map(|s| (s.field.clone(), s.items.len()))
                        );
                        // SC_SLICER_OFF=\"甲,乙\" 模拟取消勾选后应用
                        if let Ok(off) = std::env::var("SC_SLICER_OFF") {
                            if let Some(s) = self.slicer.as_mut() {
                                for name in off.split(',') {
                                    let name = name.trim();
                                    for (v, on) in s.items.iter_mut() {
                                        if v == name {
                                            *on = false;
                                        }
                                    }
                                }
                            }
                            self.slicer_apply();
                            eprintln!(
                                "[slicer] 筛掉 {:?}，透视表规格 exclude={:?}",
                                off,
                                self.pivot_last.as_ref().map(|x| x.1.exclude.clone())
                            );
                        }
                    }
                    // 无界面验收：SC_OPEN_DIALOG=format/revision/xlink 直接开对话框截图
                    match std::env::var("SC_OPEN_DIALOG").as_deref() {
                        Ok("format") => self.open_format_dialog(),
                        Ok("revision") => self.rev_open = true,
                        Ok("xlink") => self.xlink_dlg = true,
                        Ok("find") => {
                            self.find_open_new_session();
                        }
                        Ok("cf") => self.cf_mgr = true,
                        Ok("chart") => {
                            self.chart_mgr = true;
                            self.reload_charts();
                        }
                        Ok("about") => self.about_open = true,
                        Ok("spark") => self.spark_open_create(
                            sheetcore::sparkline::SparkKind::Line,
                        ),
                        Ok("sparkedit") => self.spark_open_edit(),
                        Ok("a11y") => {
                            self.a11y_scan();
                            self.a11y_open = true;
                            eprintln!(
                                "[a11y] {} 项：{:?}",
                                self.a11y_list.len(),
                                self.a11y_list
                                    .iter()
                                    .take(4)
                                    .map(|i| (i.sheet_name.clone(), i.kind.label(), i.detail.clone()))
                                    .collect::<Vec<_>>()
                            );
                        }
                        Ok("textbox") => {
                            if self.tb_sel.is_none() {
                                self.tb_sel = Some(0);
                            }
                            let i = self.tb_sel.unwrap_or(0);
                            self.tb_open_edit(i);
                        }
                        Ok("symbol") => self.symbol_dlg = true,
                        Ok("errors") => {
                            if std::env::var("SC_ECOPTS").is_ok() {
                                self.ec_options = true;
                            }
                            self.open_error_check();
                            match std::env::var("SC_IGNORE").as_deref() {
                                Ok("all") => {
                                    let all: Vec<(u32, u32)> =
                                        self.error_list.iter().map(|i| (i.row, i.col)).collect();
                                    let sh = self.wb.sheet_mut(self.sheet_idx);
                                    for k in &all {
                                        sh.ignored_errors.insert(*k);
                                    }
                                    sh.ignored_errors_dirty = true;
                                    let n = all.len();
                                    self.error_list.clear();
                                    eprintln!("[ignore] all n={n}");
                                }
                                Ok("sel") => {
                                    let (r, c) = self.sel;
                                    let sh = self.wb.sheet_mut(self.sheet_idx);
                                    sh.ignored_errors.insert((r, c));
                                    sh.ignored_errors_dirty = true;
                                    self.error_list =
                                        sheetcore::errors::scan_wb(&self.wb, self.sheet_idx);
                                    eprintln!("[ignore] sel={r},{c}");
                                }
                                Ok("reset") => {
                                    let sh = self.wb.sheet_mut(self.sheet_idx);
                                    sh.ignored_errors.clear();
                                    sh.ignored_errors_dirty = true;
                                    self.error_list =
                                        sheetcore::errors::scan_wb(&self.wb, self.sheet_idx);
                                    eprintln!("[ignore] reset left={}", self.error_list.len());
                                }
                                _ => {}
                            }
                        }
                        Ok("goal") => {
                            // SC_GOAL="目标格,可变格,目标值"，例如 SC_GOAL=A2,A1,150
                            if let Ok(spec) = std::env::var("SC_GOAL") {
                                let parts: Vec<&str> = spec.split(',').collect();
                                if parts.len() == 3 {
                                    let t = SheetApp::parse_addr(parts[0]);
                                    let v = SheetApp::parse_addr(parts[1]);
                                    let g = parts[2].trim().parse::<f64>();
                                    if let (Some((tr, tc)), Some((vr, vc)), Ok(g)) = (t, v, g) {
                                        match self.goal_seek_run(tr, tc, g, vr, vc) {
                                            Ok(x) => eprintln!("[goal] ok x={x}"),
                                            Err(e) => eprintln!("[goal] fail {e}"),
                                        }
                                    }
                                }
                            }
                        }
                        Ok("detail") => {
                            // SC_DETAIL="r1,r2" 收/展这一段的明细；SC_DETAIL_HIDE=0 表示展开
                            if let Ok(spec) = std::env::var("SC_DETAIL") {
                                let mut it = spec.split(',');
                                if let (Some(a0), Some(b0)) = (it.next(), it.next()) {
                                    if let (Ok(r1), Ok(r2)) =
                                        (a0.trim().parse::<u32>(), b0.trim().parse::<u32>())
                                    {
                                        self.sel = (r1, 0);
                                        self.sel_end = (r2, 0);
                                        let hide = std::env::var("SC_DETAIL_HIDE")
                                            .map(|v| v != "0")
                                            .unwrap_or(true);
                                        self.toggle_detail(hide);
                                        eprintln!(
                                            "[detail] {} hidden={:?}",
                                            self.status,
                                            {
                                                let mut v: Vec<u32> = self
                                                    .wb
                                                    .sheet(self.sheet_idx)
                                                    .hidden_rows_user
                                                    .iter()
                                                    .copied()
                                                    .collect();
                                                v.sort();
                                                v
                                            }
                                        );
                                    }
                                }
                            }
                        }
                        Ok("zhpreview") => {
                            // SC_SEL/SC_SEL2 定选区，SC_ZH_VARIANT=tw|hk 选变体
                            if let (Ok(a), Ok(b)) = (
                                std::env::var("SC_SEL"),
                                std::env::var("SC_SEL2"),
                            ) {
                                let p = |v: &str| -> Option<(u32, u32)> {
                                    let (x, y) = v.split_once(',')?;
                                    Some((x.trim().parse().ok()?, y.trim().parse().ok()?))
                                };
                                if let (Some(s0), Some(s1)) = (p(&a), p(&b)) {
                                    self.sel = s0;
                                    self.sel_end = s1;
                                }
                            }
                            self.zh_preview_all_sheets =
                                std::env::var("SC_ZH_ALL").map(|v| v == "1").unwrap_or(false);
                            self.zh_preview_sheet =
                                std::env::var("SC_ZH_SHEET").ok().and_then(|v| v.parse().ok());
                            // 没显式指定就沿用记住的变体（不覆盖）
                            if let Ok(v) = std::env::var("SC_ZH_VARIANT") {
                                self.zh_preview_variant = match v.as_str() {
                                    "tw" => sheetcore::zhconv::Variant::Taiwan,
                                    "hk" => sheetcore::zhconv::Variant::HongKong,
                                    _ => sheetcore::zhconv::Variant::Generic,
                                };
                            }
                            self.zh_preview_scan();
                            self.zh_preview_dlg = true;
                            eprintln!(
                                "[zhpreview] diffs={} variant={:?}",
                                self.zh_preview.len(),
                                self.zh_preview_variant
                            );
                        }
                        Ok("level") => {
                            if let Ok(spec) = std::env::var("SC_LEVEL") {
                                let axis = spec.chars().next().unwrap_or('r');
                                let k: u8 = spec[1..].trim().parse().unwrap_or(1);
                                self.set_outline_level(axis != 'c', k);
                                eprintln!("[level] {} -> {}", spec, self.status);
                                let sh = self.wb.sheet(self.sheet_idx);
                                let mut v: Vec<u32> =
                                    sh.hidden_rows_user.iter().copied().collect();
                                v.sort();
                                let mut w: Vec<u32> =
                                    sh.hidden_cols.iter().copied().collect();
                                w.sort();
                                eprintln!("[level] hidden_rows={v:?} hidden_cols={w:?}");
                            }
                        }
                        Ok("outline_set") => {
                            self.outline_set_dlg = true;
                            if let Ok(spec) = std::env::var("SC_OUTLINE_PR") {
                                let parts: Vec<&str> = spec.split(',').collect();
                                if parts.len() >= 3 {
                                    let (b, r, sym) = (
                                        parts[0].trim() != "0",
                                        parts[1].trim() != "0",
                                        parts[2].trim() != "0",
                                    );
                                    {
                                        let sh = self.wb.sheet_mut(self.sheet_idx);
                                        sh.outline_summary_below = b;
                                        sh.outline_summary_right = r;
                                        sh.outline_symbols = sym;
                                        sh.outline_pr_dirty = true;
                                    }
                                    // 当成一次编辑：否则后台重算的结果会把整份 wb 换回去
                                    self.doc_gen = self.doc_gen.wrapping_add(1);
                                    self.wb.dirty = true;
                                    eprintln!("[outline] below={b} right={r} symbols={sym}");
                                }
                            }
                        }
                        Ok("filterdd") => {
                            // 打开 A 列的筛选下拉（截图/验收用）
                            let col: u32 = std::env::var("SC_FILTER_COL")
                                .ok()
                                .and_then(|v| v.parse().ok())
                                .unwrap_or(0);
                            if self.wb.sheet(self.sheet_idx).filter.is_none() {
                                self.start_filter();
                            }
                            // SC_FILTER_CRIT="contains,甲" / "between,1,3"
                            if let Ok(spec) = std::env::var("SC_FILTER_CRIT") {
                                let mut it = spec.split(',');
                                let op_s = it.next().unwrap_or("").trim().to_string();
                                let v1 = it.next().unwrap_or("").trim().to_string();
                                let v2 = it.next().map(|s| s.trim().to_string());
                                let op = match op_s.as_str() {
                                    "eq" => Some(sheetcore::sort_filter::CmpOp::Eq),
                                    "ne" => Some(sheetcore::sort_filter::CmpOp::Ne),
                                    "gt" => Some(sheetcore::sort_filter::CmpOp::Gt),
                                    "ge" => Some(sheetcore::sort_filter::CmpOp::Ge),
                                    "lt" => Some(sheetcore::sort_filter::CmpOp::Lt),
                                    "le" => Some(sheetcore::sort_filter::CmpOp::Le),
                                    "between" => Some(sheetcore::sort_filter::CmpOp::Between),
                                    "contains" => Some(sheetcore::sort_filter::CmpOp::Contains),
                                    "notcontains" => {
                                        Some(sheetcore::sort_filter::CmpOp::NotContains)
                                    }
                                    "begins" => Some(sheetcore::sort_filter::CmpOp::Begins),
                                    "ends" => Some(sheetcore::sort_filter::CmpOp::Ends),
                                    _ => None,
                                };
                                if let Some(op) = op {
                                    let crit = sheetcore::sort_filter::Criterion {
                                        op,
                                        val: v1,
                                        val2: v2,
                                    };
                                    {
                                        let sh = self.wb.sheet_mut(self.sheet_idx);
                                        if let Some(f) = sh.filter.as_mut() {
                                            f.criteria.insert(col, crit);
                                            f.allows.remove(&col);
                                        }
                                    }
                                    self.recalc_filter_hidden();
                                    let n = self
                                        .wb
                                        .sheet(self.sheet_idx)
                                        .hidden_rows
                                        .len();
                                    eprintln!("[filterdd] criteria {op_s} -> hidden={n}");
                                    self.wb.dirty = true;
                                }
                            }
                            if let Some(f) = self.wb.sheet(self.sheet_idx).filter.clone() {
                                let sh = self.wb.sheet(self.sheet_idx);
                                let vals =
                                    sheetcore::sort_filter::unique_values(sh, f.range, col);
                                let allowed = f.allows.get(&col).cloned();
                                let items: Vec<(String, bool)> = vals
                                    .into_iter()
                                    .map(|v| {
                                        let on = allowed
                                            .as_ref()
                                            .map(|a| a.contains(&v))
                                            .unwrap_or(true);
                                        (v, on)
                                    })
                                    .collect();
                                eprintln!(
                                    "[filterdd] col={col} items={} range={:?} crit={:?} hidden={}",
                                    items.len(),
                                    f.range,
                                    f.criteria.get(&col),
                                    self.wb.sheet(self.sheet_idx).hidden_rows.len()
                                );
                                let sh2 = self.wb.sheet(self.sheet_idx);
                                for rr in f.range.0..=f.range.2 {
                                    eprintln!("   r{rr}: {:?}", sh2.get(rr, col).map(|c| c.value.display()));
                                }
                                self.filter_popup = Some(FilterPopup {
                                    col,
                                    items,
                                    search: std::env::var("SC_FILTER_Q").unwrap_or_default(),
                                    anchor: std::env::var("SC_FILTER_AT")
                                        .ok()
                                        .and_then(|v| {
                                            let (x, y) = v.split_once(',')?;
                                            Some(egui::pos2(
                                                x.trim().parse().ok()?,
                                                y.trim().parse().ok()?,
                                            ))
                                        })
                                        .unwrap_or(egui::pos2(240.0, 236.0)),
                                    crit_dlg: None,
                                    ops_open: std::env::var("SC_FILTER_OPS")
                                        .map(|v| v == "1")
                                        .unwrap_or(false),
                                    ops_anchor: egui::pos2(482.0, 300.0),
                                });
                            }
                        }
                        Ok("proof") => {
                            if std::env::var("SC_PROOF_SEL").map(|v| v == "1").unwrap_or(false) {
                                let p = |v: &str| -> Option<(u32, u32)> {
                                    let (x, y) = v.split_once(',')?;
                                    Some((x.trim().parse().ok()?, y.trim().parse().ok()?))
                                };
                                if let (Ok(a), Ok(b)) = (
                                    std::env::var("SC_SEL"),
                                    std::env::var("SC_SEL2"),
                                ) {
                                    if let (Some(s0), Some(s1)) = (p(&a), p(&b)) {
                                        self.sel = s0;
                                        self.sel_end = s1;
                                    }
                                }
                                self.proof_only_sel = true;
                            }
                            self.open_proof();
                            if let Ok(spec) = std::env::var("SC_PROOF_DBL") {
                                if let Some((a0, b0)) = spec.split_once(',') {
                                    if let (Ok(r), Ok(c)) =
                                        (a0.trim().parse::<u32>(), b0.trim().parse::<u32>())
                                    {
                                        self.proof_fix_cells(vec![(r, c)]);
                                        eprintln!(
                                            "[proof] 双击修 {} -> issues={} status={}",
                                            cell_name(r, c),
                                            self.proof_list.len(),
                                            self.status
                                        );
                                    }
                                }
                            }
                            match std::env::var("SC_PROOF_FIX").as_deref() {
                                Ok("all") => {
                                    self.proof_apply_fix(false);
                                    eprintln!("[proof] fixed all -> {}", self.status);
                                }
                                Ok("sel") => {
                                    self.proof_apply_fix(true);
                                    eprintln!("[proof] fixed sel -> {}", self.status);
                                }
                                _ => {}
                            }
                            eprintln!("[proof] issues={} first={:?}", self.proof_list.len(), self.proof_list.first().map(|i| (i.row, i.col, i.kind)));
                        }
                        Ok("zh") => {
                            if let (Ok(sel), Ok(end)) = (
                                std::env::var("SC_SEL"),
                                std::env::var("SC_SEL2"),
                            ) {
                                let p = |v: &str| -> Option<(u32, u32)> {
                                    let (x, y) = v.split_once(',')?;
                                    Some((x.trim().parse().ok()?, y.trim().parse().ok()?))
                                };
                                if let (Some(s0), Some(s1)) = (p(&sel), p(&end)) {
                                    self.sel = s0;
                                    self.sel_end = s1;
                                }
                            }
                            let dir = std::env::var("SC_ZH").unwrap_or_default();
                            match dir.as_str() {
                                "tw" => self.zh_convert(true, sheetcore::zhconv::Variant::Taiwan),
                                "hk" => self.zh_convert(true, sheetcore::zhconv::Variant::HongKong),
                                "t" => self.zh_convert(true, sheetcore::zhconv::Variant::Generic),
                                _ => self.zh_convert(false, sheetcore::zhconv::Variant::Generic),
                            }
                            eprintln!("[zh] {}", self.status);
                        }
                        Ok("colgroup") => {
                            if let Ok(spec) = std::env::var("SC_GROUP_COLS") {
                                let mut it = spec.split(',');
                                if let (Some(a0), Some(b0)) = (it.next(), it.next()) {
                                    if let (Ok(c1), Ok(c2)) =
                                        (a0.trim().parse::<u32>(), b0.trim().parse::<u32>())
                                    {
                                        self.sel = (0, c1);
                                        self.sel_end = (1_048_575, c2);
                                        self.group_selection();
                                        if std::env::var("SC_COL_HIDE").is_ok() {
                                            self.toggle_detail(true);
                                        }
                                        eprintln!(
                                            "[colgroup] {} cols={:?}",
                                            self.status,
                                            self.wb.sheet(self.sheet_idx).col_levels.len()
                                        );
                                    }
                                }
                            }
                        }
                        Ok("addsheet") => {
                            if let Ok(name) = std::env::var("SC_ADD_SHEET") {
                                let mut sh = sheetcore::model::Sheet::new(&name);
                                sh.set(
                                    0,
                                    0,
                                    sheetcore::model::Cell {
                                        value: sheetcore::model::Value::Text("新表".into()),
                                        formula: None,
                                    },
                                );
                                let idx = self.wb.sheets.len();
                                if sheetcore::sheet_ops::insert_sheet(&mut self.wb, idx, sh) {
                                    self.sheet_idx = idx;
                                    self.finish_sheet_change();
                                    eprintln!("[addsheet] ok {name} sheets={}", self.wb.sheets.len());
                                } else {
                                    eprintln!("[addsheet] fail {name}");
                                }
                            }
                        }
                        Ok("scen") => {
                            self.scen_dlg = true;
                            // SC_SCEN_ADD="名称:A1:B1" 保存方案；SC_SCEN_SHOW=名称 应用；SC_SCEN_SUMMARY=1 生成摘要
                            if let Ok(spec) = std::env::var("SC_SCEN_ADD") {
                                if let Some((name, range)) = spec.split_once(':') {
                                    if let Some(r) = SheetApp::parse_rect(range) {
                                        let sc = sheetcore::scenarios::capture(
                                            self.wb.sheet(self.sheet_idx),
                                            name,
                                            "",
                                            r,
                                        );
                                        let n = sc.cells.len();
                                        let sh = self.wb.sheet_mut(self.sheet_idx);
                                        sh.scenarios.push(sc);
                                        sh.scenarios_dirty = true;
                                        eprintln!("[scen] added {name} cells={n}");
                                    } else {
                                        eprintln!("[scen] bad range {range}");
                                    }
                                }
                            }
                            if let Ok(name) = std::env::var("SC_SCEN_SHOW") {
                                let sc = self
                                    .wb
                                    .sheet(self.sheet_idx)
                                    .scenarios
                                    .iter()
                                    .find(|x| x.name == name)
                                    .cloned();
                                match sc {
                                    Some(sc) => {
                                        for ((r, c), v) in &sc.cells {
                                            let val = sheetcore::scenarios::apply_value(v);
                                            let sh = self.wb.sheet_mut(self.sheet_idx);
                                            let mut cell = sh.get(*r, *c).cloned().unwrap_or_default();
                                            cell.value = val;
                                            cell.formula = None;
                                            sh.set(*r, *c, cell);
                                        }
                                        sheetcore::formula::recalc_all(&mut self.wb);
                                        eprintln!("[scen] shown {name}");
                                    }
                                    None => eprintln!("[scen] not found {name}"),
                                }
                            }
                            if std::env::var("SC_SCEN_SUMMARY").is_ok() {
                                let res = std::env::var("SC_SCEN_RESULTS")
                                    .ok()
                                    .and_then(|v| SheetApp::parse_rect(&v));
                                match self.build_scenario_summary(res) {
                                    Ok(n) => eprintln!("[scen] summary sheet {n}"),
                                    Err(e) => eprintln!("[scen] summary fail {e}"),
                                }
                            }
                        }
                        Ok("dtable") => {
                            // SC_SEL=r,c 起点、SC_SEL2=r2,c2 终点
                            if let (Ok(a1), Ok(a2)) = (
                                std::env::var("SC_SEL"),
                                std::env::var("SC_SEL2"),
                            ) {
                                let pa = |v: &str| -> Option<(u32, u32)> {
                                    let (x, y) = v.split_once(',')?;
                                    Some((x.trim().parse().ok()?, y.trim().parse().ok()?))
                                };
                                if let (Some(s0), Some(s1)) = (pa(&a1), pa(&a2)) {
                                    self.sel = s0;
                                    self.sel_end = s1;
                                }
                            }
                            if let Ok(spec) = std::env::var("SC_DTABLE") {
                                let mut it = spec.split(',');
                                let col_in = it.next().and_then(|v| SheetApp::parse_addr(v));
                                let row_in = it.next().and_then(|v| SheetApp::parse_addr(v));
                                match self.data_table_run(row_in, col_in) {
                                    Ok((label, n)) => eprintln!("[dtable] {label} filled {n}"),
                                    Err(e) => eprintln!("[dtable] fail {e}"),
                                }
                            }
                        }
                        _ => {}
                    }
                    // 无界面验收：SC_REV_REVERT=N 撤回倒数第 N 条修订
                    if let Ok(v) = std::env::var("SC_REV_REVERT") {
                        if let Ok(n) = v.parse::<usize>() {
                            let idx = self.rev.len().saturating_sub(n.max(1));
                            self.revert_revision(idx);
                            eprintln!("[rev] 撤回倒数第 {n} 条（索引 {idx}），共 {} 条", self.rev.len());
                        }
                    }
                    if let Ok(font) = std::env::var("SC_FONT") {
                        let font = font.trim().to_string();
                        self.apply_style(move |s| s.font = font.clone());
                        eprintln!("[font] 选区已套用字体 {:?}", self.current_style().font);
                    }
                    // 无界面验收：SC_UNDERLINE=1 给选区加下划线（同样的 apply_style 通路）
                    if std::env::var("SC_UNDERLINE").is_ok() {
                        self.apply_style(|s| s.underline = true);
                        eprintln!("[ul] 选区下划线={}", self.current_style().underline);
                    }
                    // 无界面验收：SC_DRAG=r1,c1,r2,c2,dr,dc[,copy] 直接走「拖动边框移动/复制」
                    if let Ok(spec) = std::env::var("SC_DRAG") {
                        let v: Vec<i64> = spec
                            .split(',')
                            .filter_map(|x| x.trim().parse::<i64>().ok())
                            .collect();
                        if v.len() >= 6 {
                            self.sel = (v[0].max(0) as u32, v[1].max(0) as u32);
                            self.sel_end = (v[2].max(0) as u32, v[3].max(0) as u32);
                            let (dr, dc) = (v[4], v[5]);
                            let mode = spec.split(',').nth(6).map(|s| s.trim().to_string()).unwrap_or_default();
                            match mode.as_str() {
                                "1" => self.copy_selection_by(dr, dc),
                                "2" => self.shift_insert_by(dr, dc),
                                _ => self.move_selection_by(dr, dc),
                            }
                            eprintln!("[drag] {} -> {}", spec, self.status);
                            let sh = self.wb.sheet(self.sheet_idx);
                            eprintln!(
                                "[drag] 源A1={:?} 目标={:?}",
                                sh.get(0, 0).map(|c| c.value.display()),
                                sh.get(
                                    (v[2].max(0) as i64 + dr).max(0) as u32,
                                    (v[3].max(0) as i64 + dc).max(0) as u32
                                )
                                .map(|c| c.value.display())
                            );
                        }
                    }
                    // 无界面验收：SC_AUTOFIT="c:1" 或 "r:2"（0 基），跑自适应并打印前后尺寸
                    if let Ok(spec) = std::env::var("SC_AUTOFIT") {
                        let parts: Vec<&str> = spec.split(':').collect();
                        if parts.len() == 2 {
                            if let Ok(idx) = parts[1].trim().parse::<u32>() {
                                let before = if parts[0].trim() == "c" {
                                    self.wb.sheet(self.sheet_idx).cols.size(idx)
                                } else {
                                    self.wb.sheet(self.sheet_idx).rows.size(idx)
                                };
                                self.pending_autofit = Some((parts[0].trim() == "c", idx));
                                eprintln!("[autofit] 登记 {spec} 原尺寸 {before:.0}");
                            }
                        }
                    }
                    if let Ok(out) = std::env::var("SC_SAVE") {
                        let target = PathBuf::from(&out);
                        // 基准沿用打开时的原文件（和另存为的语义一致），不覆盖 wb.path
                        let wb = self.wb.clone();
                        let ts = std::time::Instant::now();
                        match sheetcore::xlsx::save_atomic(&target, &wb) {
                            Ok(()) => eprintln!(
                                "[save] 测试钩子已存 {}（{}ms）",
                                target.display(),
                                ts.elapsed().as_millis()
                            ),
                            Err(e) => eprintln!("[save] 测试钩子失败 {e:#}"),
                        }
                    }
                    if self.tasks.pending_host {
                        self.tasks.pending_host = false;
                        self.start_host();
                    } else if let Some(addr) = self.tasks.pending_join.take() {
                        self.join_addr = addr;
                        self.join_shared();
                    } else {
                        // 没指定角色：看看文件旁边有没有同事留下的占用卡
                        self.try_auto_join();
                    }
                }
                OpenMsg::RecalcedWb(wb, deps, epoch) => {
                    self.tasks.busy = false;
                    if epoch == self.wb_epoch {
                        self.wb = *wb;
                        self.manual_calc = self.wb.calc_manual;
                        self.wb_epoch += 1;
                        self.deps = *deps;
                        self.cf_stats_gen = u64::MAX;
                        self.doc_gen = self.doc_gen.wrapping_add(1);
                        self.status = if self.manual_calc {
                            "重算完成（仍为手动计算模式）".into()
                        } else {
                            "重算全部完成".into()
                        };
                        eprintln!("[open] 手动重算完成");
                    } else {
                        self.status = "重算结果已过期（期间有编辑），已丢弃".into();
                    }
                    finished = true;
                    continue;
                }
                OpenMsg::DepsReady(deps) => {
                    self.deps = *deps;
                    self.deps_pending = false;
                    self.tasks.busy = false;
                    self.status = "已打开大文件（显示文件里的缓存值；公式→重算全部 可强制重算）".into();
                    eprintln!("[open] 大文件：已准备依赖图，跳过全量重算");
                    finished = true;
                    continue;
                }
                OpenMsg::Recalced(wb, deps) => {
                    self.deps_pending = false;
                    self.wb_epoch += 1;
                    // 整份替换后条件格式统计必须重算，否则色阶/图标/数据条全空
                    self.cf_stats_gen = u64::MAX;
                    if self.doc_gen != 0 {
                        // 期间用户改过：保留用户结果，等空闲再补一次全量
                        self.tasks.needs_full = true;
                        self.tasks.busy = false;
                        self.deps = sheetcore::formula::deps::Deps::build(&self.wb);
                        self.status = "已打开；因期间有编辑，稍后会自动补算一次".into();
                        eprintln!("[open] 丢弃后台结果（期间有编辑），等空闲补算");
                        finished = true;
                        continue;
                    }
                    // Calculation owns values, not the live document's identity
                    // or save state (Save As may have completed meanwhile).
                    let path = self.wb.path.clone();
                    let dirty = self.wb.dirty;
                    self.wb = *wb;
                    self.wb.path = path;
                    self.wb.dirty = dirty;
                    self.manual_calc = self.wb.calc_manual;
                    self.deps = *deps;
                    self.tasks.busy = false;
                    self.tasks.needs_full = false;
                    finished = true;
                    let n: usize = self.wb.sheets.iter().map(|s| s.len()).sum();
                    self.status = if self.load_diag.as_ref().is_some_and(|d| d.has_fatal()) {
                        self.load_diag.as_ref().map(|d| d.summary()).unwrap_or_default()
                    } else if self.manual_calc {
                        format!("已打开（{n} 个非空格，手动计算：按 F9 重算）")
                    } else {
                        format!("已打开并重算完成（{n} 个非空格）")
                    };
                    eprintln!("[open] 后台重算完成 {n} 格");
                    if std::env::var("SC_FILTER").is_ok()
                        && self.wb.sheet(self.sheet_idx).filter.is_none()
                    {
                        self.start_filter();
                    }
                }
                OpenMsg::Failed(e) => {
                    self.status = e;
                    self.tasks.busy = false;
                    // A failed replacement leaves the previous workbook visible.
                    self.deps = sheetcore::formula::deps::Deps::build(&self.wb);
                    finished = true;
                }
            }
        }
        if finished {
            self.tasks.open_rx = None;
        }
    }

    fn save(&mut self, force_dialog: bool) {
        // C14：打开时有关键部件没读出来（公式/样式/整张表），就地覆盖会把"没读到的东西"
        // 永久写没。只读查看和「另存为抢救副本」仍然允许。
        if !force_dialog && self.wb.path.is_some() {
            if let Some(d) = self.load_diag.as_ref().filter(|d| d.has_fatal()) {
                self.status = format!(
                    "打开不完整，已禁止覆盖保存：{}。请用「另存为」保存抢救副本",
                    d.summary()
                );
                return;
            }
        }
        if self.tasks.saving.is_some() {
            self.status = "上一次保存还没完成…".into();
            return;
        }
        if self.tasks.open_rx.is_some() {
            self.status = "正在加载或重算，完成后再保存".into();
            return;
        }
        self.commit_edit(None);
        if self.editing.is_some() {
            return;
        }
        let path = match (&self.wb.path, force_dialog) {
            (Some(p), false) => Some(p.clone()),
            // 无界面验收：SC_SAVE_AS=路径 时把「另存为」直接落在该路径（不弹系统对话框）。
            // 只换对话框，保存本身仍走同一条 start_save 链路。
            _ => match std::env::var("SC_SAVE_AS") {
                Ok(p) if !p.trim().is_empty() => Some(PathBuf::from(p)),
                _ => rfd::FileDialog::new()
                .add_filter("Excel 工作簿", &["xlsx"])
                .add_filter("Excel 启用宏的工作簿", &["xlsm"])
                .add_filter("Excel 97-2003 工作簿", &["xls"])
                    .set_file_name(if self.wb.has_vba {
                        format!("{}.xlsm", self.wb.title())
                    } else {
                        format!("{}.xlsx", self.wb.title())
                    })
                    .save_file(),
            },
        };
        let Some(path) = path else { return };

        let ext = path
            .extension()
            .map(|e| e.to_string_lossy().to_lowercase())
            .unwrap_or_default();
        if self.wb.has_vba && ext == "xlsx" {
            self.status = "该文件含 VBA 宏，存成 .xlsx 会丢掉宏；已改存为 .xlsm".into();
        }
        let path = if self.wb.has_vba && ext == "xlsx" {
            path.with_extension("xlsm")
        } else {
            path
        };
        self.status = format!("正在保存 {}…", path.display());
        self.tasks.start_save(&mut self.wb, path);
    }

    /// Poll each save against the workbook that owns its channel, even off-screen.
    fn poll_save(&mut self) {
        if let Some(result) = self.tasks.poll_save(&mut self.wb) {
            self.status = match result {
                Ok(path) => {
                    // 另存成功后新文件是按当前已知内容完整写出的；诊断清掉，
                    // 后续对这份新文件的覆盖保存不再被旧文件的缺口挡住。
                    if self.wb.path.as_deref() == Some(path.as_path()) {
                        self.load_diag = None;
                        self.wb.load_incomplete = false;
                    }
                    format!("已保存 {}", path.display())
                }
                Err(error) => error,
            };
            eprintln!("[save] {}", self.status);
        }
        for tab in &mut self.tabs {
            let TabSlot::Parked(doc) = tab else { continue };
            if let Some(result) = doc.tasks.poll_save(&mut doc.wb) {
                match result {
                    Ok(path) => {
                        doc.title = path.file_name().unwrap_or_default().to_string_lossy().into_owned();
                        // 挂起的文档保存成功同样要解除旧诊断：否则切回来还会拿
                        // 已经修好的旧缺口挡住保存。
                        if doc.wb.path.as_deref() == Some(path.as_path()) {
                            doc.load_diag = None;
                            doc.wb.load_incomplete = false;
                        }
                        self.status = format!("已保存 {}", path.display());
                    }
                    Err(error) => self.status = format!("{}：{error}", doc.title),
                }
                eprintln!("[save] {}", self.status);
            }
        }
    }

    fn has_pending_save(&self) -> bool {
        self.tasks.saving.is_some() || self.tabs.iter().any(|tab| {
            matches!(tab, TabSlot::Parked(doc) if doc.tasks.saving.is_some())
        })
    }

    /// 窗口关闭前把编辑缓冲落进模型；数据验证不通过时取消关闭（草稿不能顺手丢）。
    fn commit_edit_before_close(&mut self, ctx: &egui::Context) {
        if !ctx.input(|i| i.viewport().close_requested()) {
            return;
        }
        if self.editing.is_some() {
            self.commit_edit(None);
            if self.editing.is_some() {
                ctx.send_viewport_cmd(egui::ViewportCommand::CancelClose);
            }
        }
    }

    fn defer_close_while_saving(&mut self, ctx: &egui::Context, was_saving: bool) {
        if (was_saving || self.has_pending_save())
            && ctx.input(|input| input.viewport().close_requested())
        {
            ctx.send_viewport_cmd(egui::ViewportCommand::CancelClose);
            // A failed save may have completed in this frame. Keep its error.
            if self.has_pending_save() {
                self.status = "文件仍在保存，完成后再关闭窗口".into();
            }
        }
    }

    /// 提交当前编辑：写回单元格、增量重算、广播给协作者

    /// 无界面测试钩子：SC_LOCK=r,c 占住某格；SC_LOCK_TRY=r,c 反复尝试
    fn lock_probe(&mut self, ctx: &egui::Context) {
        let (Ok(kind), Ok(cell)) = (
            std::env::var("SC_LOCK").or_else(|_| std::env::var("SC_LOCK_TRY")),
            std::env::var("SC_LOCK_CELL"),
        ) else {
            return;
        };
        let _ = kind;
        let parts: Vec<u32> = cell.split(',').filter_map(|x| x.trim().parse().ok()).collect();
        if parts.len() != 2 {
            return;
        }
        if self.net.is_none() || self.tasks.open_rx.is_some() {
            return;
        }
        if let Some(_) = self.my_lock {
            // 测试钩子：占住 N 秒后主动放锁
            let hold: u64 = std::env::var("SC_LOCK_RELEASE_SECS")
                .ok()
                .and_then(|v| v.parse().ok())
                .unwrap_or(u64::MAX);
            if self.lock_first_at.unwrap().elapsed().as_secs() >= hold {
                self.release_lock();
                if std::env::var("SC_LOCK").is_ok() {
                    eprintln!("[lock] released");
                    self.probe_done = true;
                }
            }
            return;
        }
        if self.probe_done {
            return;
        }
        if self.lock_first_at.is_none() {
            self.lock_first_at = Some(std::time::Instant::now());
        }
        let delay: u64 = std::env::var("SC_LOCK_DELAY")
            .ok()
            .and_then(|v| v.parse().ok())
            .unwrap_or(0);
        if self.lock_first_at.unwrap().elapsed().as_secs() < delay {
            ctx.request_repaint_after(std::time::Duration::from_millis(300));
            return;
        }
        if self.probe_at.elapsed().as_secs() < 2 {
            ctx.request_repaint_after(std::time::Duration::from_millis(300));
            return;
        }
        self.probe_at = std::time::Instant::now();
        self.sel = (parts[0], parts[1]);
        self.begin_edit(None);
        self.editing = None; // 只验租约，不开编辑框
        ctx.request_repaint_after(std::time::Duration::from_millis(500));
    }

    /// 无界面自检：导入 CSV + 刷新
    fn b4_probe(&mut self) {
        if std::env::var("SC_B4").is_err() || self.tasks.open_rx.is_some() || self.b4_done {
            return;
        }
        let Some(dir) = Self::probe_dir() else { return };
        self.b4_done = true;
        self.sel = (0, 0);
        self.sel_end = (0, 0);
        let csv = dir.join("import.csv");
        self.import_csv_from(&csv);
        eprintln!("[B4] {}", self.status);
        for r in 0..4 {
            let row: Vec<String> = (0..3)
                .map(|c| self.wb.sheet(self.sheet_idx).get(r, c).map(|x| x.value.display()).unwrap_or_default())
                .collect();
            eprintln!("[B4] 第{}行 {:?}", r + 1, row);
        }
        // 改文件再刷新
        let _ = std::fs::write(&csv, "姓名,部门,金额
赵六,财务,900
");
        self.refresh_import();
        let v = self.wb.sheet(self.sheet_idx).get(1, 0).map(|x| x.value.display()).unwrap_or_default();
        eprintln!("[B4] 刷新后 A2={v} 状态={}", self.status);
        eprintln!("[B4] 数据源 {} 个", self.wb.sources.len());

        // 存盘再重开：数据源应当还在，刷新能力才谈得上"持久"
        let out = dir.join("b4_out.xlsx");
        let _ = std::fs::remove_file(&out);
        if let Err(e) = sheetcore::xlsx::save_atomic(&out, &self.wb) {
            eprintln!("[B4] 存盘失败: {e:#}");
            return;
        }
        // 挂查询表（必须在文件写完之后，和手动流程一致）
        self.wb.path = Some(out.clone());
        self.attach_query_tables();
        eprintln!("[B4] {}", self.status);
        match sheetcore::xlsx::load(&out) {
            Ok(back) => eprintln!(
                "[B4] 重开后数据源={} 首个={:?}",
                back.sources.len(),
                back.sources.first().map(|s| format!("{:?} {}", s.kind, s.rows * s.cols))
            ),
            Err(e) => eprintln!("[B4] 重开失败: {e:#}"),
        }
    }

    /// 无界面自检：图表改颜色/轴标题 → 写盘 → 重读
    fn d3_probe(&mut self) {
        if std::env::var("SC_D3").is_err() || self.tasks.open_rx.is_some() || self.d3_done {
            return;
        }
        self.d3_done = true;
        let charts = self.wb.sheet(self.sheet_idx).charts.clone();
        let Some(mut ch) = charts.first().cloned() else {
            eprintln!("[D3] 当前表没有图表");
            return;
        };
        ch.axis_x = "季度".into();
        ch.axis_y = "销量".into();
        if let Some(s0) = ch.series.first_mut() {
            s0.color = Some([0xE0, 0x4A, 0x2F]);
        }
        ch.y_min = Some(0.0);
        ch.y_max = Some(600.0);
        eprintln!("[D3] 改前 part={:?} 系列={}", ch.part, ch.series.len());
        self.commit_chart(ch);
        eprintln!("[D3] 提交状态={}", self.status);
        if let Some(path) = self.wb.path.clone() {
            match sheetcore::charts::load_charts(&path, &self.wb.sheet(self.sheet_idx).name) {
                Ok(list) => {
                    for c in list.iter().take(1) {
                        eprintln!(
                            "[D3] 重读 轴X={:?} 轴Y={:?} ymax={:?} 首色={:?}",
                            c.axis_x, c.axis_y, c.y_max,
                            c.series.first().and_then(|s| s.color)
                        );
                    }
                }
                Err(e) => eprintln!("[D3] 重读失败 {e:#}"),
            }
        }
    }

    /// 无界面自检：选区转表格 + 结构化引用 + 存盘
    fn b1_probe(&mut self) {
        if std::env::var("SC_B1").is_err() || self.tasks.open_rx.is_some() || self.b1_done {
            return;
        }
        let Some(dir) = Self::probe_dir() else { return };
        self.b1_done = true;
        self.sel = (0, 0);
        self.sel_end = (5, 2);
        self.make_table();
        eprintln!("[B1] {}", self.status);
        let t = self.wb.sheet(self.sheet_idx).tables.first().cloned();
        eprintln!("[B1] 表格={:?}", t.as_ref().map(|x| (x.name.clone(), x.range, x.columns.clone())));
        let name = t.map(|x| x.name).unwrap_or_else(|| "Table1".into());
        let si = self.sheet_idx;
        let v = sheetcore::formula::eval_formula(&self.wb, si, &format!("=SUM({name}[金额])"));
        eprintln!("[B1] SUM({name}[金额]) = {v:?}");
        let out = dir.join("b1_out.xlsx");
        let _ = std::fs::remove_file(&out);
        match sheetcore::xlsx::save_atomic(&out, &self.wb) {
            Ok(_) => eprintln!("[B1] 存盘后表格={:?}", sheetcore::table::load(&out)),
            Err(e) => eprintln!("[B1] 保存失败 {e:#}"),
        }
    }


    /// 无界面自检：Ctrl+Shift+Enter 数组公式 → 存盘带 t="array"
    fn b3_probe(&mut self) {
        if std::env::var("SC_B3").is_err() || self.tasks.open_rx.is_some() || self.b3_done {
            return;
        }
        let Some(dir) = Self::probe_dir() else { return };
        self.b3_done = true;
        self.sel = (1, 1);
        self.sel_end = (1, 3);
        self.begin_edit(Some("=SUM(A1:A3*C1:C3)".to_string()));
        self.cse_pending = true;
        self.commit_edit(None);
        eprintln!("[B3] 状态={} 数组={:?}", self.status, self.wb.sheet(self.sheet_idx).arrays);
        let out = dir.join("b3_out.xlsx");
        let _ = std::fs::remove_file(&out);
        match sheetcore::xlsx::save_atomic(&out, &self.wb) {
            Ok(_) => {
                let found = sheetcore::arr::scan(&out);
                eprintln!("[B3] 存盘后数组={found:?}");
                let b2 = self.wb.sheet(self.sheet_idx).get(1, 1).map(|c| c.value.display());
                let c2 = self.wb.sheet(self.sheet_idx).get(1, 2).map(|c| c.value.display());
                eprintln!("[B3] B2={b2:?} C2={c2:?}");
            }
            Err(e) => eprintln!("[B3] 保存失败 {e:#}"),
        }
    }

    /// 无界面自检：成员列表内容（谁在线、在哪个格）
    fn c2_probe(&mut self) {
        if std::env::var("SC_C2").is_err() || self.net.is_none() {
            return;
        }
        if self.t0.elapsed().as_secs() < 6 || self.c2_done {
            return;
        }
        self.c2_done = true;
        let mut members: Vec<String> = Vec::new();
        for (site, name, _) in self.peers_list.iter() {
            let pos = self.remote.get(site).map(|(_, _, r, c)| format!("({r},{c})"));
            members.push(format!("{name}#{site}@{pos:?}"));
        }
        eprintln!("[C2] 成员 {} 人: {:?}", members.len(), members);
    }

    /// 无界面自检：圈释无效 + 输入提示
    fn b6_probe(&mut self, ctx: &egui::Context) {
        if std::env::var("SC_B6").is_err() || self.tasks.open_rx.is_some() || self.b6_done {
            return;
        }
        self.b6_done = true;
        self.circle_invalid = true;
        self.invalid_gen = u64::MAX;
        self.compute_invalid();
        let mut cells: Vec<(u32, u32)> = self.invalid_cells.iter().copied().collect();
        cells.sort();
        eprintln!("[B6] 无效格 {:?}", cells);
        // 选中 A2 看提示
        self.sel = (1, 0);
        self.sel_end = (1, 0);
        let dv = sheetcore::dv::find(&self.wb.sheet(self.sheet_idx).dv, 1, 0);
        eprintln!(
            "[B6] A2 提示 = {:?} / {:?}",
            dv.as_ref().map(|d| d.prompt_title.clone()),
            dv.as_ref().map(|d| d.prompt_msg.clone())
        );
        let _ = ctx;
    }

    /// 无界面自检：条件格式管理器（描述文本 + 删规则 + 调顺序）
    fn b5_probe(&mut self) {
        if std::env::var("SC_B5").is_err() || self.tasks.open_rx.is_some() || self.b5_done {
            return;
        }
        self.b5_done = true;
        let sheet = self.wb.sheet(self.sheet_idx);
        let before: Vec<String> = sheet
            .cf
            .blocks
            .iter()
            .flat_map(|b| b.rules.iter().map(|r| r.kind.describe()))
            .collect();
        eprintln!("[B5] 原有 {} 条规则: {:?}", before.len(), before);
        // 删第一条规则
        {
            let sheet = self.wb.sheet_mut(self.sheet_idx);
            if let Some(b) = sheet.cf.blocks.first_mut() {
                if !b.rules.is_empty() {
                    b.rules.remove(0);
                }
            }
            sheet.cf.blocks.retain(|b| !b.rules.is_empty());
            sheet.cf_dirty = true;
        }
        let after: Vec<String> = self
            .wb
            .sheet(self.sheet_idx)
            .cf
            .blocks
            .iter()
            .flat_map(|b| b.rules.iter().map(|r| r.kind.describe()))
            .collect();
        eprintln!("[B5] 删除后 {} 条: {:?}", after.len(), after);
        // 调顺序
        let n = self.wb.sheet(self.sheet_idx).cf.blocks.len();
        if n >= 2 {
            let first_range = self.wb.sheet(self.sheet_idx).cf.blocks[0].ranges.clone();
            self.wb.sheet_mut(self.sheet_idx).cf.blocks.swap(0, 1);
            let new_first = self.wb.sheet(self.sheet_idx).cf.blocks[0].ranges.clone();
            eprintln!("[B5] 交换后首块区域 {:?} -> 原第二块 {:?}", first_range, new_first);
        }
    }

    /// 无界面自检：A 组（剪贴板/查找替换/工作表）
    fn a_group_probe(&mut self, ctx: &egui::Context) {
        if std::env::var("SC_A_TEST").is_err() || self.tasks.open_rx.is_some() || self.a_done {
            return;
        }
        self.a_done = true;
        // 剪贴板：A1:B2 -> D1
        self.sel = (0, 0);
        self.sel_end = (1, 1);
        self.clip_copy(false, ctx);
        self.sel = (0, 3);
        self.sel_end = (0, 3);
        self.clip_paste(false, None);
        let pasted = format!(
            "{}/{}/{}/{}",
            self.wb.sheet(self.sheet_idx).get(0, 3).map(|c| c.value.display()).unwrap_or_default(),
            self.wb.sheet(self.sheet_idx).get(0, 4).map(|c| c.value.display()).unwrap_or_default(),
            self.wb.sheet(self.sheet_idx).get(1, 3).map(|c| c.value.display()).unwrap_or_default(),
            self.wb.sheet(self.sheet_idx).get(1, 4).map(|c| c.value.display()).unwrap_or_default()
        );
        // 查找替换
        self.find.find = "研发".into();
        self.find.replace = "技术".into();
        self.replace_all();
        let replaced = self.wb.sheet(self.sheet_idx).get(1, 1).map(|c| c.value.display()).unwrap_or_default();
        let status_find = self.status.clone();
        // 工作表
        let before = self.wb.sheets.len();
        self.add_sheet();
        let new_name = self.wb.sheets.last().map(|s| s.name.clone()).unwrap_or_default();
        self.wb.sheets.last_mut().unwrap().name = "新表".into();
        self.move_sheet(self.wb.sheets.len() - 1, -1);
        let moved_to = self.sheet_idx;
        // 删掉刚建的那张（按名字找），别把原表删了
        if let Some(i) = self.wb.sheets.iter().position(|s| s.name == "新表") {
            self.delete_sheet(i);
        }
        // 数据工具：排序 / 删除重复 / 分列（先回到第一张表，前面动过工作表）
        self.sheet_idx = 0;
        {
            let (r1, c1, r2, c2) = (0u32, 0u32, 5u32, 2u32);
            self.sel = (r1, c1);
            self.sel_end = (r2, c2);
            let dlg = DataDlg {
                tab: 0,
                keys: vec![(1, true, true), (2, false, true)],
                header: true,
                delim: ",".into(),
            };
            self.run_sort(&dlg);
            let order: Vec<String> = (1..=5)
                .map(|r| self.wb.sheet(self.sheet_idx).get(r, 1).map(|c| c.value.display()).unwrap_or_default())
                .collect();
            eprintln!("[B2] 排序后部门列={order:?}");
            self.run_dedup();
            eprintln!("[B2] 去重状态={}", self.status);
            // 分列：D 列写 "甲,1" 再拆
            self.wb.sheet_mut(self.sheet_idx).set(0, 3, sheetcore::model::Cell {
                value: sheetcore::model::Value::Text("甲,1".into()), formula: None });
            self.sel = (0, 3);
            self.sel_end = (0, 3);
            self.run_split(',');
            let a = self.wb.sheet(self.sheet_idx).get(0, 3).map(|c| c.value.display()).unwrap_or_default();
            let b = self.wb.sheet(self.sheet_idx).get(0, 4).map(|c| c.value.display()).unwrap_or_default();
            eprintln!("[B2] 分列后 D1={a} E1={b}");
        }
        // 填充：1,2 拉到第 6 行应为 3,4,5,6
        self.wb.sheet_mut(self.sheet_idx).set(8, 0, sheetcore::model::Cell { value: sheetcore::model::Value::Number(1.0), formula: None });
        self.wb.sheet_mut(self.sheet_idx).set(9, 0, sheetcore::model::Cell { value: sheetcore::model::Value::Number(2.0), formula: None });
        self.sel = (8, 0);
        self.sel_end = (9, 0);
        self.fill_to(13, true);
        let filled: Vec<String> = (8..=13)
            .map(|r| self.wb.sheet(self.sheet_idx).get(r, 0).map(|c| c.value.display()).unwrap_or_default())
            .collect();
        self.autofit_col(ctx, 0);
        let w = self.wb.sheet(self.sheet_idx).cols.size(0);
        eprintln!("[A] 填充={filled:?} 列宽={w:.0} 粘贴={pasted} 替换后B2={replaced} ({status_find}) 表数 {before}->{} 新表={new_name} 移动后位置={moved_to}",
            self.wb.sheets.len()
        );
    }

    /// 无界面自检：打开宏窗口并打印读到的模块
    fn macro_probe(&mut self) {
        if std::env::var("SC_MACRO").is_err() || self.tasks.open_rx.is_some() || self.macro_done {
            return;
        }
        self.macro_done = true;
        self.open_macro_view();
        if let Some((mods, _)) = &self.macro_win {
            for m in mods {
                eprintln!(
                    "[macro] {} [{}] {} 行，首行={:?}",
                    m.name,
                    m.kind,
                    m.lines,
                    m.source.lines().next().unwrap_or("")
                );
            }
        } else {
            eprintln!("[macro] 没有读到模块（状态={}）", self.status);
        }
    }

    /// 无界面自检：在顶部插两行，验证协作同步
    fn struct_probe(&mut self) {
        if std::env::var("SC_STRUCT_TEST").is_err() || self.tasks.open_rx.is_some() || self.struct_done {
            return;
        }
        self.struct_done = true;
        self.structural(sheetcore::structural::Structural::InsertRows { at: 0, n: 2 });
        eprintln!("[struct] 已插入 2 行");
    }

    /// 无界面自检：给 B2 加粗并广播，用来验格式同步
    fn style_probe(&mut self) {
        if std::env::var("SC_STYLE_TEST").is_err() || self.tasks.open_rx.is_some() || self.style_done {
            return;
        }
        self.style_done = true;
        self.sel = (1, 1);
        self.sel_end = (1, 1);
        self.apply_style(|st| st.bold = true);
        eprintln!("[style] 已加粗 B2 并广播");
    }

    /// 无界面自检：按 XML 命令直接触发一次（截图验证功能区连线用）
    fn ribbon_probe(&mut self, ctx: &egui::Context) {
        if self.ribbon_probe_done || self.tasks.open_rx.is_some() {
            return;
        }
        if let Ok(v) = std::env::var("SC_RIBBON_SEL") {
            let n: Vec<u32> = v
                .split(',')
                .filter_map(|x| x.trim().parse().ok())
                .collect();
            if n.len() == 4 {
                self.sel = (n[0], n[1]);
                self.sel_end = (n[2], n[3]);
            }
        }
        if let Ok(list) = std::env::var("SC_RIBBON_ACTION") {
            self.ribbon_probe_done = true;
            for one in list.split(';').filter(|s| !s.is_empty()) {
                self.ribbon_action(one, ctx);
                if std::env::var("SC_RIBBON_LOG").is_ok() {
                    eprintln!(
                        "[ribbon] 动作 {one} → 状态「{}」 表格 {} 个",
                        self.status,
                        self.wb.sheet(self.sheet_idx).tables.len()
                    );
                }
            }
        }
        if std::env::var("SC_RIBBON_CHART").is_ok() {
            self.ribbon_probe_done = true;
            if let Some((i, _)) = self
                .wb
                .sheets
                .iter()
                .enumerate()
                .find(|(_, sh)| !sh.charts.is_empty())
            {
                self.sheet_idx = i;
                self.chart_sel = Some(0);
                self.ribbon_tab = 101;
            } else {
                eprintln!("[ribbon] 整簿没有图表");
            }
        }
        if let Ok(id) = std::env::var("SC_RIBBON_ITEMS") {
            self.ribbon_probe_done = true;
            if let Some(items) = self.ribbon.find_dropdown(&id) {
                self.ribbon_popup = Some(ribbon::ui::Popup {
                    kind: ribbon::ui::PopupKind::Items(items),
                    pos: egui::pos2(200.0, 200.0),
                    opened_at: 0.0,
                });
            } else {
                eprintln!("[ribbon] 找不到下拉 {id}");
            }
        }
        if let Ok(m) = std::env::var("SC_RIBBON_MENU") {
            self.ribbon_probe_done = true;
            if let Some(menu) = self.ribbon.find_menu(&m) {
                self.ribbon_popup = Some(ribbon::ui::Popup {
                    kind: ribbon::ui::PopupKind::Menu(menu),
                    pos: egui::pos2(200.0, 200.0),
                    opened_at: 0.0,
                });
            } else {
                eprintln!("[ribbon] 找不到菜单 {m}");
            }
        }
    }

    /// 无界面自检：编辑 → 撤销 → 重做 → 格式撤销
    fn undo_probe(&mut self) {
        if std::env::var("SC_UNDO_TEST").is_err() || self.tasks.open_rx.is_some() || self.probe_done {
            return;
        }
        self.probe_done = true;
        let (r, c) = (1u32, 1u32);
        let orig = self
            .wb
            .sheet(self.sheet_idx)
            .get(r, c)
            .map(|x| x.value.display())
            .unwrap_or_default();
        // 1) 编辑
        self.sel = (r, c);
        self.editing = Some(EditState::new("999".into()));
        self.commit_edit(None);
        let after_edit = self.wb.sheet(self.sheet_idx).get(r, c).unwrap().value.display();
        // 2) 撤销
        self.do_undo(false);
        let after_undo = self.wb.sheet(self.sheet_idx).get(r, c).unwrap().value.display();
        // 3) 重做
        self.do_undo(true);
        let after_redo = self.wb.sheet(self.sheet_idx).get(r, c).unwrap().value.display();
        // 4) 格式：加粗后撤销
        self.sel = (r, c);
        self.apply_style(|st| st.bold = !st.bold);
        let bold_after = self.wb.styles.get(self.wb.sheet(self.sheet_idx).style_of(r, c)).bold;
        self.do_undo(false);
        let bold_undo = self.wb.styles.get(self.wb.sheet(self.sheet_idx).style_of(r, c)).bold;
        // 5) 清除后撤销
        self.sel = (r, c);
        self.wb
            .sheet_mut(self.sheet_idx)
            .set(r, c, Cell { value: Value::Empty, formula: None });
        self.undo.push(sheetcore::undo::Action {
            label: "清除".into(),
            merges: None,
            snap_before: None,
            snap_after: None,
            by_site: 0,
            shapes: None,
            deltas: vec![sheetcore::undo::CellDelta {
                sheet: self.sheet_idx,
                row: r,
                col: c,
                before: Cell { value: Value::Number(7.0), formula: None },
                after: Cell { value: Value::Empty, formula: None },
                before_style: 0,
                after_style: 0,
            }],
            focus: (self.sheet_idx, r, c),
            refresh_sizes: None,
        });
        self.do_undo(false);
        let clear_undo = self.wb.sheet(self.sheet_idx).get(r, c).unwrap().value.display();
        eprintln!(
            "[undo] 原值={orig} 编辑后={after_edit} 撤销后={after_undo} 重做后={after_redo} 加粗={bold_after} 撤销后={bold_undo} 清除撤销={clear_undo} 深度={:?}",
            self.undo.depth()
        );
    }

    /// 把远端做过的结构改动套到当前工作簿上。
    /// 文件每次重新读入（Loaded/Recalced）都会得到「未改结构」的版本，
    /// 所以换过一次就要从头再套一遍。
    fn sync_history(&mut self) {
        if self.struct_history.is_empty() {
            return;
        }
        if self.wb_epoch != self.history_last_epoch {
            self.history_planted = 0;
            self.history_last_epoch = self.wb_epoch;
        }
        if self.history_planted >= self.struct_history.len() {
            return;
        }
        let items: Vec<(usize, sheetcore::structural::Structural)> =
            self.struct_history[self.history_planted..].to_vec();
        for (sheet, op) in items.iter() {
            if *sheet < self.wb.sheets.len() {
                // 格子由快照给（已经是新坐标），这里只搬合并/条件格式等结构
                self.wb
                    .sheet_mut(*sheet)
                    .apply_structural_structure_only(op);
            }
        }
        self.history_planted = self.struct_history.len();
        self.doc_gen = self.doc_gen.wrapping_add(1);
    }

    fn lock_now(&self) -> u64 {
        self.t0.elapsed().as_millis() as u64
    }

    /// 这个格子现在能不能由我编辑
    fn lock_holder(&self, row: u32, col: u32) -> Option<String> {
        self.lock_holder_on(self.sheet_idx, row, col)
    }

    fn lock_holder_on(&self, sheet: usize, row: u32, col: u32) -> Option<String> {
        // 离线时也认本地租约表：表里已有他人持有时，不能因为暂时没连网就放行
        let site = self.net.as_ref().map(|n| n.site).unwrap_or(0);
        if self.locks.is_locked_by_other(sheet, row, col, site) {
            self.locks
                .holder(sheet, row, col)
                .map(|h| h.name.clone())
        } else {
            None
        }
    }

    /// 开始编辑：没联网直接开；联网先申请租约，批准后才开
    /// 工作表受保护时阻止一切改内容的操作
    fn edit_blocked(&mut self) -> bool {
        if self.deps_pending {
            self.status = "大文件还在后台准备依赖图，稍等一下再编辑".into();
            return true;
        }
        if self.wb.sheet(self.sheet_idx).protection.is_some() {
            self.status = "工作表受保护：请先“审阅 → 撤销保护”".into();
            true
        } else {
            false
        }
    }

    /// 统一写入门禁：所有直接改模型的入口先过这里。
    /// - 后台依赖未就绪、工作表受保护 → 拒绝；
    /// - 目标区域里**任何一格**被别人锁定 → 整批拒绝，不做部分写入。
    fn write_preflight(&mut self, keys: &[(u32, u32)], what: &str) -> bool {
        self.write_preflight_on(self.sheet_idx, keys, what)
    }

    /// 指定工作表的统一门禁（跨表剪切等场景不能只看当前表）
    fn write_preflight_on(&mut self, sheet: usize, keys: &[(u32, u32)], what: &str) -> bool {
        if self.deps_pending {
            self.status = "大文件还在后台准备依赖图，稍等一下再操作".into();
            return false;
        }
        if self.wb.sheet(sheet).protection.is_some() {
            let name = self.wb.sheet(sheet).name.clone();
            self.status = format!("工作表「{name}」受保护：不能{what}（先“审阅 → 撤销保护”）");
            return false;
        }
        for (r, c) in keys {
            if let Some(holder) = self.lock_holder_on(sheet, *r, *c) {
                self.status = format!("{holder} 正在编辑 {}，不能{what}", cell_name(*r, *c));
                return false;
            }
        }
        true
    }

    fn begin_edit(&mut self, initial: Option<String>) {
        self.begin_edit_at(initial, EditSpot::Grid);
    }

    /// 进入编辑并指定焦点位置。没在编辑时按当前格进；已在编辑时只搬焦点、不重置缓冲
    /// （在编辑栏点一下不能把刚打的字清掉）。
    fn focus_edit(&mut self, spot: EditSpot) {
        if let Some(ed) = self.editing.as_mut() {
            ed.spot = spot;
            return;
        }
        self.begin_edit_at(None, spot);
    }

    fn begin_edit_at(&mut self, initial: Option<String>, spot: EditSpot) {
        if self.edit_blocked() {
            return;
        }
        let (r, c) = self.sel;
        if let Some(holder) = self.lock_holder(r, c) {
            self.status = format!("{} 正在编辑 {}，请稍后", holder, cell_name(r, c));
            return;
        }
        let Some(net) = self.net.as_ref() else {
            let buf = initial.unwrap_or_else(|| {
                match self.wb.sheet(self.sheet_idx).get(r, c) {
                    Some(cell) => cell
                        .formula
                        .as_deref()
                        .map(|f| sheetcore::xlinks::display_formula(&self.wb, f))
                        .unwrap_or_else(|| cell.value.display()),
                    None => String::new(),
                }
            });
            self.editing = Some(EditState { buf, spot });
            return;
        };
        let name = self.my_name.clone();
        net.request_lock(self.sheet_idx, r, c, &name);
        self.pending_spot = spot;
        self.pending_edit = Some(initial.unwrap_or_default());
        self.status = format!("正在申请编辑 {}…", cell_name(r, c));
    }

    /// 编辑结束/放弃，交还租约
    fn release_lock(&mut self) {
        if let Some((sheet, row, col)) = self.my_lock.take() {
            if let Some(net) = self.net.as_ref() {
                net.release_lock(sheet, row, col);
            }
            let site = self.net.as_ref().map(|n| n.site).unwrap_or(0);
            self.locks.release(sheet, row, col, site);
        }
        self.pending_edit = None;
    }

    /// 编辑中定期续期，防止长时间思考时被判定超时
    fn renew_lock_if_needed(&mut self) {
        if self.my_lock.is_none() {
            return;
        }
        if self.lock_renew.elapsed().as_secs() < 8 {
            return;
        }
        self.lock_renew = std::time::Instant::now();
        if let (Some(net), Some((sheet, row, col))) = (self.net.as_ref(), self.my_lock) {
            let name = self.my_name.clone();
            net.request_lock(sheet, row, col, &name);
        }
    }


    /// 记一步撤销：先 capture，改完 finish
    fn txn_begin(&self, keys: &[(u32, u32)]) -> Vec<sheetcore::undo::CellDelta> {
        sheetcore::undo::capture(self.wb.sheet(self.sheet_idx), self.sheet_idx, keys)
    }

    fn txn_end(&mut self, label: &str, before: Vec<sheetcore::undo::CellDelta>) {
        let deltas = sheetcore::undo::finish(before, self.wb.sheet(self.sheet_idx));
        if deltas.is_empty() {
            return;
        }
        self.record_revision(label, &deltas);
        let focus = (self.sheet_idx, self.sel.0, self.sel.1);
        self.undo.push(sheetcore::undo::Action {
            label: label.to_string(),
            merges: None,
            deltas,
            focus,
            snap_before: None,
            snap_after: None,
            by_site: 0,
            shapes: None,
            refresh_sizes: None,
        });
    }


    /// 远端改动也进日志（只展示，不给撤回）
    fn record_remote_ops(
        &mut self,
        ops: &[sheetcore::sync::Op],
        befores: Vec<Option<sheetcore::model::Cell>>,
    ) {
        let Some(path) = self.wb.path.clone() else {
            return;
        };
        for (op, before) in ops.iter().zip(befores.into_iter()) {
            let Some(sheet) = self.wb.sheets.get(op.sheet) else {
                continue;
            };
            let sheet_name = sheet.name.clone();
            let after = sheet.get(op.row, op.col).cloned();
            let (Some(b), Some(a)) = (before, after) else {
                continue;
            };
            let who = self
                .peers_list
                .iter()
                .find(|(s, _, _)| *s == op.site)
                .map(|(_, n, _)| n.clone())
                .unwrap_or_else(|| format!("同事#{}", op.site));
            let mut e = sheetcore::revision::Entry::new(&who, op.site, "远端编辑", &sheet_name);
            e.remote = true;
            e.cells.push(sheetcore::revision::Change {
                r: op.row,
                c: op.col,
                before: sheetcore::revision::Snap::from_cell(&b),
                after: sheetcore::revision::Snap::from_cell(&a),
                before_style: None,
                after_style: None,
            });
            let _ = sheetcore::revision::append(&path, &e);
            self.rev.push(e);
            if self.rev.len() > 600 {
                self.rev.remove(0);
            }
        }
    }

    /// 把一次动作写进修订日志（本地动作）
    fn record_revision(&mut self, label: &str, deltas: &[sheetcore::undo::CellDelta]) {
        let Some(path) = self.wb.path.clone() else {
            return; // 没保存过的新文件还不知道日志放哪
        };
        let sheet_idx = deltas.first().map(|d| d.sheet).unwrap_or(self.sheet_idx);
        let sheet = self.wb.sheet(sheet_idx).name.clone();
        let mut e = sheetcore::revision::Entry::new(&self.my_name, 0, label, &sheet);
        let total = deltas.len();
        let mut only_style = true;
        for d in deltas.iter().take(sheetcore::revision::MAX_CELLS) {
            if d.before.value != d.after.value || d.before.formula != d.after.formula {
                only_style = false;
            }
            let (bs, as_) = if d.before_style != d.after_style {
                (
                    Some(self.wb.styles.get(d.before_style).clone()),
                    Some(self.wb.styles.get(d.after_style).clone()),
                )
            } else {
                (None, None)
            };
            e.cells.push(sheetcore::revision::Change {
                r: d.row,
                c: d.col,
                before: sheetcore::revision::Snap::from_cell(&d.before),
                after: sheetcore::revision::Snap::from_cell(&d.after),
                before_style: bs,
                after_style: as_,
            });
        }
        if only_style && total > 0 {
            e.note = "格式变更".into();
        }
        if total > sheetcore::revision::MAX_CELLS {
            e.note = format!("共 {total} 格，只记前 {} 格", sheetcore::revision::MAX_CELLS);
        }
        if let Err(err) = sheetcore::revision::append(&path, &e) {
            eprintln!("[rev] 写日志失败: {err}");
        }
        self.rev.push(e);
        if self.rev.len() > 600 {
            self.rev.remove(0);
        }
    }

    // ===== 剪贴板 =====
    fn clip_copy(&mut self, cut: bool, ctx: &egui::Context) {
        let (r1, c1, r2, c2) = self.sel_rect();
        if (r2 - r1 + 1) as u64 * (c2 - c1 + 1) as u64 > 200_000 {
            self.status = "选区太大（超过 20 万格），不复制".into();
            return;
        }
        let si = self.sheet_idx;
        let mut cells = Vec::new();
        let mut tsv = String::new();
        for r in r1..=r2 {
            let mut row = Vec::new();
            let mut line = Vec::new();
            for c in c1..=c2 {
                let cell = self.wb.sheet(si).get(r, c).cloned().unwrap_or(sheetcore::model::Cell {
                    value: sheetcore::model::Value::Empty,
                    formula: None,
                });
                let st = self.wb.sheet(si).style_of(r, c);
                line.push(cell.value.display());
                row.push((cell, st));
            }
            tsv.push_str(&line.join("\t"));
            tsv.push('\n');
            cells.push(row);
        }
        ctx.copy_text(tsv.clone());
        self.clip_stamp = Some(tsv);
        self.clip = Some(Clip { sheet: si, rect: (r1, c1, r2, c2), cells, cut });
        self.status = format!(
            "已{} {:?}（{} 行 × {} 列）",
            if cut { "剪切" } else { "复制" },
            (r1, c1, r2, c2),
            r2 - r1 + 1,
            c2 - c1 + 1
        );
    }

    /// values_only=true 时只贴值（不贴公式和格式）
    fn clip_paste(&mut self, values_only: bool, text: Option<String>) {
        if self.edit_blocked() {
            return;
        }
        let (r, c) = self.sel;
        let si = self.sheet_idx;
        let mut tsv_paste = false;
        let mut rows: Vec<Vec<(sheetcore::model::Cell, u16)>> = Vec::new();
        let mut cut_src: Option<(usize, (u32, u32, u32, u32))> = None;

        if let Some(clip) = self.clip.clone() {
            // 系统剪贴板里的内容跟内部剪贴板不一致时优先用系统的
            if let Some(t) = &text {
                if !t.trim_end().is_empty() && !self.clip_matches(t, &clip) {
                    rows = Self::parse_tsv(t);
                    tsv_paste = true;
                }
            }
            if !tsv_paste {
                let (sr1, sc1, _, _) = clip.rect;
                let dr = r as i64 - sr1 as i64;
                let dc = c as i64 - sc1 as i64;
                for (i, row) in clip.cells.iter().enumerate() {
                    let mut out = Vec::new();
                    for (j, (cell, st)) in row.iter().enumerate() {
                        let mut cell = cell.clone();
                        if !values_only {
                            if let Some(f) = &cell.formula {
                                let src_sheet = clip.sheet;
                                let name = self.wb.sheet(src_sheet).name.clone();
                                let _ = name;
                                let sheet_name = self.wb.sheet(si).name.clone();
                                let nf = sheetcore::refs::translate(f, dr, dc + (j as i64 - j as i64), &sheet_name);
                                cell.formula = Some(nf.into_boxed_str());
                            }
                        } else {
                            cell.formula = None;
                        }
                        out.push((cell, if values_only { 0 } else { *st }));
                    }
                    rows.push(out);
                }
                if clip.cut {
                    cut_src = Some((clip.sheet, clip.rect));
                }
            }
        } else if let Some(t) = text {
            rows = Self::parse_tsv(&t);
            tsv_paste = true;
        } else {
            self.status = "剪贴板是空的".into();
            return;
        }
        if rows.is_empty() {
            return;
        }

        // One transaction covers both sides of a cut, including overlapping cells.
        let h = rows.len() as u32;
        let w = rows.iter().map(|r| r.len()).max().unwrap_or(0) as u32;
        let mut touched = std::collections::BTreeSet::new();
        for (i, row) in rows.iter().enumerate() {
            for j in 0..row.len() {
                touched.insert((si, r + i as u32, c + j as u32));
            }
        }
        if let Some((source, (sr1, sc1, sr2, sc2))) = cut_src {
            for rr in sr1..=sr2 {
                for cc in sc1..=sc2 {
                    touched.insert((source, rr, cc));
                }
            }
        }
        // 目标区或剪切源里任何一格被别人锁着 → 整批都不写
        let target_keys: Vec<(u32, u32)> = touched
            .iter()
            .filter(|(sheet, _, _)| *sheet == si)
            .map(|(_, rr, cc)| (*rr, *cc))
            .collect();
        if !self.write_preflight(&target_keys, "粘贴") {
            return;
        }
        if let Some((source, (sr1, sc1, sr2, sc2))) = cut_src {
            let src_keys = sheetcore::undo::rect_keys(sr1, sc1, sr2, sc2);
            if !self.write_preflight_on(source, &src_keys, "剪切") {
                return;
            }
        }
        let mut transactions = std::collections::BTreeMap::new();
        for &(sheet, rr, cc) in &touched {
            transactions.entry(sheet).or_insert_with(Vec::new).push((rr, cc));
        }
        let before: Vec<_> = transactions.into_iter().map(|(sheet, keys)| {
            (sheet, sheetcore::undo::capture(self.wb.sheet(sheet), sheet, &keys))
        }).collect();
        // Clear before writing: the clipboard already holds a source snapshot.
        if let Some((source, (sr1, sc1, sr2, sc2))) = cut_src {
            for rr in sr1..=sr2 {
                for cc in sc1..=sc2 {
                    self.wb.sheet_mut(source).set(rr, cc, Cell::default());
                    self.wb.sheet_mut(source).set_style(rr, cc, 0);
                }
            }
        }
        for (i, row) in rows.iter().enumerate() {
            for (j, (cell, st)) in row.iter().enumerate() {
                let rr = r + i as u32;
                let cc = c + j as u32;
                self.wb.sheet_mut(si).set(rr, cc, cell.clone());
                if !values_only && !tsv_paste {
                    self.wb.sheet_mut(si).set_style(rr, cc, *st);
                }
            }
        }
        let label = if cut_src.is_some() { "剪切粘贴" } else if values_only { "粘贴数值" } else { "粘贴" };
        let mut deltas = Vec::new();
        for (sheet, captured) in before {
            let changes = sheetcore::undo::finish(captured, self.wb.sheet(sheet));
            if !changes.is_empty() {
                self.record_revision(label, &changes);
                deltas.extend(changes);
            }
        }
        self.undo.push(sheetcore::undo::Action {
            label: label.into(), deltas, focus: (si, r, c),
            merges: None,
            snap_before: None, snap_after: None, by_site: 0,
            shapes: None,
            refresh_sizes: None,
        });
        if cut_src.is_some() {
            self.clip = None;
        }
        // 重算 + 广播
        let touched: Vec<_> = touched.into_iter().collect();
        self.recalc_and_broadcast(&touched);
        self.wb.dirty = true;
        self.doc_gen = self.doc_gen.wrapping_add(1);
        self.tasks.last_edit = Some(std::time::Instant::now());
        self.status = format!("已粘贴 {h} 行 × {w} 列");
    }

    fn clip_matches(&self, text: &str, clip: &Clip) -> bool {
        let mut expect = String::new();
        for row in clip.cells.iter() {
            let mut line = Vec::new();
            for (cell, _) in row.iter() {
                line.push(cell.value.display());
            }
            expect.push_str(&line.join("\t"));
            expect.push('\n');
        }
        expect == text
    }

    fn parse_tsv(text: &str) -> Vec<Vec<(sheetcore::model::Cell, u16)>> {
        let mut rows = Vec::new();
        for line in text.lines() {
            if line.is_empty() && rows.is_empty() {
                continue;
            }
            let mut row = Vec::new();
            for field in line.split('\t') {
                let cell = if field.starts_with('=') {
                    sheetcore::model::Cell {
                        value: sheetcore::model::Value::Text(field.into()),
                        formula: Some(field.into()),
                    }
                } else {
                    sheetcore::model::Cell {
                        value: sheetcore::model::Value::parse_input(field),
                        formula: None,
                    }
                };
                row.push((cell, 0u16));
            }
            rows.push(row);
        }
        rows
    }

    /// 系统剪贴板文本 → 粘贴矩阵。与普通粘贴共用 parse_tsv，保留中间空行。
    fn parse_clip_text(text: &str) -> Vec<Vec<(sheetcore::model::Cell, u16)>> {
        Self::parse_tsv(text)
    }

    fn recalc_and_broadcast(&mut self, keys: &[(usize, u32, u32)]) {
        // 依赖图还没建好（刚打开、后台构建中）时先补一份，否则清除/粘贴的
        // 下游公式不会重算。空图 + 无公式时这次构建只是一次扫描。
        if self.deps.is_empty() {
            self.deps = sheetcore::formula::deps::Deps::build(&self.wb);
        }
        for k in keys {
            self.deps.update_cell(&self.wb, *k);
        }
        let deps = std::mem::replace(&mut self.deps, sheetcore::formula::deps::Deps::empty());
        if !self.manual_calc {
            sheetcore::formula::recalc_dirty(&mut self.wb, &deps, keys);
        } else {
            self.wb.calc_manual = true;
            sheetcore::formula::mark_pending(&mut self.wb, &deps, keys);
            self.status = "手动计算：已标记待计算（按 F9 或“开始计算”重算）".into();
        }
        self.deps = deps;
        if let (Some(peer), Some(net)) = (self.peer.as_mut(), self.net.as_ref()) {
            for (si, r, c) in keys.iter() {
                let cell = self.wb.sheet(*si).get(*r, *c).cloned().unwrap_or_default();
                let op = peer.local_set(*si, *r, *c, &cell);
                net.broadcast_op(op);
            }
        }
    }

    /// 双击填充柄时的终点：看左右相邻列谁有连续数据
    fn fill_down_limit(&self, c1: u32, c2: u32) -> u32 {
        let (_, _, r2, _) = self.sel_rect();
        let sh = self.wb.sheet(self.sheet_idx);
        let neighbour = if c1 > 0 && sh.get(r2 + 1, c1 - 1).is_some() {
            Some(c1 - 1)
        } else if sh.get(r2 + 1, c2 + 1).is_some() {
            Some(c2 + 1)
        } else {
            None
        };
        let Some(nc) = neighbour else {
            return r2;
        };
        let mut r = r2 + 1;
        while r < 1_048_576 && sh.get(r, nc).is_some() {
            r += 1;
        }
        r.saturating_sub(1)
    }

    /// Ctrl+D / Ctrl+R：用选区首行（首列）填满整个选区，公式按位移调整
    fn fill_cmd(&mut self, down: bool) {
        self.commit_edit(None);
        let (r1, c1, r2, c2) = self.sel_rect();
        if down && r2 == r1 {
            return;
        }
        if !down && c2 == c1 {
            return;
        }
        // 实际被写的是尾端目标区（首行/首列只是源），门禁按真实写入范围收集
        let gate = if down {
            sheetcore::undo::rect_keys(r1 + 1, c1, r2, c2)
        } else {
            sheetcore::undo::rect_keys(r1, c1 + 1, r2, c2)
        };
        if !self.write_preflight(
            &gate,
            if down { "向下填充" } else { "向右填充" },
        ) {
            return;
        }
        let keys = sheetcore::undo::rect_keys(r1, c1, r2, c2);
        let txn = self.txn_begin(&keys);
        if down {
            for c in c1..=c2 {
                let Some(src) = self.wb.sheet(self.sheet_idx).get(r1, c).cloned() else {
                    continue;
                };
                for r in (r1 + 1)..=r2 {
                    let mut cell = src.clone();
                    if let Some(f) = &src.formula {

                        cell.formula = Some(sheetcore::cf::shift_formula(f, r - r1, 0).into());
                    }
                    self.wb.sheet_mut(self.sheet_idx).set(r, c, cell);
                }
            }
        } else {
            for r in r1..=r2 {
                let Some(src) = self.wb.sheet(self.sheet_idx).get(r, c1).cloned() else {
                    continue;
                };
                for c in (c1 + 1)..=c2 {
                    let mut cell = src.clone();
                    if let Some(f) = &src.formula {

                        cell.formula = Some(sheetcore::cf::shift_formula(f, 0, c - c1).into());
                    }
                    self.wb.sheet_mut(self.sheet_idx).set(r, c, cell);
                }
            }
        }
        self.txn_end(if down { "向下填充" } else { "向右填充" }, txn);
        sheetcore::formula::recalc_all(&mut self.wb);
        self.deps = sheetcore::formula::deps::Deps::build(&self.wb);
        self.doc_gen = self.doc_gen.wrapping_add(1);
        self.wb.dirty = true;
        self.status = if down {
            format!("已用首行填充 {}-{} 行", r1 + 1, r2 + 1)
        } else {
            format!("已用首列填充到第 {} 列", c2 + 1)
        };
    }

    /// 验证下拉选中一项后真正写入（与网格内联逻辑同一个入口，便于门禁回归）。
    fn dv_pick_apply(&mut self, dr: u32, dc: u32, v: &str) -> bool {
        if !self.write_preflight(&[(dr, dc)], "选择验证下拉值") {
            self.dv_open = None;
            return false;
        }
        let cell = Cell {
            value: Value::parse_input(v),
            formula: None,
        };
        let key = (self.sheet_idx, dr, dc);
        self.wb.sheet_mut(self.sheet_idx).set(dr, dc, cell);
        self.wb.dirty = true;
        self.doc_gen = self.doc_gen.wrapping_add(1);
        self.deps.update_cell(&self.wb, key);
        sheetcore::formula::recalc_dirty(&mut self.wb, &self.deps, &[key]);
        true
    }

    /// 填充柄：把源区域按线性序列/复制的方式填到目标区域
    fn fill_to(&mut self, target_row: u32, vertical: bool) {
        let (r1, c1, r2, c2) = self.sel_rect();
        let gate = if vertical {
            sheetcore::undo::rect_keys(r1, c1, target_row.max(r2), c2)
        } else {
            // 横向填充写的是 target_row（此处是目标列）之前的整段，不能只查源区
            sheetcore::undo::rect_keys(r1, c1, r2, target_row.max(c2))
        };
        if !self.write_preflight(&gate, "填充") {
            return;
        }
        if vertical {
            if target_row <= r2 {
                return;
            }
            let src_h = r2 - r1 + 1;
            let keys = sheetcore::undo::rect_keys(r1, c1, target_row, c2);
            let txn = self.txn_begin(&keys);
            for c in c1..=c2 {
                // 取源列的数字，判断是不是等差
                let nums: Vec<Option<f64>> = (r1..=r2)
                    .map(|r| match self.wb.sheet(self.sheet_idx).get(r, c).map(|x| x.value.clone()) {
                        Some(sheetcore::model::Value::Number(n)) => Some(n),
                        _ => None,
                    })
                    .collect();
                let all_num = nums.iter().all(|x| x.is_some());
                let step = if all_num && src_h >= 2 {
                    let a = nums[0].unwrap();
                    let b = nums[1].unwrap();
                    Some(b - a)
                } else {
                    None
                };
                for r in r2 + 1..=target_row {
                    let cell = if let Some(st) = step {
                        let base = nums[0].unwrap();
                        let idx = (r - r1) as f64;
                        sheetcore::model::Cell {
                            value: sheetcore::model::Value::Number(base + st * idx),
                            formula: None,
                        }
                    } else {
                        let src_r = r1 + (r - r2 - 1) % src_h;
                        self.wb
                            .sheet(self.sheet_idx)
                            .get(src_r, c)
                            .cloned()
                            .unwrap_or(sheetcore::model::Cell {
                                value: sheetcore::model::Value::Empty,
                                formula: None,
                            })
                    };
                    self.wb.sheet_mut(self.sheet_idx).set(r, c, cell);
                }
            }
            self.txn_end("填充", txn);
            self.sel_end = (target_row, c2);
        } else {
            let target_col = target_row; // 横向时传列号
            if target_col <= c2 {
                return;
            }
            let src_w = c2 - c1 + 1;
            let keys = sheetcore::undo::rect_keys(r1, c1, r2, target_col);
            let txn = self.txn_begin(&keys);
            for r in r1..=r2 {
                let nums: Vec<Option<f64>> = (c1..=c2)
                    .map(|c| match self.wb.sheet(self.sheet_idx).get(r, c).map(|x| x.value.clone()) {
                        Some(sheetcore::model::Value::Number(n)) => Some(n),
                        _ => None,
                    })
                    .collect();
                let all_num = nums.iter().all(|x| x.is_some());
                let step = if all_num && src_w >= 2 {
                    Some(nums[1].unwrap() - nums[0].unwrap())
                } else {
                    None
                };
                for c in c2 + 1..=target_col {
                    let cell = if let Some(st) = step {
                        let base = nums[0].unwrap();
                        let idx = (c - c1) as f64;
                        sheetcore::model::Cell {
                            value: sheetcore::model::Value::Number(base + st * idx),
                            formula: None,
                        }
                    } else {
                        let src_c = c1 + (c - c2 - 1) % src_w;
                        self.wb
                            .sheet(self.sheet_idx)
                            .get(r, src_c)
                            .cloned()
                            .unwrap_or(sheetcore::model::Cell {
                                value: sheetcore::model::Value::Empty,
                                formula: None,
                            })
                    };
                    self.wb.sheet_mut(self.sheet_idx).set(r, c, cell);
                }
            }
            self.txn_end("填充", txn);
            self.sel_end = (r2, target_col);
        }
        self.wb.dirty = true;
        self.doc_gen = self.doc_gen.wrapping_add(1);
        let (a, b, c_, d) = self.sel_rect();
        let keys = sheetcore::undo::rect_keys(a, b, c_, d)
            .into_iter()
            .map(|(r, c)| (self.sheet_idx, r, c))
            .collect::<Vec<_>>();
        self.recalc_and_broadcast(&keys);
        self.status = "已填充".into();
    }

    /// 按内容自适应列宽
    fn autofit_col(&mut self, ctx: &egui::Context, col: u32) {
        let mut width: f32 = 24.0;
        let (_, _, r2, _) = self.wb.sheet(self.sheet_idx).used_bounds().unwrap_or((0, 0, 0, 0));
        for r in 0..=r2.min(5000) {
            let Some(cell) = self.wb.sheet(self.sheet_idx).get(r, col) else {
                continue;
            };
            let st = {
                let sh = self.wb.sheet(self.sheet_idx);
                self.wb.styles.get(sh.style_of(r, col)).clone()
            };
            let txt = sheetcore::style::format_value_in(self.wb.date_system, &cell.value, &st.format);
            if txt.is_empty() {
                continue;
            }
            // 和绘制用同一套字号/字族，量出来的才是真宽度
            let size = (if st.size > 0.0 { st.size } else { 11.0 }) * 4.0 / 3.0
                * self.paint_scale;
            let fam = cell_family(if st.font.is_empty() { "默认" } else { &st.font });
            let font = egui::FontId::new(if st.bold { size + 0.8 } else { size }, fam);
            let w = ctx.fonts(|f| {
                f.layout_no_wrap(txt.clone(), font.clone(), egui::Color32::BLACK)
                    .size()
                    .x
            });
            if std::env::var("SC_AUTOFIT").is_ok() {
                eprintln!(
                    "[autofit]   r{r} txt={:?} len={} galley={:.1} size={:.1} bold={}",
                    txt.chars().take(12).collect::<String>(),
                    txt.chars().count(),
                    w,
                    size,
                    st.bold
                );
            }
            // 左边 4px 起始 + 右边留 6px，再加一点余量避免最后一个字被切
            width = width.max(w + 16.0 + st.indent as f32 * size * 2.0);
        }
        let width = width.clamp(24.0, 1500.0);
        {
            let sh = self.wb.sheet_mut(self.sheet_idx);
            sh.cols.set(col, width);
            sh.layout_dirty = true;
        }
        self.wb.dirty = true;
        self.doc_gen = self.doc_gen.wrapping_add(1);
        self.status = format!(
            "{} 列宽已自适应：{:.0}px",
            cell_name(0, col).trim_end_matches('1'),
            width
        );
    }

    /// 按内容自适应行高（自动换行时按折行数算，用真实字形量）
    fn autofit_row(&mut self, ctx: &egui::Context, row: u32) {
        let (_, c1, _, c2) = self
            .wb
            .sheet(self.sheet_idx)
            .used_bounds()
            .unwrap_or((0, 0, 0, 0));
        let mut best: f32 = 15.0;
        for c in c1..=c2 {
            let Some(cell) = self.wb.sheet(self.sheet_idx).get(row, c) else {
                continue;
            };
            let st = {
                let sh = self.wb.sheet(self.sheet_idx);
                self.wb.styles.get(sh.style_of(row, c)).clone()
            };
            let txt = sheetcore::style::format_value_in(self.wb.date_system, &cell.value, &st.format);
            if txt.is_empty() {
                continue;
            }
            let size =
                (if st.size > 0.0 { st.size } else { 11.0 }) * 4.0 / 3.0 * self.paint_scale;
            let fam = cell_family(if st.font.is_empty() { "默认" } else { &st.font });
            let font = egui::FontId::new(if st.bold { size + 0.8 } else { size }, fam);
            let col_w = self.wb.sheet(self.sheet_idx).cols.size(c);
            let h = if st.wrap {
                ctx.fonts(|f| {
                    f.layout(
                        txt.clone(),
                        font.clone(),
                        egui::Color32::BLACK,
                        (col_w - 6.0).max(8.0),
                    )
                    .size()
                    .y
                })
            } else {
                ctx.fonts(|f| {
                    f.layout_no_wrap(txt.clone(), font.clone(), egui::Color32::BLACK)
                        .size()
                        .y
                })
            };
            best = best.max(h + 5.0);
        }
        let h = best.clamp(15.0, 409.0);
        {
            let sh = self.wb.sheet_mut(self.sheet_idx);
            sh.rows.set(row, h);
            sh.layout_dirty = true;
        }
        self.wb.dirty = true;
        self.doc_gen = self.doc_gen.wrapping_add(1);
        self.status = format!("第 {} 行行高已自适应：{:.0}px", row + 1, h);
    }

    // ===== 数据工具 =====
    fn open_data_dlg(&mut self, tab: u8) {
        let (r1, c1, r2, c2) = self.sel_rect();
        let header = sheetcore::sort_filter::has_header(self.wb.sheet(self.sheet_idx), r1, c1, r2, c2);
        let keys = (c1..=c2).map(|c| (c, true, c == c1)).collect();
        self.data_dlg = Some(DataDlg { tab, keys, header, delim: ",".into() });
    }

    fn run_sort(&mut self, dlg: &DataDlg) {
        let (r1, c1, r2, c2) = self.sel_rect();
        if !self.write_preflight(&sheetcore::undo::rect_keys(r1, c1, r2, c2), "排序") {
            return;
        }
        if let Err(error) = sheetcore::sort_filter::validate_sort_region(
            self.wb.sheet(self.sheet_idx), (r1, c1, r2, c2),
        ) {
            self.status = error;
            return;
        }
        let keys: Vec<sheetcore::data_tools::SortKey> = dlg
            .keys
            .iter()
            .filter(|(_, _, on)| *on)
            .map(|(c, asc, _)| sheetcore::data_tools::SortKey {
                col: *c,
                asc: *asc,
                ignore_case: true,
            })
            .collect();
        if keys.is_empty() {
            self.status = "至少选一列排序".into();
            return;
        }
        let txn = self.txn_begin(&sheetcore::undo::rect_keys(r1, c1, r2, c2));
        let moved = sheetcore::data_tools::sort_multi(
            self.wb.sheet_mut(self.sheet_idx),
            (r1, c1, r2, c2),
            &keys,
            dlg.header,
        );
        self.txn_end("多级排序", txn);
        self.wb.dirty = true;
        self.doc_gen = self.doc_gen.wrapping_add(1);
        sheetcore::formula::recalc_all(&mut self.wb);
        self.deps = sheetcore::formula::deps::Deps::build(&self.wb);
        self.status = format!("已按 {} 个键排序（{} 行移动）", keys.len(), moved);
    }

    fn run_dedup(&mut self) {
        let (r1, c1, r2, c2) = self.sel_rect();
        if !self.write_preflight(&sheetcore::undo::rect_keys(r1, c1, r2, c2), "删除重复") {
            return;
        }
        let header = sheetcore::sort_filter::has_header(self.wb.sheet(self.sheet_idx), r1, c1, r2, c2);
        let txn = self.txn_begin(&sheetcore::undo::rect_keys(r1, c1, r2, c2));
        let removed = sheetcore::data_tools::remove_duplicates(
            self.wb.sheet_mut(self.sheet_idx),
            (r1, c1, r2, c2),
            &[],
            header,
        );
        self.txn_end("删除重复", txn);
        self.wb.dirty = true;
        self.doc_gen = self.doc_gen.wrapping_add(1);
        self.status = if removed == 0 {
            "没有重复行".into()
        } else {
            format!("删除了 {removed} 行重复")
        };
    }

    fn run_split(&mut self, delim: char) {
        let (r1, c1, r2, c2) = self.sel_rect();
        if !self.write_preflight(&sheetcore::undo::rect_keys(r1, c1, r2, c2), "分列") {
            return;
        }
        let txn = self.txn_begin(&sheetcore::undo::rect_keys(r1, c1, r2, c2));
        let n = sheetcore::data_tools::text_to_columns(
            self.wb.sheet_mut(self.sheet_idx),
            (r1, c1, r2, c2),
            delim,
        );
        self.txn_end("分列", txn);
        self.wb.dirty = true;
        self.doc_gen = self.doc_gen.wrapping_add(1);
        self.status = if n <= 1 {
            "没有找到分隔符".into()
        } else {
            format!("已分成 {n} 列")
        };
    }

    /// 打印预览：按页面设置分页，把每一页画成一张纸
    fn print_preview_window(&mut self, ctx: &egui::Context) {
        if !self.print_preview {
            return;
        }
        let mut open = true;
        let mut goto_page: Option<usize> = None;
        let mut do_print = false;
        let mut do_export = false;
        // 先把要画的东西取出来，别在闭包里借 self
        let (layout, cols, rows, texts, page_no, total) = {
            let sheet = self.wb.sheet(self.sheet_idx);
            let layout = sheetcore::print::paginate(sheet, &sheet.page);
            let total = layout.pages.len().max(1);
            let page_no = self.preview_page.min(total - 1);
            let span = layout
                .pages
                .get(page_no)
                .cloned()
                .unwrap_or(sheetcore::print::PageSpan { rows: (0, 0), cols: (0, 0) });
            let mut texts: Vec<(u32, u32, String)> = Vec::new();
            for r in span.rows.0..=span.rows.1 {
                for c in span.cols.0..=span.cols.1 {
                    if let Some(cell) = sheet.get(r, c) {
                        let t = cell.value.display();
                        if !t.is_empty() {
                            texts.push((r, c, t));
                        }
                    }
                }
            }
            (
                layout,
                sheet.cols.clone(),
                sheet.rows.clone(),
                texts,
                page_no,
                total,
            )
        };
        let span = layout
            .pages
            .get(page_no)
            .cloned()
            .unwrap_or(sheetcore::print::PageSpan { rows: (0, 0), cols: (0, 0) });
        let (pw, ph) = layout.page_size;
        let (print_w, print_h) = layout.printable;
        let page_h = 560.0f32;
        let page_w = page_h * pw / ph;
        let scale_preview = page_h / ph;
        let margins = self.wb.sheet(self.sheet_idx).page.margins;
        let scale_txt = layout.scale;

        ui_kit::window(ctx, "打印预览", 420.0)
            .open(&mut open)
            .default_width(page_w + 280.0)
            .show(ctx, |ui| {
                ui.horizontal(|ui| {
                    if ui.button("◀").clicked() && page_no > 0 {
                        goto_page = Some(page_no - 1);
                    }
                    ui.label(format!("第 {} / {} 页", page_no + 1, total));
                    if ui.button("▶").clicked() && page_no + 1 < total {
                        goto_page = Some(page_no + 1);
                    }
                    ui.separator();
                    ui.label(format!(
                        "纸张 {pw:.0}×{ph:.0}pt 缩放 {:.0}%",
                        scale_txt * 100.0
                    ));
                    ui.separator();
                    if ui.button("打印…").clicked() {
                        do_print = true;
                    }
                    if ui.button("导出 PDF…").clicked() {
                        do_export = true;
                    }
                });
                ui.separator();
                egui::ScrollArea::both().show(ui, |ui| {
                    let (resp, painter) =
                        ui.allocate_painter(egui::vec2(page_w, page_h), egui::Sense::hover());
                    let page_rect = resp.rect;
                    painter.rect_filled(page_rect, 2.0, egui::Color32::WHITE);
                    painter.rect_stroke(
                        page_rect,
                        2.0,
                        egui::Stroke::new(1.0, egui::Color32::from_gray(150)),
                        egui::StrokeKind::Inside,
                    );
                    let inner = egui::Rect::from_min_max(
                        page_rect.min
                            + egui::vec2(
                                margins[0] * 72.0 * scale_preview,
                                margins[2] * 72.0 * scale_preview,
                            ),
                        page_rect.max
                            - egui::vec2(
                                margins[1] * 72.0 * scale_preview,
                                margins[3] * 72.0 * scale_preview,
                            ),
                    );
                    painter.rect_stroke(
                        inner,
                        0.0,
                        egui::Stroke::new(0.8, egui::Color32::from_gray(205)),
                        egui::StrokeKind::Inside,
                    );

                    // 一页内容的原始尺寸（96 DPI 像素）
                    let mut content_w = 0.0f32;
                    for c in span.cols.0..=span.cols.1 {
                        content_w += cols.size(c);
                    }
                    let mut content_h = 0.0f32;
                    for r in span.rows.0..=span.rows.1 {
                        content_h += rows.size(r);
                    }
                    let fit = (print_w * scale_preview / content_w.max(1.0))
                        .min(print_h * scale_preview / content_h.max(1.0));
                    let cell_scale = fit * scale_txt;

                    let mut y = inner.min.y;
                    for r in span.rows.0..=span.rows.1 {
                        let h = rows.size(r) * cell_scale;
                        if y > inner.max.y + 1.0 {
                            break;
                        }
                        let mut x = inner.min.x;
                        painter.line_segment(
                            [egui::pos2(inner.min.x, y), egui::pos2(inner.max.x, y)],
                            egui::Stroke::new(0.4, egui::Color32::from_gray(225)),
                        );
                        for c in span.cols.0..=span.cols.1 {
                            let w = cols.size(c) * cell_scale;
                            if x > inner.max.x + 1.0 {
                                break;
                            }
                            if let Some((_, _, t)) =
                                texts.iter().find(|(rr, cc, _)| *rr == r && *cc == c)
                            {
                                let fs = (11.0 * cell_scale * 1.05).clamp(4.0, 15.0);
                                let per = (fs * 0.62).max(1.0);
                                let max_chars = ((w - 2.0).max(1.0) / per) as usize + 1;
                                let clipped: String = t.chars().take(max_chars).collect();
                                painter.text(
                                    egui::pos2(x + 1.0, y + 1.0),
                                    egui::Align2::LEFT_TOP,
                                    clipped,
                                    egui::FontId::proportional(fs),
                                    egui::Color32::BLACK,
                                );
                            }
                            painter.line_segment(
                                [egui::pos2(x, y), egui::pos2(x, (y + h).min(inner.max.y))],
                                egui::Stroke::new(0.4, egui::Color32::from_gray(225)),
                            );
                            x += w;
                        }
                        y += h;
                    }
                    if std::env::var("SC_PREVIEW").is_ok() {
                        eprintln!(
                            "[preview] page={}/{} rows={:?} cols={:?} scale={:.2} paper={:.0}x{:.0} cells={}",
                            page_no + 1,
                            total,
                            span.rows,
                            span.cols,
                            scale_txt,
                            pw,
                            ph,
                            texts.len()
                        );
                    }
                });
            });
        if let Some(p) = goto_page {
            self.preview_page = p;
        }
        if do_export {
            self.export_pdf_dialog();
        }
        if do_print {
            self.print_to_printer();
        }
        self.print_preview = open;
    }

    /// 真打印：先导出 PDF，再交给系统默认处理程序打印
    fn print_to_printer(&mut self) {
        let path = std::env::temp_dir().join(format!(
            "sheetcore-print-{}.pdf",
            std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .map(|d| d.as_secs())
                .unwrap_or(0)
        ));
        let font = std::path::Path::new("C:/Windows/Fonts/simhei.ttf");
        match sheetcore::print::export_pdf(&self.wb, self.sheet_idx, &path, font) {
            Ok(_) => {
                let p = path.to_string_lossy().to_string();
                let r = std::process::Command::new("powershell")
                    .args([
                        "-NoProfile",
                        "-Command",
                        &format!("Start-Process -FilePath '{p}' -Verb Print"),
                    ])
                    .spawn();
                self.status = match r {
                    Ok(_) => format!("已交给系统打印：{p}"),
                    Err(e) => format!("打印失败：{e}"),
                };
            }
            Err(e) => self.status = format!("生成打印文件失败：{e:#}"),
        }
    }

    fn export_pdf_dialog(&mut self) {
        let Some(path) = rfd::FileDialog::new()
            .set_file_name(format!("{}.pdf", self.wb.title()))
            .add_filter("PDF", &["pdf"])
            .save_file()
        else {
            return;
        };
        let font = std::path::Path::new("C:/Windows/Fonts/simhei.ttf");
        match sheetcore::print::export_pdf(&self.wb, self.sheet_idx, &path, font) {
            Ok(_) => self.status = format!("已导出 {}", path.display()),
            Err(e) => self.status = format!("导出失败：{e:#}"),
        }
    }

    /// 解一张图片并缓存纹理（解不出来就记 None，不反复重试）
    fn img_texture(
        &mut self,
        key: &str,
        part: &str,
        ctx: &egui::Context,
    ) -> Option<egui::TextureHandle> {
        if let Some(v) = self.img_cache.get(key) {
            return v.clone();
        }
        let loaded = (|| {
            let path = self.wb.path.as_ref()?;
            let bytes = sheetcore::pic::read_part(path, part)?;
            let img = image::load_from_memory(&bytes).ok()?.to_rgba8();
            let size = [img.width() as usize, img.height() as usize];
            let color = egui::ColorImage::from_rgba_unmultiplied(size, img.as_raw());
            Some(ctx.load_texture(key.to_string(), color, egui::TextureOptions::LINEAR))
        })();
        self.img_cache.insert(key.to_string(), loaded.clone());
        loaded
    }

    /// 导入 CSV/TSV 到当前选区左上角
    fn import_csv(&mut self) {
        let Some(path) = rfd::FileDialog::new()
            .add_filter("CSV / TSV", &["csv", "tsv", "txt"])
            .pick_file()
        else {
            return;
        };
        self.open_csv_dialog(&path);
    }

    /// 选一个工作簿，把它的每张表复制到当前工作簿末尾（值 + 公式）
    fn import_workbook(&mut self) {
        let Some(path) = rfd::FileDialog::new()
            .add_filter("Excel 工作簿", &["xlsx", "xlsm", "xls"])
            .pick_file()
        else {
            return;
        };
        let other = match sheetcore::xlsx::load(&path) {
            Ok(w) => w,
            Err(e) => {
                self.status = format!("打开失败：{e:#}");
                return;
            }
        };
        let txn = self.txn_begin(&[]);
        let mut added: Vec<String> = Vec::new();
        for src in other.sheets.iter() {
            let mut name = src.name.clone();
            let mut n = 2;
            while self.wb.sheets.iter().any(|s| s.name == name) {
                name = format!("{} ({n})", src.name);
                n += 1;
            }
            let mut sheet = src.clone();
            sheet.name = name.clone();
            sheet.charts.clear();
            sheet.tables.clear();
            added.push(name);
            self.wb.sheets.push(sheet);
        }
        let n = added.len();
        if let Some(first) = self.wb.sheets.len().checked_sub(n) {
            self.sheet_idx = first;
        }
        self.sel = (0, 0);
        self.sel_end = self.sel;
        self.txn_end("导入工作簿", txn);
        self.wb.dirty = true;
        self.doc_gen = self.doc_gen.wrapping_add(1);
        self.status = if n == 0 {
            "目标文件里没有工作表".into()
        } else {
            format!("已导入 {n} 张表：{}", added.join("、"))
        };
    }

    /// C09：选文件后先打开选项对话框（编码/引号/表头/文本列 + 真实预览）
    fn open_csv_dialog(&mut self, path: &std::path::Path) {
        let Ok(bytes) = std::fs::read(path) else {
            self.status = format!("读不了 {}", path.display());
            return;
        };
        let (text, enc, _bad) = sheetcore::csv::decode(&bytes, None);
        let delim = sheetcore::csv::sniff(&text);
        let preview = sheetcore::csv::records_strict_q(&text, delim, '"').unwrap_or_default();
        self.csv_dlg = Some(CsvDlg {
            path: path.to_path_buf(),
            bytes,
            delim,
            header: false,
            enc: Some(enc),
            quote: '"',
            text_cols: std::collections::BTreeSet::new(),
            preview,
            err: None,
        });
    }

    /// 对话框里的选项变了：按当前编码/引号重新解析预览
    fn csv_dlg_reload(&mut self) {
        let Some(dlg) = self.csv_dlg.as_mut() else { return };
        let (text, _enc, bad) = sheetcore::csv::decode(&dlg.bytes, dlg.enc);
        if bad {
            dlg.preview.clear();
            dlg.err = Some("所选编码无法完整解码这个文件".into());
            return;
        }
        match sheetcore::csv::records_strict_q(&text, dlg.delim, dlg.quote) {
            Ok(rows) => {
                dlg.err = None;
                dlg.preview = rows;
            }
            Err(e) => {
                dlg.preview.clear();
                dlg.err = Some(e);
            }
        }
    }

    fn csv_dlg_ui(&mut self, ctx: &egui::Context) {
        let Some(mut dlg) = self.csv_dlg.take() else { return };
        let mut close = false;
        let mut import = false;
        let mut changed = false;
        egui::Window::new("导入 CSV")
            .collapsible(false)
            .resizable(true)
            .default_width(560.0)
            .show(ctx, |ui| {
                ui.label(format!("文件：{}", dlg.path.display()));
                ui.horizontal(|ui| {
                    ui.label("编码");
                    let label = match dlg.enc {
                        None => "自动".to_string(),
                        Some(e) => e.id().to_string(),
                    };
                    egui::ComboBox::from_id_salt("csv_enc")
                        .selected_text(label)
                        .show_ui(ui, |ui| {
                            if ui.selectable_label(dlg.enc.is_none(), "自动（BOM/UTF-8/GB18030）").clicked() {
                                dlg.enc = None;
                                changed = true;
                            }
                            for e in [
                                sheetcore::csv::Encoding::Utf8,
                                sheetcore::csv::Encoding::Utf16Le,
                                sheetcore::csv::Encoding::Gb18030,
                            ] {
                                if ui.selectable_label(dlg.enc == Some(e), e.id()).clicked() {
                                    dlg.enc = Some(e);
                                    changed = true;
                                }
                            }
                        });
                    ui.separator();
                    ui.label("引号");
                    let mut q = dlg.quote.to_string();
                    if ui.add(egui::TextEdit::singleline(&mut q).desired_width(28.0)).changed() {
                        if let Some(c) = q.chars().next() {
                            dlg.quote = c;
                            changed = true;
                        }
                    }
                    ui.separator();
                    if ui.checkbox(&mut dlg.header, "首行是表头").changed() {
                        changed = true;
                    }
                });
                ui.label("勾选下面的列按文本导入（保留 00123、18 位账号这类前导零）：");
                egui::ScrollArea::both().max_height(260.0).show(ui, |ui| {
                    egui::Grid::new("csv_preview").striped(true).show(ui, |ui| {
                        let cols = dlg.preview.iter().map(|r| r.len()).max().unwrap_or(0);
                        for c in 0..cols {
                            let mut on = dlg.text_cols.contains(&(c as u32));
                            if ui.checkbox(&mut on, format!("第 {} 列", c + 1)).changed() {
                                if on {
                                    dlg.text_cols.insert(c as u32);
                                } else {
                                    dlg.text_cols.remove(&(c as u32));
                                }
                            }
                        }
                        ui.end_row();
                        for row in dlg.preview.iter().take(8) {
                            for c in 0..cols {
                                ui.label(row.get(c).cloned().unwrap_or_default());
                            }
                            ui.end_row();
                        }
                    });
                });
                if let Some(e) = &dlg.err {
                    ui.colored_label(egui::Color32::RED, e);
                }
                ui.horizontal(|ui| {
                    if ui.button("取消").clicked() {
                        close = true;
                    }
                    if ui.add_enabled(dlg.err.is_none(), egui::Button::new("导入")).clicked() {
                        import = true;
                    }
                });
            });
        if changed {
            self.csv_dlg = Some(dlg);
            self.csv_dlg_reload();
        } else {
            self.csv_dlg = Some(dlg);
        }
        if import {
            let d = self.csv_dlg.as_ref().unwrap();
            let (path, delim, header, enc, quote) =
                (d.path.clone(), d.delim, d.header, d.enc, d.quote);
            let cols: Vec<u32> = d.text_cols.iter().copied().collect();
            self.csv_dlg = None;
            self.import_csv_choice(&path, delim, header, enc, quote, &cols);
        } else if close {
            self.csv_dlg = None;
        }
    }

    fn import_csv_from(&mut self, path: &std::path::Path) {
        self.import_csv_choice(path, ',', false, None, '"', &[]);
    }

    /// C09：按用户在导入对话框里选的编码/引号/文本列导入，并把选择持久化到数据源。
    fn import_csv_choice(
        &mut self,
        path: &std::path::Path,
        delim: char,
        header: bool,
        enc: Option<sheetcore::csv::Encoding>,
        quote: char,
        text_cols: &[u32],
    ) {
        let bytes = match std::fs::read(path) {
            Ok(b) => b,
            Err(e) => {
                self.status = format!("读不了 {}：{e}", path.display());
                return;
            }
        };
        let (text, _used, bad) = sheetcore::csv::decode(&bytes, enc);
        if bad {
            self.status = "这个文件用所选编码解不出来（没有写入任何格）".into();
            return;
        }
        let delim = if delim == ',' && !text.lines().next().unwrap_or("").contains(',') {
            sheetcore::csv::sniff(&text)
        } else {
            delim
        };
        let probe = match sheetcore::csv::records_strict_q(&text, delim, quote) {
            Ok(p) => p,
            Err(e) => {
                self.status = format!("CSV 解析失败（没有写入任何格）：{e}");
                return;
            }
        };
        if probe.is_empty() {
            self.status = "这个文件里没有可导入的内容".into();
            return;
        }
        let (r0, c0) = self.sel;
        let max_r = probe.len() as u32;
        let max_c = probe.iter().map(|r| r.len()).max().unwrap_or(0) as u32;
        let mut keys: Vec<(u32, u32)> = Vec::new();
        for r in 0..max_r {
            for c in 0..max_c {
                keys.push((r0 + r, c0 + c));
            }
        }
        let txn = self.txn_begin(&keys);
        let (size, used_enc) = match sheetcore::external::import_csv_opts(
            self.wb.sheet_mut(self.sheet_idx),
            &path.to_string_lossy(),
            delim,
            header,
            enc,
            text_cols,
            quote,
            (0, 0),
            (r0, c0),
        ) {
            Ok((rows, cols, enc)) => ((rows, cols), enc),
            Err(e) => {
                for d in &txn {
                    self.wb.sheet_mut(self.sheet_idx).set(d.row, d.col, d.before.clone());
                }
                self.status = format!("导入 CSV 失败：{e}");
                return;
            }
        };
        self.txn_end("导入 CSV", txn);
        self.wb.dirty = true;
        self.doc_gen = self.doc_gen.wrapping_add(1);
        let stored_path = sheetcore::external::store_path(&self.wb, path);
        let key = (stored_path.clone(), r0, c0);
        let existing = self.wb.sources.iter_mut().find(|src| match &src.kind {
            sheetcore::external::Kind::Csv { path: p, .. } => {
                (p.clone(), src.at.0, src.at.1) == key
            }
            _ => false,
        });
        let opts = sheetcore::external::CsvOpts {
            encoding: Some(used_enc),
            text_cols: text_cols.to_vec(),
            quote,
        };
        match existing {
            Some(src) => {
                src.rows = size.0;
                src.cols = size.1;
                src.csv_opts = Some(opts);
            }
            None => {
                let src = sheetcore::external::Source {
                    name: String::new(),
                    kind: sheetcore::external::Kind::Csv {
                        path: stored_path,
                        delim,
                        header,
                    },
                    at: (r0, c0),
                    rows: size.0,
                    cols: size.1,
                    csv_opts: Some(opts),
                };
                self.wb.sources.push(src);
                let mut n = self.wb.sources.len();
                loop {
                    let name = format!("_sc_src_{n}");
                    if !self.wb.sources.iter().any(|s| s.name == name) {
                        self.wb.sources.last_mut().unwrap().name = name;
                        break;
                    }
                    n += 1;
                }
            }
        }
        self.status = format!("已导入 {} 行 × {} 列", size.0, size.1);
    }

    /// 刷新数据：优先按登记过的数据源重读，没有就退回"上次导入"
    fn refresh_import(&mut self) {
        if self.wb.sources.is_empty() {
            match self.last_import.clone() {
                Some((path, r, c)) => {
                    self.sel = (r, c);
                    self.sel_end = (r, c);
                    self.import_csv_from(&path);
                }
                None => self.status = "还没有导入过外部数据".into(),
            }
            return;
        }
        let idx = self.sheet_idx;
        let sources = self.wb.sources.clone();
        let before_sizes: Vec<(String, u32, u32)> =
            sources.iter().map(|s| (s.name.clone(), s.rows, s.cols)).collect();
        // 刷新是一步可撤销操作：整表快照 + 源尺寸前后值
        let snap_before = sheetcore::undo::snapshot_sheet(self.wb.sheet(idx), idx);
        let mut ok = 0;
        let mut fail = 0;
        for mut src in sources {
            match sheetcore::external::refresh(&mut self.wb, idx, &src) {
                Ok((rows, cols)) => {
                    ok += 1;
                    // 行数变了就更新记录，下次保存写回去
                    if let Some(slot) = self.wb.sources.iter_mut().find(|s| s.name == src.name) {
                        slot.rows = rows;
                        slot.cols = cols;
                    }
                    src.rows = rows;
                }
                Err(_) => fail += 1,
            }
        }
        if ok > 0 {
            let snap_after = sheetcore::undo::snapshot_sheet(self.wb.sheet(idx), idx);
            let after_sizes: Vec<(String, u32, u32)> =
                self.wb.sources.iter().map(|s| (s.name.clone(), s.rows, s.cols)).collect();
            self.undo.push(sheetcore::undo::Action {
                label: "刷新外部数据".into(),
                merges: None,
                deltas: Vec::new(),
                focus: (idx, self.sel.0, self.sel.1),
                snap_before: Some(snap_before),
                snap_after: Some(snap_after),
                by_site: 0,
                shapes: None,
                refresh_sizes: Some((before_sizes, after_sizes)),
            });
        }
        self.doc_gen = self.doc_gen.wrapping_add(1);
        self.wb.dirty = true;
        self.status = if fail == 0 {
            format!("已刷新 {ok} 个数据源")
        } else {
            format!("刷新完成：成功 {ok}，失败 {fail}")
        };
    }


    /// 把从 Excel 复制来的块贴进来：值 + 格式 + 合并
    fn paste_office_block(&mut self, block: &office_clipboard::OfficeBlock) -> bool {
        if block.is_empty() {
            return false;
        }
        let (r0, c0) = self.sel;
        let cols = block.cols() as u32;
        let rows = block.rows.len() as u32;
        if (rows as u64) * (cols as u64) > 200_000 {
            self.status = "粘贴区域太大（超过 20 万格），改用纯文本粘贴".into();
            return false;
        }

        let keys = sheetcore::undo::rect_keys(r0, c0, r0 + rows - 1, c0 + cols - 1);
        let txn = self.txn_begin(&keys);
        let mut merges: Vec<(u32, u32, u32, u32)> = Vec::new();
        let si = self.sheet_idx;

        for (ri, row) in block.rows.iter().enumerate() {
            let mut ci: u32 = 0;
            for cell in row {
                let r = r0 + ri as u32;
                let c = c0 + ci;
                // 值：带公式的按缓存值类型走，之后统一重算
                let text = cell.text.trim();
                let value = if cell.formula.is_some() {
                    match cell.kind {
                        0 => text
                            .replace(',', "")
                            .parse::<f64>()
                            .map(Value::Number)
                            .unwrap_or(Value::Empty),
                        2 => Value::Bool(text == "1" || text.eq_ignore_ascii_case("true")),
                        4 => sheetcore::formula::ErrKind::from_text(text)
                            .map(Value::Error)
                            .unwrap_or(Value::Text(text.into())),
                        _ => {
                            if text.is_empty() {
                                Value::Empty
                            } else {
                                Value::Text(text.into())
                            }
                        }
                    }
                } else if text.is_empty() {
                    Value::Empty
                } else if cell.kind == 4 {
                    // 从 Excel 复制的错误格：还原成错误值，别当文本也别当 0
                    sheetcore::formula::ErrKind::from_text(text)
                        .map(Value::Error)
                        .unwrap_or_else(|| Value::Text(text.into()))
                } else if cell.kind == 3 {
                    // 从 Excel/WPS 复制的日期：XMLSS 给的是 ISO 文本，不是序列号。
                    // 按**目标簿的日期体系**重算序列号（1900/1904 差 1462 天），
                    // 顺手补一个日期格式，否则粘进来是 45293 这样的裸数字。
                    match sheetcore::clipboard_xmlss::iso_to_serial(self.wb.date_system, text) {
                        Some((serial, _)) => {
                            if cell.num_format.trim().is_empty() {
                                let sid = self.wb.styles.intern(sheetcore::style::CellStyle {
                                    format: "yyyy-mm-dd".into(),
                                    ..Default::default()
                                });
                                self.wb.sheet_mut(si).set_style(r, c, sid);
                            }
                            Value::Number(serial)
                        }
                        None => Value::Text(text.into()),
                    }
                } else if let Ok(n) = text.replace(',', "").parse::<f64>() {
                    Value::Number(n)
                } else {
                    Value::Text(text.into())
                };
                self.wb.sheet_mut(si).set(
                    r,
                    c,
                    Cell { value, formula: cell.formula.as_deref().map(|f| f.into()) },
                );

                // 格式
                let base_id = self.wb.sheet(si).style_of(r, c);
                let mut st = self.wb.styles.get(base_id).clone();
                let mut touched = false;
                if cell.bold != st.bold {
                    st.bold = cell.bold;
                    touched = true;
                }
                if cell.italic != st.italic {
                    st.italic = cell.italic;
                    touched = true;
                }
                if let Some(fill) = cell.fill {
                    st.fill = Some(fill);
                    touched = true;
                }
                if let Some(color) = cell.color {
                    st.color = color;
                    touched = true;
                }
                if cell.halign != 0 && cell.halign != st.halign {
                    st.halign = cell.halign;
                    touched = true;
                }
                if let Some(bc) = cell.border {
                    for side in st.border.iter_mut() {
                        if side.style == 0 {
                            side.style = 1;
                            side.color = bc;
                        }
                    }
                    touched = true;
                }
                // XML Spreadsheet 还带了字体名/字号/数字格式，HTML 那条路没有
                if !cell.font.is_empty() {
                    let f = sheetcore::style::normalize_font(&cell.font);
                    if f != st.font {
                        st.font = f;
                        touched = true;
                    }
                }
                if cell.size > 0.0 && (cell.size - st.size).abs() > 0.01 {
                    st.size = cell.size;
                    touched = true;
                }
                if !cell.num_format.is_empty() && cell.num_format != st.format {
                    st.format = cell.num_format.clone();
                    touched = true;
                }
                if touched {
                    let id = self.wb.styles.intern(st.clone());
                    self.wb.sheet_mut(si).set_style(r, c, id);
                }

                // 合并
                if cell.colspan > 1 || cell.rowspan > 1 {
                    merges.push((r, c, r + cell.rowspan - 1, c + cell.colspan - 1));
                }
                ci += cell.colspan.max(1);
            }
        }

        if !merges.is_empty() {
            let sheet = self.wb.sheet_mut(si);
            for m in merges {
                if !sheet.merges.iter().any(|x| x.0 == m.0 && x.1 == m.1 && x.2 == m.2 && x.3 == m.3) {
                    sheet.merges.push(m);
                }
            }
            sheet.merges_dirty = true;
        }

        // 公式要立刻算出来（Excel 复制过来的是 R1C1 折算后的 A1）
        let fkeys: Vec<(usize, u32, u32)> = (0..rows)
            .flat_map(|ri| (0..cols).map(move |ci| (r0 + ri, c0 + ci)))
            .filter(|(r, c)| {
                self.wb
                    .sheet(si)
                    .get(*r, *c)
                    .map(|x| x.formula.is_some())
                    .unwrap_or(false)
            })
            .map(|(r, c)| (si, r, c))
            .collect();
        if !fkeys.is_empty() {
            for k in &fkeys {
                self.deps.update_cell(&self.wb, *k);
            }
            sheetcore::formula::recalc_dirty(&mut self.wb, &self.deps, &fkeys);
        }

        self.txn_end("从 Excel 粘贴", txn);
        self.wb.dirty = true;
        self.doc_gen = self.doc_gen.wrapping_add(1);
        self.sel_end = (r0 + rows - 1, c0 + cols - 1);
        self.status = format!("已粘贴 Excel 区域 {rows} 行 × {cols} 列（含格式与合并）");
        eprintln!("[paste] office 块 {rows}x{cols}");
        true
    }

    /// 把选区转成 Excel 表格对象（ListObject），首行当列名
    fn make_table(&mut self) {
        let (r1, c1, r2, c2) = self.sel_rect();
        if r2 - r1 < 1 || c2 == c1 {
            self.status = "表格至少要两行两列（首行是列名）".into();
            return;
        }
        let mut names: Vec<String> = Vec::new();
        for c in c1..=c2 {
            let v = self
                .wb
                .sheet(self.sheet_idx)
                .get(r1, c)
                .map(|x| x.value.display())
                .unwrap_or_default();
            names.push(if v.trim().is_empty() {
                format!("列{}", c - c1 + 1)
            } else {
                v
            });
        }
        // 名字不能重复，Excel 也不允许
        let mut seen: std::collections::HashSet<String> = std::collections::HashSet::new();
        for i in 0..names.len() {
            let mut base = names[i].clone();
            let mut k = 2;
            while seen.contains(&base.to_lowercase()) {
                base = format!("{}_{k}", names[i]);
                k += 1;
            }
            seen.insert(base.to_lowercase());
            names[i] = base;
        }
        let existing: std::collections::HashSet<String> = self
            .wb
            .sheet(self.sheet_idx)
            .tables
            .iter()
            .map(|t| t.name.to_lowercase())
            .collect();
        let mut n = 1usize;
        while existing.contains(&format!("table{n}")) {
            n += 1;
        }
        let name = format!("Table{n}");
        let t = sheetcore::table::Table {
                column_ids: Vec::new(),
            name: name.clone(),
            display: name.clone(),
            range: (r1, c1, r2, c2),
            columns: names,
            header_row: true,
            totals_row: false,
        };
        {
            let sh = self.wb.sheet_mut(self.sheet_idx);
            sh.tables.push(t);
            sh.tables_dirty = true;
            // Excel 建表默认带筛选按钮
            sh.filter = Some(sheetcore::sort_filter::Filter::new(r1, c1, r2, c2));
            sh.filter_dirty = true;
        }
        self.wb.dirty = true;
        self.doc_gen = self.doc_gen.wrapping_add(1);
        self.status = format!("已创建表格 {}（{}）", name, sheetcore::table::a1((r1, c1, r2, c2)));
    }

    /// 在线成员：谁在哪儿，点一下跳过去
    fn members_window(&mut self, ctx: &egui::Context) {
        if !self.members_open {
            return;
        }
        let mut open = true;
        let mut jump: Option<(u32, u32)> = None;
        ui_kit::window(ctx, "在线成员", 260.0)
            .open(&mut open)
            .default_width(260.0)
            .show(ctx, |ui| {
                dlg_section(ui, "当前共享成员");
                let me = self.net.as_ref().map(|n| n.site);
                if self.peers_list.is_empty() && self.net.is_none() {
                    ui.label("当前没有共享");
                }
                for (site, name, color) in self.peers_list.clone() {
                    let is_me = Some(site) == me;
                    ui.horizontal(|ui| {
                        let c = match color % 7 {
                            0 => egui::Color32::from_rgb(230, 81, 0),
                            1 => egui::Color32::from_rgb(0, 121, 107),
                            2 => egui::Color32::from_rgb(106, 27, 154),
                            3 => egui::Color32::from_rgb(2, 119, 189),
                            4 => egui::Color32::from_rgb(198, 40, 40),
                            5 => egui::Color32::from_rgb(46, 125, 50),
                            _ => egui::Color32::from_rgb(255, 143, 0),
                        };
                        let (rect, _) =
                            ui.allocate_exact_size(egui::vec2(10.0, 10.0), egui::Sense::hover());
                        ui.painter().circle_filled(rect.center(), 4.5, c);
                        let label = if is_me {
                            format!("{name}（我）")
                        } else {
                            name.clone()
                        };
                        ui.add_sized(
                            [120.0, 18.0],
                            egui::Label::new(label).truncate(),
                        );
                        // 远端光标位置
                        let pos = self
                            .remote
                            .get(&site)
                            .map(|(_, _, r, c)| (*r, *c))
                            .or(if is_me { Some(self.sel) } else { None });
                        if let Some((r, c)) = pos {
                            if !is_me {
                                if ui
                                    .small_button(format!("{}", cell_name(r, c)))
                                    .on_hover_text("跳到他所在的位置")
                                    .clicked()
                                {
                                    jump = Some((r, c));
                                }
                            } else {
                                ui.label(egui::RichText::new(cell_name(r, c)).weak());
                            }
                        }
                    });
                }
                ui.separator();
                ui.label(
                    egui::RichText::new("位置来自对方的选区广播，没动过的人不显示")
                        .weak()
                        .size(10.0),
                );
            });
        if let Some((r, c)) = jump {
            self.sel = (r, c);
            self.sel_end = (r, c);
            self.ensure_visible();
            self.status = format!("已跳到 {}", cell_name(r, c));
        }
        self.members_open = open;
    }

    /// 算出当前表里不符合数据验证的格子（上限 5 万格，避免卡死）
    fn compute_invalid(&mut self) {
        if self.invalid_gen == self.doc_gen {
            return;
        }
        self.invalid_gen = self.doc_gen;
        self.invalid_cells.clear();
        let si = self.sheet_idx;
        let dv_list = self.wb.sheet(si).dv.clone();
        if dv_list.is_empty() {
            return;
        }
        let mut budget = 50_000usize;
        let mut calc = sheetcore::formula::Calc::new(&self.wb);
        for dv in dv_list.iter() {
            for (r1, c1, r2, c2) in dv.ranges.iter().copied() {
                for r in r1..=r2 {
                    for c in c1..=c2 {
                        if budget == 0 {
                            return;
                        }
                        budget -= 1;
                        let sheet = self.wb.sheet(si);
                        let Some(cell) = sheet.get(r, c) else { continue };
                        if matches!(cell.value, sheetcore::model::Value::Empty) {
                            continue;
                        }
                        let ok = sheetcore::dv::validate(dv, &cell.value, sheet, r, c, |f, rr, cc| {
                            let shifted = sheetcore::cf::shift_formula(f.trim_start_matches('='), rr, cc);
                            match sheetcore::formula::parse(&shifted) {
                                Ok(node) => matches!(
                                    calc.eval_node(&node, si),
                                    sheetcore::formula::FValue::Bool(true)
                                ),
                                Err(_) => true,
                            }
                        });
                        if !ok {
                            self.invalid_cells.insert((r, c));
                        }
                    }
                }
            }
        }
    }

    /// 条件格式管理器：看规则、调顺序、删除、定位
    fn cf_manager(&mut self, ctx: &egui::Context) {
        if !self.cf_mgr {
            return;
        }
        let mut open = true;
        let mut del: Option<(usize, usize)> = None;
        let mut up: Option<usize> = None;
        let mut down: Option<usize> = None;
        let mut goto: Option<(u32, u32, u32, u32)> = None;
        let blocks = self.wb.sheet(self.sheet_idx).cf.blocks.clone();
        ui_kit::window(ctx, "条件格式管理", 460.0)
            .open(&mut open)
            .default_width(460.0)
            .show(ctx, |ui| {
                if blocks.is_empty() {
                    ui.label("这张表还没有条件格式规则");
                }
                for (bi, blk) in blocks.iter().enumerate() {
                    let range_text = blk
                        .ranges
                        .iter()
                        .map(|(r1, c1, r2, c2)| {
                            format!(
                                "{}{}:{}{}",
                                sheetcore::model::col_label(*c1),
                                r1 + 1,
                                sheetcore::model::col_label(*c2),
                                r2 + 1
                            )
                        })
                        .collect::<Vec<_>>()
                        .join(" ");
                    ui.horizontal(|ui| {
                        ui.label(egui::RichText::new(format!("区域 {range_text}")).strong());
                        if ui.small_button("定位").clicked() {
                            if let Some(r) = blk.ranges.first() {
                                goto = Some(*r);
                            }
                        }
                        if ui.small_button("上移").clicked() {
                            up = Some(bi);
                        }
                        if ui.small_button("下移").clicked() {
                            down = Some(bi);
                        }
                    });
                    for (ri, rule) in blk.rules.iter().enumerate() {
                        ui.horizontal(|ui| {
                            ui.label(format!("  · {}", rule.kind.describe()));
                            if rule.stop {
                                ui.label(egui::RichText::new("(命中即停)").weak());
                            }
                            if ui.small_button("删除").clicked() {
                                del = Some((bi, ri));
                            }
                        });
                    }
                    ui.separator();
                }
            });
        if let Some((bi, ri)) = del {
            let sheet = self.wb.sheet_mut(self.sheet_idx);
            if let Some(blk) = sheet.cf.blocks.get_mut(bi) {
                if ri < blk.rules.len() {
                    blk.rules.remove(ri);
                }
                if blk.rules.is_empty() {
                    sheet.cf.blocks.remove(bi);
                }
            }
            sheet.cf_dirty = true;
            self.wb.dirty = true;
            self.doc_gen = self.doc_gen.wrapping_add(1);
            self.status = "已删除一条条件格式规则".into();
        }
        if let Some(bi) = up {
            if bi > 0 {
                self.wb.sheet_mut(self.sheet_idx).cf.blocks.swap(bi, bi - 1);
                self.wb.sheet_mut(self.sheet_idx).cf_dirty = true;
                self.doc_gen = self.doc_gen.wrapping_add(1);
                self.status = "规则已上移（优先级更高）".into();
            }
        }
        if let Some(bi) = down {
            let n = self.wb.sheet(self.sheet_idx).cf.blocks.len();
            if bi + 1 < n {
                self.wb.sheet_mut(self.sheet_idx).cf.blocks.swap(bi, bi + 1);
                self.wb.sheet_mut(self.sheet_idx).cf_dirty = true;
                self.doc_gen = self.doc_gen.wrapping_add(1);
                self.status = "规则已下移".into();
            }
        }
        if let Some((r1, c1, _, _)) = goto {
            self.sel = (r1, c1);
            self.sel_end = (r1, c1);
            self.ensure_visible();
        }
        self.cf_mgr = open;
    }

    fn data_dialog(&mut self, ctx: &egui::Context) {
        let Some(mut dlg) = self.data_dlg.take() else { return };
        let mut open = true;
        let mut run = false;
        let title = if dlg.tab == 0 { "多级排序" } else { "分列" };
        ui_kit::window(ctx, title, 420.0)
            .collapsible(false)
            .resizable(false)
            .open(&mut open)
            .show(ctx, |ui| {
                if dlg.tab == 0 {
                    ui.checkbox(&mut dlg.header, "首行是标题");
                    ui.separator();
                    ui.label("按顺序勾选排序列（靠前的优先）：");
                    for (c, asc, on) in dlg.keys.iter_mut() {
                        ui.horizontal(|ui| {
                            ui.checkbox(on, format!("{} 列", cell_name(0, *c).trim_end_matches('1')));
                            egui::ComboBox::from_id_salt(format!("ord{c}"))
                                .selected_text(if *asc { "升序" } else { "降序" })
                                .width(70.0)
                                .show_ui(ui, |ui| {
                                    ui.selectable_value(asc, true, "升序");
                                    ui.selectable_value(asc, false, "降序");
                                });
                        });
                    }
                } else {
                    ui.horizontal(|ui| {
                        ui.label("分隔符");
                        ui.add(egui::TextEdit::singleline(&mut dlg.delim).desired_width(60.0));
                    });
                    ui.label(egui::RichText::new("按分隔符拆到右边相邻列，右侧内容整体右移").weak());
                }
                ui.separator();
                if ui.button("执行").clicked() {
                    run = true;
                }
            });
        if run {
            if dlg.tab == 0 {
                self.run_sort(&dlg);
            } else {
                let ch = dlg.delim.chars().next().unwrap_or(',');
                self.run_split(ch);
            }
        } else if open {
            self.data_dlg = Some(dlg);
        }
    }

    // ===== 查找替换 =====
fn search_opts(&self) -> sheetcore::search::SearchOpts {
        sheetcore::search::SearchOpts {
            match_case: self.find.match_case,
            whole_cell: self.find.whole_cell,
            in_formula: self.find.in_formula,
        }
    }

    fn search_order(&self) -> sheetcore::search::SearchOrder {
        if self.find.order_column {
            sheetcore::search::SearchOrder::ColumnMajor
        } else {
            sheetcore::search::SearchOrder::RowMajor
        }
    }

    /// 从 Ribbon/快捷键/搜索框开始一次新的查找会话：
    /// 旧会话锁定的选区快照必须清掉，否则下一次“全部替换”仍会作用到旧区域。
    /// 连续 Next 不走这里，会话内定位继续使用已锁定快照。
    fn find_open_new_session(&mut self) {
        self.find.session_rect = None;
        self.find.session_rects.clear();
        self.find.open = true;
    }

    /// scope==2 的选区快照：主矩形 + Ctrl 多选矩形；没有快照时退回当前选择。
    fn find_rects(&self) -> Vec<(u32, u32, u32, u32)> {
        if self.find.scope != 2 {
            return Vec::new();
        }
        if !self.find.session_rects.is_empty() {
            return self.find.session_rects.clone();
        }
        let mut rects = self.extra_sel.clone();
        rects.push(self.find.session_rect.unwrap_or_else(|| self.sel_rect()));
        rects.sort_unstable();
        rects.dedup();
        rects
    }

    fn lock_find_rects(&mut self) {
        if self.find.scope != 2 || !self.find.session_rects.is_empty() {
            return;
        }
        self.find.session_rect = Some(self.sel_rect());
        let mut rects = self.extra_sel.clone();
        rects.push(self.sel_rect());
        rects.sort_unstable();
        rects.dedup();
        self.find.session_rects = rects;
    }

    /// 当前范围（选区/工作表/工作簿）的全部命中，按选定顺序排序
    fn find_hits(&self) -> Vec<sheetcore::search::Hit> {
        let opts = self.search_opts();
        let needle = sheetcore::search::normalize_needle(&self.find.find, &opts);
        if needle.is_empty() {
            return Vec::new();
        }
        let order = self.search_order();
        match self.find.scope {
            1 => sheetcore::search::hits(&self.wb, None, &needle, &opts, order),
            2 => {
                let mut out = Vec::new();
                for (r1, c1, r2, c2) in self.find_rects() {
                    out.extend(sheetcore::search::hits_in_rect(
                        &self.wb,
                        self.sheet_idx,
                        (r1, c1, r2, c2),
                        &needle,
                        &opts,
                        order,
                    ));
                }
                match order {
                    sheetcore::search::SearchOrder::RowMajor => out.sort_unstable(),
                    sheetcore::search::SearchOrder::ColumnMajor => {
                        out.sort_unstable_by_key(|h| (h.sheet, h.col, h.row))
                    }
                }
                out.dedup();
                out
            }
            _ => sheetcore::search::hits(&self.wb, Some(self.sheet_idx), &needle, &opts, order),
        }
    }

    /// 把范围内所有“存在的格”作为候选，按顺序排好，供分帧扫描。
    fn scan_candidates(&self) -> Vec<sheetcore::search::Hit> {
        let mut keys = Vec::new();
        let order = self.search_order();
        let (only, rects) = match self.find.scope {
            1 => (None, Vec::new()),
            2 => (Some(self.sheet_idx), self.find_rects()),
            _ => (Some(self.sheet_idx), Vec::new()),
        };
        for (si, sh) in self.wb.sheets.iter().enumerate() {
            if only.is_some_and(|x| x != si) {
                continue;
            }
            for (k, _) in sh.iter() {
                if !rects.is_empty()
                    && !rects.iter().any(|(r1, c1, r2, c2)| {
                        k.row >= (*r1).min(*r2)
                            && k.row <= (*r1).max(*r2)
                            && k.col >= (*c1).min(*c2)
                            && k.col <= (*c1).max(*c2)
                    })
                {
                    continue;
                }
                keys.push(sheetcore::search::Hit { sheet: si, row: k.row, col: k.col });
            }
        }
        match order {
            sheetcore::search::SearchOrder::RowMajor => keys.sort_unstable(),
            sheetcore::search::SearchOrder::ColumnMajor => {
                keys.sort_unstable_by_key(|h| (h.sheet, h.col, h.row))
            }
        }
        keys
    }

    fn start_scan(&mut self, purpose: u8) {
        if self.find.find.is_empty() {
            return;
        }
        let opts = self.search_opts();
        let needle = sheetcore::search::normalize_needle(&self.find.find, &opts);
        if needle.is_empty() {
            return;
        }
        if self.find.scope == 2 && self.find.session_rect.is_none() {
            self.lock_find_rects();
        }
        let keys = self.scan_candidates();
        if keys.is_empty() {
            self.status = "没找到".into();
            return;
        }
        let mut scan = FindScan {
            wb_epoch: self.wb_epoch,
            keys,
            at: 0,
            needle,
            opts,
            out: Vec::new(),
            purpose,
        };
        // 小范围直接同步跑完（测试与日常小表不需要跨帧）；大表分帧，可取消
        if scan.keys.len() <= 8000 {
            let total = scan.keys.len();
            self.run_scan_chunk(&mut scan, total);
            self.finish_scan(scan);
        } else {
            self.status = format!("正在扫描 {} 格，可点“取消”…", scan.keys.len());
            self.find_scan = Some(scan);
        }
    }

    fn run_scan_chunk(&self, scan: &mut FindScan, count: usize) {
        let end = (scan.at + count).min(scan.keys.len());
        for h in scan.keys[scan.at..end].iter() {
            if sheetcore::search::cell_matches(
                &self.wb, h.sheet, h.row, h.col, &scan.needle, &scan.opts,
            ) {
                scan.out.push(*h);
            }
        }
        scan.at = end;
    }

    fn poll_find_scan(&mut self) {
        let Some(mut scan) = self.find_scan.take() else { return };
        if scan.wb_epoch != self.wb_epoch {
            self.status = "文档已切换，已取消扫描".into();
            return;
        }
        self.run_scan_chunk(&mut scan, 4000);
        if scan.at >= scan.keys.len() {
            self.finish_scan(scan);
        } else {
            self.status = format!("正在扫描 {}/{} 格，可点“取消”…", scan.at, scan.keys.len());
            self.find_scan = Some(scan);
        }
    }

    fn cancel_find_scan(&mut self) {
        if self.find_scan.take().is_some() {
            self.status = "已取消扫描".into();
        }
    }

    fn finish_scan(&mut self, scan: FindScan) {
        // 候选键本身已按选定顺序排好，out 天然有序，无需再排
        if scan.purpose == 0 {
            self.find.hits = scan.out.len();
            self.find.find_all = scan.out;
            self.find.find_all_open = true;
            self.status = format!("查找全部：{} 处", self.find.hits);
        } else {
            self.apply_replace_hits(scan.out);
        }
    }

    /// 按匹配规则算出替换后的格子；没有实际变化时返回 None。
    /// 值模式默认不碰公式格：命中公式结果时必须由用户显式勾选“替换公式结果”。
    fn replacement_at(
        &self,
        sheet: usize,
        r: u32,
        c: u32,
        cell: &sheetcore::model::Cell,
    ) -> Option<sheetcore::model::Cell> {
        let opts = self.search_opts();
        let needle = sheetcore::search::normalize_needle(&self.find.find, &opts);
        if !sheetcore::search::cell_matches(&self.wb, sheet, r, c, &needle, &opts) {
            return None;
        }
        if !opts.in_formula && cell.formula.is_some() && !self.find.replace_formula_results {
            return None;
        }
        let text = sheetcore::search::cell_text_at(
            &self.wb,
            sheet,
            r,
            c,
            cell,
            opts.in_formula,
        )?;
        if opts.in_formula {
            let formula = cell.formula.as_deref()?;
            let next = if opts.whole_cell {
                self.find.replace.clone()
            } else {
                sheetcore::search::replace_in_text(
                    formula,
                    &self.find.find,
                    &self.find.replace,
                    self.find.match_case,
                )
            };
            if next == formula {
                return None;
            }
            let mut out = cell.clone();
            out.formula = Some(next.into_boxed_str());
            return Some(out);
        }
        let next = if opts.whole_cell {
            self.find.replace.clone()
        } else {
            sheetcore::search::replace_in_text(
                &text,
                &self.find.find,
                &self.find.replace,
                self.find.match_case,
            )
        };
        if next == text {
            return None;
        }
        Some(sheetcore::model::Cell {
            value: sheetcore::model::Value::parse_input(&next),
            formula: None,
        })
    }

    fn find_next(&mut self, backwards: bool) {
        if self.find.find.is_empty() {
            return;
        }
        if self.find.scope == 2 && self.find.session_rect.is_none() {
            self.lock_find_rects();
        }
        let hits = self.find_hits();
        if hits.is_empty() {
            self.status = "没找到".into();
            return;
        }
        let cur = sheetcore::search::Hit {
            sheet: self.sheet_idx,
            row: self.sel.0,
            col: self.sel.1,
        };
        let Some((hit, wrapped)) =
            sheetcore::search::next_hit(&hits, cur, !backwards, self.search_order())
        else {
            self.status = "没找到".into();
            return;
        };
        let idx = hits.iter().position(|h| *h == hit).unwrap_or(0) + 1;
        self.find.hits = hits.len();
        self.sheet_idx = hit.sheet.min(self.wb.sheets.len().saturating_sub(1));
        self.sel = (hit.row, hit.col);
        self.sel_end = (hit.row, hit.col);
        self.extra_sel.clear();
        self.ensure_visible();
        let name = cell_name(hit.row, hit.col);
        let where_ = self.wb.sheet(self.sheet_idx).name.clone();
        let edge = if wrapped {
            if backwards { "，已到最前，从末尾继续" } else { "，已回到开头" }
        } else {
            ""
        };
        self.status = format!("找到 {where_}!{name}（第 {idx}/{} 处{edge}）", hits.len());
    }

    fn replace_current(&mut self) {
        let si = self.sheet_idx;
        let (r, c) = self.sel;
        let Some(cell) = self.wb.sheet(si).get(r, c).cloned() else {
            self.find_next(false);
            return;
        };
        if !self.find.in_formula
            && cell.formula.is_some()
            && !self.find.replace_formula_results
        {
            let msg = format!(
                "{} 是公式结果：值模式不替换公式，请勾选“替换公式结果”或切到公式模式",
                cell_name(r, c)
            );
            self.find_next(false);
            // find_next 会写“找到…”，这里要保留真正的拒绝原因
            self.status = msg;
            return;
        }
        let Some(new_cell) = self.replacement_at(self.sheet_idx, r, c, &cell) else {
            self.find_next(false);
            return;
        };
        if !self.write_preflight(&[(r, c)], "替换") {
            return;
        }
        let txn = self.txn_begin(&[(r, c)]);
        self.wb.sheet_mut(si).set(r, c, new_cell);
        self.txn_end("替换", txn);
        self.recalc_and_broadcast(&[(si, r, c)]);
        self.wb.dirty = true;
        self.doc_gen = self.doc_gen.wrapping_add(1);
        self.status = format!("已替换 {}", cell_name(r, c));
        self.find_next(false);
    }

    fn replace_all(&mut self) {
        // 大表分帧扫描（可取消），扫描完成后再统一算差异并提交
        self.start_scan(1);
    }

    fn apply_replace_hits(&mut self, hits: Vec<sheetcore::search::Hit>) {
        if hits.is_empty() {
            self.status = "没找到可替换的内容".into();
            return;
        }
        // 先算差异，再统一提交：命中数与实改数可对账
        let mut diffs: Vec<(usize, u32, u32, sheetcore::model::Cell)> = Vec::new();
        for h in hits.iter() {
            let Some(cell) = self.wb.sheet(h.sheet).get(h.row, h.col) else { continue };
            if let Some(new_cell) = self.replacement_at(h.sheet, h.row, h.col, cell) {
                diffs.push((h.sheet, h.row, h.col, new_cell));
            }
        }
        let formula_skips = if self.find.in_formula || self.find.replace_formula_results {
            0
        } else {
            hits.iter()
                .filter(|h| {
                    self.wb
                        .sheet(h.sheet)
                        .get(h.row, h.col)
                        .is_some_and(|c| c.formula.is_some())
                })
                .count()
        };
        if diffs.is_empty() {
            self.status = if formula_skips > 0 {
                format!(
                    "找到 {} 处，其中 {} 处是公式结果（未替换；勾选“替换公式结果”或切到公式模式）",
                    hits.len(),
                    formula_skips
                )
            } else {
                format!("找到 {} 处，替换后没有变化", hits.len())
            };
            return;
        }
        // 按表分组做保护/锁检查；任何一格不可写就整批拒绝
        let mut groups: std::collections::BTreeMap<usize, Vec<(u32, u32)>> =
            std::collections::BTreeMap::new();
        for (si, r, c, _) in diffs.iter() {
            groups.entry(*si).or_default().push((*r, *c));
        }
        for (si, keys) in groups.iter() {
            let mut keys = keys.clone();
            keys.sort_unstable();
            keys.dedup();
            if !self.write_preflight_on(*si, &keys, "全部替换") {
                return;
            }
        }
        // 多表单事务：逐表捕获，合并成一次撤销
        let mut before: std::collections::BTreeMap<usize, Vec<sheetcore::undo::CellDelta>> =
            std::collections::BTreeMap::new();
        for (si, keys) in groups.iter() {
            let mut keys = keys.clone();
            keys.sort_unstable();
            keys.dedup();
            before.insert(*si, sheetcore::undo::capture(self.wb.sheet(*si), *si, &keys));
        }
        for (si, r, c, cell) in diffs.iter() {
            self.wb.sheet_mut(*si).set(*r, *c, cell.clone());
        }
        let mut deltas: Vec<sheetcore::undo::CellDelta> = Vec::new();
        for (si, caps) in before.into_iter() {
            deltas.extend(sheetcore::undo::finish(caps, self.wb.sheet(si)));
        }
        if !deltas.is_empty() {
            self.record_revision("全部替换", &deltas);
            self.undo.push(sheetcore::undo::Action {
                label: "全部替换".into(),
                merges: None,
                deltas,
                focus: (diffs[0].0, diffs[0].1, diffs[0].2),
                snap_before: None,
                snap_after: None,
                by_site: 0,
                shapes: None,
                refresh_sizes: None,
            });
        }
        let keys: Vec<(usize, u32, u32)> =
            diffs.iter().map(|(si, r, c, _)| (*si, *r, *c)).collect();
        self.recalc_and_broadcast(&keys);
        self.wb.dirty = true;
        self.doc_gen = self.doc_gen.wrapping_add(1);
        self.status = if formula_skips > 0 {
            format!(
                "找到 {} 处，替换 {} 处，跳过 {} 处公式结果（可勾选“替换公式结果”）",
                hits.len(),
                diffs.len(),
                formula_skips
            )
        } else {
            format!(
                "找到 {} 处，替换 {} 处（{}）",
                hits.len(),
                diffs.len(),
                if diffs.len() < hits.len() { "其余替换后无变化" } else { "全部成功" }
            )
        };
    }

    // ===== 工作表 =====
    fn can_change_sheets(&mut self) -> bool {
        if self.net.is_some() {
            self.status = "协作期间暂不支持增删、改名或移动工作表，请先断开协作".into();
            return false;
        }
        if self.tasks.open_rx.is_some() {
            self.status = "正在加载或重算，完成后再调整工作表".into();
            return false;
        }
        self.commit_edit(None);
        self.editing.is_none()
    }

    fn finish_sheet_change(&mut self) {
        self.wb.dirty = true;
        self.doc_gen = self.doc_gen.wrapping_add(1);
        self.tasks.last_edit = Some(std::time::Instant::now());
        // These records contain sheet indices or old formula qualifiers.
        self.undo = sheetcore::undo::UndoStack::new();
        self.clip = None;
        sheetcore::formula::recalc_all(&mut self.wb);
        self.deps = sheetcore::formula::deps::Deps::build(&self.wb);
        self.cf_stats_gen = u64::MAX;
        self.invalid_gen = u64::MAX;
    }

    fn set_sheet_name(&mut self, idx: usize, name: &str) -> bool {
        if !self.can_change_sheets() {
            return false;
        }
        if self.wb.sheets.get(idx).is_some_and(|sheet| sheet.name == name) {
            return true;
        }
        if !sheetcore::sheet_ops::rename_sheet(&mut self.wb, idx, name) {
            self.status = "工作表名称无效或已存在".into();
            return false;
        }
        self.finish_sheet_change();
        self.status = format!("已重命名为 {name}");
        true
    }

    fn add_sheet(&mut self) {
        if !self.can_change_sheets() {
            return;
        }
        let n = self.wb.sheets.len() + 1;
        let mut name = format!("Sheet{n}");
        let mut k = n;
        while self.wb.sheets.iter().any(|s| s.name.eq_ignore_ascii_case(&name)) {
            k += 1;
            name = format!("Sheet{k}");
        }
        let index = self.wb.sheets.len();
        if !sheetcore::sheet_ops::insert_sheet(&mut self.wb, index, sheetcore::model::Sheet::new(&name)) {
            self.status = "无法创建工作表：名称无效或已存在".into();
            return;
        }
        self.sheet_idx = index;
        self.finish_sheet_change();
        self.status = format!("已新建 {name}");
    }

    fn delete_sheet(&mut self, idx: usize) {
        if idx >= self.wb.sheets.len() || !self.can_change_sheets() {
            return;
        }
        if self.wb.sheets.len() <= 1 {
            self.status = "至少保留一张工作表".into();
            return;
        }
        let name = self.wb.sheets[idx].name.clone();
        if !sheetcore::sheet_ops::delete_sheet(&mut self.wb, idx) {
            return;
        }
        if self.sheet_idx > idx {
            self.sheet_idx -= 1;
        }
        self.sheet_idx = self.sheet_idx.min(self.wb.sheets.len() - 1);
        self.finish_sheet_change();
        self.status = format!("已删除 {name}");
    }

    fn move_sheet(&mut self, idx: usize, delta: i32) {
        let to = idx as i32 + delta;
        if to < 0 || to as usize >= self.wb.sheets.len() {
            return;
        }
        if self.swap_sheet_positions(idx, to as usize) {
            self.sheet_idx = to as usize;
        }
    }

    fn swap_sheet_positions(&mut self, from: usize, to: usize) -> bool {
        if from == to || from >= self.wb.sheets.len() || to >= self.wb.sheets.len()
            || !self.can_change_sheets()
        {
            return false;
        }
        if !sheetcore::sheet_ops::move_sheet(&mut self.wb, from, to) {
            return false;
        }
        if self.sheet_idx == from {
            self.sheet_idx = to;
        } else if self.sheet_idx == to {
            self.sheet_idx = from;
        }
        self.finish_sheet_change();
        true
    }

    /// 撤销 / 重做
    fn do_undo(&mut self, redo: bool) {
        if self.editing.is_some() {
            return;
        }
        if self.net.is_some() && if redo { self.undo.redo_is_structure() } else { self.undo.undo_is_structure() } {
            self.status = "协作期间不能撤销或重做整表结构，请先断开协作".into();
            return;
        }
        // 协作时：只回退仍然是我改成的样子的格子
        let mut mine: std::collections::HashSet<(usize, u32, u32)> = std::collections::HashSet::new();
        let site = self.net.as_ref().map(|n| n.site);
        if let Some(_site) = site {
            if let Some(peer) = self.peer.as_ref() {
                for (k, op) in peer.cells.iter() {
                    if op.site == site.unwrap() {
                        mine.insert(*k);
                    }
                }
            }
        }
        let guard = |sheet: usize, row: u32, col: u32, _cur: &sheetcore::model::Cell| {
            mine.is_empty() || mine.contains(&(sheet, row, col))
        };
        let applied = if redo {
            self.undo.redo_workbook(&mut self.wb, guard)
        } else {
            self.undo.undo_workbook(&mut self.wb, guard)
        };
        let Some(applied) = applied else {
            self.status = if redo { "没有可重做的操作".into() } else { "没有可撤销的操作".into() };
            return;
        };
        if applied.merge_conflict {
            self.status = format!(
                "{}：合并结构与当前表冲突，已整体放弃（结构、内容和广播均未改动）",
                if redo { "重做" } else { "撤销" }
            );
            return;
        }
        // 刷新类动作撤销/重做时把外源源尺寸一起还原
        if let Some(sizes) = &applied.refresh_sizes {
            for (name, rows, cols) in sizes {
                if let Some(src) = self.wb.sources.iter_mut().find(|s| &s.name == name) {
                    src.rows = *rows;
                    src.cols = *cols;
                }
            }
        };
        self.wb.dirty = true;
        self.doc_gen = self.doc_gen.wrapping_add(1);
        // 重算受影响格子
        let mut keys: Vec<(usize, u32, u32)> = applied.touched.clone();
        keys.sort();
        keys.dedup();
        if applied.structural {
            sheetcore::formula::recalc_all(&mut self.wb);
            self.deps = sheetcore::formula::deps::Deps::build(&self.wb);
        } else {
            for k in keys.iter() {
                self.deps.update_cell(&self.wb, *k);
            }
            sheetcore::formula::recalc_dirty(&mut self.wb, &self.deps, &keys);
        }
        self.cf_stats_gen = u64::MAX;
        self.invalid_gen = u64::MAX;
        self.tasks.last_edit = Some(std::time::Instant::now());
        // 协作广播
        if let (Some(peer), Some(net)) = (self.peer.as_mut(), self.net.as_ref()) {
            for (sheet, row, col) in applied.touched.iter() {
                let cell = self.wb.sheet(*sheet).get(*row, *col).cloned().unwrap_or_default();
                let op = peer.local_set(*sheet, *row, *col, &cell);
                net.broadcast_op(op);
            }
            // 撤销/重做也会改样式（清除全部、格式操作）；只发内容会让对端留下默认格式，
            // 必须把每格撤销后的真实样式再同步一遍。
            let mut by_sheet: std::collections::BTreeMap<
                usize,
                Vec<(u32, u32, sheetcore::style::CellStyle)>,
            > = std::collections::BTreeMap::new();
            for (sheet, row, col) in applied.touched.iter() {
                if *sheet < self.wb.sheets.len() {
                    let id = self.wb.sheet(*sheet).style_of(*row, *col);
                    let st = self.wb.styles.get(id).clone();
                    by_sheet.entry(*sheet).or_default().push((*row, *col, st));
                }
            }
            for (sheet, items) in by_sheet {
                net.broadcast_style(sheet, items);
            }
            // 合并结构也要同步；只发内容/样式会让对端留下旧的合并轮廓。
            for (sheet, rect, on) in applied.merge_changes.iter() {
                net.broadcast_merge(*sheet, *rect, *on);
            }
        }
        // 回到出事的格
        let (sheet, row, col) = applied.focus;
        self.sheet_idx = sheet.min(self.wb.sheets.len().saturating_sub(1));
        self.sel = (row, col);
        self.sel_end = (row, col);
        self.ensure_visible();
        self.status = if redo {
            format!("重做：{}", applied.label)
        } else {
            format!("撤销：{}", applied.label)
        };
        if applied.skipped > 0 {
            self.status.push_str(&format!("（{} 格已被别人改动，跳过）", applied.skipped));
        }
    }

    /// 复制工作表：插到原表后面，名字自动去重
    fn duplicate_sheet(&mut self, i: usize) {
        if i >= self.wb.sheets.len() || !self.can_change_sheets() {
            return;
        }
        let mut copy = self.wb.sheets[i].clone();
        let base = copy.name.clone();
        let copy_name = |n| {
            let suffix = format!(" ({n})");
            let prefix: String = base.chars().take(31usize.saturating_sub(suffix.chars().count())).collect();
            format!("{prefix}{suffix}")
        };
        let mut n = 2;
        let mut name = copy_name(n);
        while self.wb.sheets.iter().any(|s| s.name.eq_ignore_ascii_case(&name)) {
            n += 1;
            name = copy_name(n);
        }
        copy.name = name;
        copy.source_part = None;
        copy.edited = true;
        // Keep spill ownership so the next recalc clears and rebuilds its tail.
        if sheetcore::sheet_ops::insert_sheet(&mut self.wb, i + 1, copy) {
            self.sheet_idx = i + 1;
            self.finish_sheet_change();
        }
    }

    /// 已用区域的右下角
    fn used_end(&self) -> (u32, u32) {
        let sheet = self.wb.sheet(self.sheet_idx);
        let (mut mr, mut mc) = (0u32, 0u32);
        for (k, cell) in sheet.iter() {
            if cell.is_blank() {
                continue;
            }
            mr = mr.max(k.row);
            mc = mc.max(k.col);
        }
        (mr, mc)
    }

    /// Ctrl+方向：沿方向跳过空白，停在连续数据块的边缘（Excel 语义）
    fn jump_edge(&self, dr: i64, dc: i64) -> (u32, u32) {
        let sheet = self.wb.sheet(self.sheet_idx);
        let (mut r, mut c) = (self.sel.0 as i64, self.sel.1 as i64);
        let occupied = |r: i64, c: i64| -> bool {
            r >= 0
                && c >= 0
                && sheet
                    .get(r as u32, c as u32)
                    .map(|x| !x.is_blank())
                    .unwrap_or(false)
        };
        // 先跳过空白
        for _ in 0..4096 {
            let (nr, nc) = (r + dr, c + dc);
            if nr < 0 || nc < 0 {
                break;
            }
            if occupied(nr, nc) {
                break;
            }
            r = nr;
            c = nc;
        }
        // 再走到数据块末尾
        if occupied(r + dr, c + dc) {
            for _ in 0..4096 {
                let (nr, nc) = (r + dr, c + dc);
                if !occupied(nr, nc) {
                    break;
                }
                r = nr;
                c = nc;
            }
        }
        (r.max(0) as u32, c.max(0) as u32)
    }

    /// 打开单元格格式对话框，先读选区左上角的样式
    fn open_format_dialog(&mut self) {
        let (r, c) = self.sel;
        let id = self.wb.sheet(self.sheet_idx).style_of(r, c);
        let st = self.wb.styles.get(id).clone();
        self.fmt_tab = 0;
        self.fmt_state = FmtState {
            font: st.font.clone(),
            bold: st.bold,
            italic: st.italic,
            underline: st.underline,
            strikethrough: st.strikethrough,
            rotation: st.rotation,
            size: st.size,
            color: st.color,
            fill: st.fill,
            halign: st.halign,
            valign: st.valign,
            wrap: st.wrap,
            indent: st.indent,
            format: st.format,
            border: [
                st.border[0].style != 0,
                st.border[1].style != 0,
                st.border[2].style != 0,
                st.border[3].style != 0,
            ],
        };
        self.fmt_merge_pending = None;
        self.fmt_dlg = true;
    }

    /// 名称框：支持 A1、A1:B2、以及定义名称
    fn goto_name(&mut self) {
        let text = self.name_buf.trim().to_string();
        if text.is_empty() {
            return;
        }
        self.commit_edit(None);
        if self.editing.is_some() {
            return;
        }
        let up = text.to_ascii_uppercase();
        let parts: Vec<&str> = up.split(':').collect();
        if parts.len() == 2 {
            if let (Some(a), Some(b)) = (
                sheetcore::sparse::parse_ref(parts[0]),
                sheetcore::sparse::parse_ref(parts[1]),
            ) {
                self.commit_edit(None);
                self.sel = a;
                self.sel_end = b;
                self.ensure_visible();
                return;
            }
        } else if let Some(a) = sheetcore::sparse::parse_ref(parts[0]) {
            self.commit_edit(None);
            self.sel = a;
            self.sel_end = a;
            self.ensure_visible();
            return;
        }
        let hit = self
            .wb
            .names
            .iter()
            .find(|(n, _, _)| n.eq_ignore_ascii_case(&text))
            .map(|(_, sh, body)| (*sh, body.clone()));
        if let Some((_sh, body)) = hit {
            let body = body.trim_start_matches('=').to_string();
            let tail = body.rsplit('!').next().unwrap_or(&body).replace('$', "");
            if let Some(pos) = sheetcore::sparse::parse_ref(&tail) {
                if let Some((sheet, _)) = body.rsplit_once('!') {
                    let nm = sheet.trim_matches(|c| c == '\'');
                    if let Some(idx) = self
                        .wb
                        .sheets
                        .iter()
                        .position(|s| s.name.eq_ignore_ascii_case(nm))
                    {
                        self.sheet_idx = idx;
                    }
                }
                self.commit_edit(None);
                self.sel = pos;
                self.sel_end = pos;
                self.ensure_visible();
                return;
            }
        }
        self.status = format!("找不到名称：{text}");
    }

    /// 提交当前编辑。缓冲的唯一所有者是 `self.editing`；数据验证不通过时不写、
    /// 不移动选区、保留编辑内容和协作租约（Excel 的「重试」）。返回是否真的写入。
    fn commit_edit(&mut self, advance: Option<(i32, i32)>) -> bool {
        let mut wrote = false;
        if let Some(ed) = self.editing.take() {
            let (r, c) = self.sel;
            // 数据验证：不合规就不写入，编辑框留着让用户改（Excel 的「重试」）
            let mut rejected: Option<String> = None;
            {
                let sheet = self.wb.sheet(self.sheet_idx);
                if let Some(dv) = sheetcore::dv::find(&sheet.dv, r, c) {
                    let probe = if ed.buf.starts_with('=') {
                        Value::Text(ed.buf.as_str().into())
                    } else {
                        Value::parse_input(&ed.buf)
                    };
                    let mut calc = sheetcore::formula::Calc::new(&self.wb);
                    let ok = sheetcore::dv::validate(dv, &probe, sheet, r, c, |f, rr, cc| {
                        let shifted = sheetcore::cf::shift_formula(f.trim_start_matches('='), rr, cc);
                        match sheetcore::formula::parse(&shifted) {
                            Ok(node) => matches!(
                                calc.eval_node(&node, self.sheet_idx),
                                sheetcore::formula::FValue::Bool(true)
                            ),
                            Err(_) => true,
                        }
                    });
                    if !ok {
                        rejected = Some(sheetcore::dv::error_text(dv));
                    }
                }
            }
            if let Some(msg) = rejected {
                self.status = msg;
                let mut again = ed.clone();
                again.buf = ed.buf.clone();
                self.editing = Some(again);
                return false;
            }
            self.release_lock();
            let cell = if ed.buf.starts_with('=') {
                // 手输的 [预算.xlsx]Sheet!A1：先把工作簿登记成链接（能读到就带缓存），
                // 再折回 Excel 认的 [N] 形式
                let mut text = ed.buf.trim().to_string();
                if sheetcore::xlinks::is_external_formula(&text) {
                    let added = sheetcore::xlinks::absorb_formula(&mut self.wb, &text);
                    if added > 0 {
                        self.status = format!("已登记 {added} 个外部工作簿");
                    }
                    text = sheetcore::xlinks::raw_formula(&self.wb, &text);
                }
                Cell { value: Value::Text(text.as_str().into()), formula: Some(text.as_str().into()) }
            } else {
                Cell { value: Value::parse_input(&ed.buf), formula: None }
            };
            let cell_clone = cell.clone();
            let txn = self.txn_begin(&[(r, c)]);
            self.wb.sheet_mut(self.sheet_idx).set(r, c, cell);
            wrote = true;
            self.txn_end("编辑单元格", txn);
            self.wb.dirty = true;
            let key = (self.sheet_idx, r, c);
            self.doc_gen = self.doc_gen.wrapping_add(1);
            self.tasks.last_edit = Some(std::time::Instant::now());
            self.deps.update_cell(&self.wb, key);
            sheetcore::formula::recalc_dirty(&mut self.wb, &self.deps, &[key]);
            // Ctrl+Shift+Enter：按选区把这条公式登记成数组公式（保存时写 t="array" ref）
            if self.cse_pending {
                self.cse_pending = false;
                let (r1, c1, r2, c2) = self.sel_rect();
                if (r2 - r1 + 1) as u64 * (c2 - c1 + 1) as u64 > 1 && ed.buf.starts_with('=') {
                    let sheet = self.wb.sheet_mut(self.sheet_idx);
                    sheet.arrays.retain(|(a, _)| *a != sheetcore::model::CellRef::new(r1, c1));
                    sheet.arrays.push((
                        sheetcore::model::CellRef::new(r1, c1),
                        (r1, c1, r2, c2),
                    ));
                    let rect = (r1, c1, r2, c2);
                    self.status = format!(
                        "已按数组公式写入 {}{}:{}{}",
                        sheetcore::model::col_label(c1),
                        r1 + 1,
                        sheetcore::model::col_label(c2),
                        r2 + 1
                    );
                    let _ = rect;
                }
            }
            if let (Some(peer), Some(net)) = (self.peer.as_mut(), self.net.as_ref()) {
                let op = peer.local_set(self.sheet_idx, r, c, &cell_clone);
                net.broadcast_op(op);
            }
        }
        // 表格对象：在表格正下方继续输入时自动扩一行（Excel 的行为）；
        // 在右侧一列输入时扩一列。汇总行不自动越过。
        {
            let (rr, cc) = self.sel;
            let mut grew: Option<(String, (u32, u32, u32, u32))> = None;
            {
                let sheet = self.wb.sheet(self.sheet_idx);
                for t in sheet.tables.iter() {
                    if t.totals_row || !t.header_row {
                        continue;
                    }
                    let (r1, c1, r2, c2) = t.range;
                    if cc >= c1 && cc <= c2 && rr == r2 + 1 {
                        grew = Some((t.name.clone(), (r1, c1, r2 + 1, c2)));
                        break;
                    }
                    if rr >= r1 && rr <= r2 && cc == c2 + 1 {
                        grew = Some((t.name.clone(), (r1, c1, r2, c2 + 1)));
                        break;
                    }
                }
            }
            if let Some((name, range)) = grew {
                let sh = self.wb.sheet_mut(self.sheet_idx);
                if let Some(t) = sh.tables.iter_mut().find(|t| t.name == name) {
                    t.range = range;
                    if range.3 as usize >= t.columns.len() {
                        let n = t.columns.len() + 1;
                        t.columns.push(format!("列{n}"));
                    }
                }
                sh.tables_dirty = true;
                // 表格带筛选时，筛选区域跟着扩大
                if let Some(f) = sh.filter.as_mut() {
                    if f.range.0 == range.0 && f.range.1 == range.1 {
                        f.range = range;
                    }
                }
                self.wb.dirty = true;
            }
        }
        // 文本被改写后旧的富文本段就失效了（避免保存时把旧分段盖回去）
        {
            let (rr, cc) = self.sel;
            let sheet = self.wb.sheet_mut(self.sheet_idx);
            if let Some(runs) = sheet.rich.get(&(rr, cc)).cloned() {
                let t = sheetcore::richtext::runs_text(&runs);
                if t != sheet.value(rr, cc).display() {
                    sheet.rich.remove(&(rr, cc));
                    sheet.rich_dirty = true;
                }
            }
        }
        if wrote {
            if let Some((dr, dc)) = advance {
                let nr = (self.sel.0 as i64 + dr as i64).max(0) as u32;
                let nc = (self.sel.1 as i64 + dc as i64).max(0) as u32;
                self.sel = (nr, nc);
                self.ensure_visible();
            }
        }
        wrote
    }

    /// 取消编辑：丢弃缓冲、交还租约，不碰模型、不记撤销、不改 dirty。
    fn cancel_edit(&mut self) {
        self.editing = None;
        self.release_lock();
    }

    /// 让选区留在可视范围内（列宽行高不统一，只能按实际位置算）
    fn ensure_visible(&mut self) {
        let (r, c) = self.sel;
        let (cols, mut rows) = self.view_axes();
        let view_w = (self.last_view.x - HEAD_W).max(64.0);
        let view_h = (self.last_view.y - HEAD_H).max(44.0);
        let top = rows.pos(r);
        let bot = top + rows.size(r);
        if top < self.scroll.y {
            self.scroll.y = top;
        } else if bot > self.scroll.y + view_h {
            self.scroll.y = bot - view_h;
        }
        let left = cols.pos(c);
        let right = left + cols.size(c);
        if left < self.scroll.x {
            self.scroll.x = left;
        } else if right > self.scroll.x + view_w {
            self.scroll.x = right - view_w;
        }
    }

    /// 当前视口实际可见的数据行数（跳过隐藏行；含底部部分可见行）。
    fn visible_page_rows(&self) -> u32 {
        let (_, rows) = self.view_axes();
        let view_h = (self.last_view.y - HEAD_H).max(44.0);
        let top = self.scroll.y;
        let mut r = rows.index_at(top);
        let mut n = 0u32;
        let mut guard = 0u32;
        while r <= 1_048_575 && rows.pos(r) < top + view_h && guard < 8192 {
            if rows.size(r) > 0.0 {
                n += 1;
            }
            r += 1;
            guard += 1;
        }
        n.max(1)
    }

    /// 下一个可见行/列，跳过隐藏（尺寸为 0）的行/列；到边界则停住。
    fn next_visible_row(&self, from: u32, down: bool) -> u32 {
        let (_, rows) = self.view_axes();
        let mut r = from;
        let mut guard = 0u32;
        loop {
            if down {
                if r >= 1_048_575 { return r; }
                r += 1;
            } else {
                if r == 0 { return r; }
                r -= 1;
            }
            guard += 1;
            if rows.size(r) > 0.0 || guard >= 1_048_576 {
                return r;
            }
        }
    }

    /// PageUp/PageDown：按当前视口可见行数翻页，保留一行重叠；不落到隐藏行。
    fn page_move(&mut self, down: bool) {
        let step = self.visible_page_rows().saturating_sub(1).max(1);
        let (mut r, c) = self.sel;
        for _ in 0..step {
            r = self.next_visible_row(r, down);
        }
        self.sel = (r, c);
        self.sel_end = (r, c);
        self.ensure_visible();
    }

    /// Ctrl+PageUp/PageDown：在当前文档内切换可见工作表，跳过隐藏表。
    fn switch_sheet_relative(&mut self, delta: i32) {
        let n = self.wb.sheets.len();
        if n < 2 {
            return;
        }
        self.commit_edit(None);
        let mut i = self.sheet_idx as i32;
        for _ in 0..n {
            i = (i + delta).rem_euclid(n as i32);
            if !self.wb.sheets[i as usize].hidden {
                self.sheet_idx = i as usize;
                self.sel = (0, 0);
                self.sel_end = (0, 0);
                self.extra_sel.clear();
                self.scroll = Vec2::ZERO;
                self.status = format!("当前工作表：{}", self.wb.sheet(self.sheet_idx).name);
                return;
            }
        }
    }

    /// Ctrl+A：第一次选当前数据区域，第二次在已选整块时选全表（Excel 的两段行为）。
    fn select_region_or_all(&mut self) {
        self.commit_edit(None);
        let (r1, c1, r2, c2) =
            sheetcore::sort_filter::current_region(self.wb.sheet(self.sheet_idx), self.sel.0, self.sel.1);
        let already = self.sel == (r1, c1) && self.sel_end == (r2, c2);
        if already {
            self.sel = (0, 0);
            self.sel_end = (1_048_575, 16_383);
            self.scroll = Vec2::ZERO;
            self.status = "已选择整个工作表".into();
        } else {
            self.sel = (r1, c1);
            self.sel_end = (r2, c2);
            self.ensure_visible();
            self.status = format!("已选择当前区域 {}:{}", cell_name(r1, c1), cell_name(r2, c2));
        }
    }

    fn select_whole_row(&mut self) {
        let r = self.sel.0;
        self.sel = (r, 0);
        self.sel_end = (r, 16_383);
        self.ensure_visible();
        self.status = format!("已选择第 {} 行", r + 1);
    }

    fn select_whole_col(&mut self) {
        let c = self.sel.1;
        self.sel = (0, c);
        self.sel_end = (1_048_575, c);
        self.ensure_visible();
        self.status = format!("已选择 {} 列", col_label(c));
    }

    /// 键盘：方向键移动、回车/制表符提交并移动、直接键入进入编辑
    fn handle_keys(&mut self, ctx: &egui::Context) {
        // 保存/打开/新建/打印/撤销/重做由 crate::command 的命令表统一处理
        // （见 `handle_command_keys`），这里只剩网格自身的按键。
        // Ctrl+F1：和 Excel 一样收起/展开功能区
        if ctx.input(|i| i.modifiers.command && i.key_pressed(Key::F1)) {
            self.ribbon_collapsed = !self.ribbon_collapsed;
        }
        // F9：Excel 同款“重算全部”，大文件走后台
        if self.editing.is_none() && ctx.input(|i| i.key_pressed(Key::F9)) {
            self.recalc_all_async();
            return;
        }
        // 格式刷：Esc 结束（连续模式也结束）
        if self.editing.is_none()
            && (self.format_painter.is_some()
                || self.merge_pending.is_some()
                || self.fmt_merge_pending.is_some())
            && ctx.input(|i| i.key_pressed(Key::Escape))
        {
            let had_painter = self.format_painter.is_some();
            let had_merge = self.merge_pending.is_some() || self.fmt_merge_pending.is_some();
            self.format_painter = None;
            self.painter_double = false;
            self.drop_merge_confirmation();
            self.status = match (had_painter, had_merge) {
                (true, true) => "格式刷与未确认的合并已取消".into(),
                (true, false) => "格式刷已取消".into(),
                _ => "已取消未确认的合并".into(),
            };
            return;
        }

        if self.editing.is_none()
            && !self.extra_sel.is_empty()
            && ctx.input(|i| i.key_pressed(Key::Escape))
        {
            self.extra_sel.clear();
            self.status = "已取消多块选区".into();
            return;
        }
        if self.editing.is_none() && ctx.wants_keyboard_input() {
            // 对话框/查找框有焦点时不要把按键当成网格快捷键
            return;
        }
        if self.editing.is_some() {
            // 编辑框内的按键交给 TextEdit 自己处理
            if ctx.input(|i| i.key_pressed(Key::Escape)) {
                self.cancel_edit();
            }
            return;
        }

        // 常用选择/格式快捷键（编辑区由 TextEdit 优先处理，见上）
        let ctrl_shortcut = ctx.input(|i| i.modifiers.command && !i.modifiers.alt);
        if ctrl_shortcut && ctx.input(|i| i.key_pressed(Key::B)) {
            self.ribbon_action("Bold", ctx);
            return;
        }
        if ctrl_shortcut && ctx.input(|i| i.key_pressed(Key::I)) {
            self.ribbon_action("Italic", ctx);
            return;
        }
        if ctrl_shortcut && ctx.input(|i| i.key_pressed(Key::U)) {
            self.ribbon_action("Underline", ctx);
            return;
        }
        if ctrl_shortcut && ctx.input(|i| i.key_pressed(Key::A)) {
            self.select_region_or_all();
            return;
        }
        let (ctrl_space, shift_space) = ctx.input(|i| {
            (
                i.modifiers.command && i.key_pressed(Key::Space),
                i.modifiers.shift && !i.modifiers.command && i.key_pressed(Key::Space),
            )
        });
        if ctrl_space {
            self.select_whole_col();
            return;
        }
        if shift_space {
            self.select_whole_row();
            return;
        }
        if ctx.input(|i| i.key_pressed(Key::F5))
            || (ctrl_shortcut && ctx.input(|i| i.key_pressed(Key::G)))
        {
            self.name_focus_request = true;
            self.status = "在名称框输入 A1、A1:B2 或定义名称，回车定位".into();
            return;
        }

        // 选中文本框时 Delete/Backspace 删掉它（Excel 同款）
        if self.editing.is_none() && !ctx.wants_keyboard_input() {
            if let Some(i) = self.tb_sel {
                if ctx.input(|i| i.key_pressed(Key::Delete) || i.key_pressed(Key::Backspace)) {
                    self.tb_delete(i);
                    return;
                }
            }
        }

        // Alt：显示页签字母提示（KeyTips），再按字母切换页签
        let alt_now = ctx.input(|i| i.modifiers.alt);
        if alt_now && !self.alt_down {
            self.keytips = true;
        }
        self.alt_down = alt_now;
        if self.keytips {
            let chosen = ctx.input(|i| {
                let m = i.modifiers;
                if m.alt || m.command || m.shift {
                    return None;
                }
                for (k, idx) in [
                    (Key::F, 0usize),
                    (Key::H, 1),
                    (Key::N, 2),
                    (Key::P, 3),
                    (Key::M, 4),
                    (Key::A, 5),
                    (Key::R, 6),
                    (Key::W, 7),
                ] {
                    if i.key_pressed(k) {
                        return Some(idx);
                    }
                }
                None
            });
            if let Some(idx) = chosen {
                self.keytips = false;
                if idx == 0 {
                    self.backstage = true;
                    self.backstage_page = 0;
                } else {
                    self.ribbon_tab = idx;
                    self.ribbon_collapsed = false;
                }
            } else if ctx.input(|i| i.key_pressed(Key::Escape) || i.pointer.any_click()) {
                self.keytips = false;
            }
        }
        let show_f_k = ctx.input(|i| i.modifiers.command && i.key_pressed(Key::Backtick));
        if show_f_k {
            self.show_formulas = !self.show_formulas;
            self.status = if self.show_formulas {
                "显示公式（再按 Ctrl+` 切回结果）".into()
            } else {
                "显示结果".into()
            };
        }
        let (copy_k, cut_k, paste_k, paste_v_k, find_k, repl_k) = ctx.input(|i| {
            (
                i.modifiers.command && i.key_pressed(Key::C),
                i.modifiers.command && i.key_pressed(Key::X),
                i.modifiers.command && !i.modifiers.shift && !i.modifiers.alt && i.key_pressed(Key::V),
                i.modifiers.command && i.modifiers.shift && i.key_pressed(Key::V),
                i.modifiers.command && i.key_pressed(Key::F),
                i.modifiers.command && i.key_pressed(Key::H),
            )
        });
        if copy_k {
            self.clip_copy(false, ctx);
            return;
        }
        if cut_k {
            self.clip_copy(true, ctx);
            return;
        }
        if paste_k || paste_v_k {
            // 从 Excel 复制过来的块：HTML 里有格式与合并，优先走这条
            if paste_k && !paste_v_k {
                if let Some(block) = office_clipboard::read_table() {
                    if self.paste_office_block(&block) {
                        return;
                    }
                }
            }
            let text = ctx.input(|i| {
                i.events.iter().find_map(|e| match e {
                    egui::Event::Paste(t) => Some(t.clone()),
                    _ => None,
                })
            });
            // 系统剪贴板没有新粘贴事件时，用内部剪贴板
            self.clip_paste(paste_v_k, text);
            return;
        }
        if find_k || repl_k {
            self.find.tab = if repl_k { 1 } else { 0 };
            self.find_open_new_session();
            return;
        }
        if ctx.input(|i| i.modifiers.command && i.modifiers.alt && i.key_pressed(Key::V)) {
            self.paste_special = true;
            return;
        }
        // Ctrl+方向：跳到数据边缘；Ctrl+Home/End：回到 A1 / 已用区域末尾
        let (ctrl, home, end, pgup, pgdn) = ctx.input(|i| {
            (
                i.modifiers.command,
                i.key_pressed(Key::Home),
                i.key_pressed(Key::End),
                i.key_pressed(Key::PageUp),
                i.key_pressed(Key::PageDown),
            )
        });
        if ctrl && (home || end) {
            self.commit_edit(None);
            let (r, c) = if home {
                (0u32, 0u32)
            } else {
                self.used_end()
            };
            self.sel = (r, c);
            self.sel_end = (r, c);
            self.ensure_visible();
            return;
        }
        if !ctrl && home {
            // Excel 的 Home：回到本行 A 列
            self.commit_edit(None);
            let r = self.sel.0;
            self.sel = (r, 0);
            self.sel_end = (r, 0);
            self.ensure_visible();
            return;
        }
        if ctrl && (pgup || pgdn) {
            self.switch_sheet_relative(if pgdn { 1 } else { -1 });
            return;
        }
        if pgup || pgdn {
            self.commit_edit(None);
            self.page_move(pgdn);
            return;
        }
        if ctrl && (ctx.input(|i| i.key_pressed(Key::ArrowUp))
            || ctx.input(|i| i.key_pressed(Key::ArrowDown))
            || ctx.input(|i| i.key_pressed(Key::ArrowLeft))
            || ctx.input(|i| i.key_pressed(Key::ArrowRight)))
        {
            let (dr, dc) = ctx.input(|i| {
                (
                    if i.key_pressed(Key::ArrowDown) { 1i64 } else if i.key_pressed(Key::ArrowUp) { -1 } else { 0 },
                    if i.key_pressed(Key::ArrowRight) { 1i64 } else if i.key_pressed(Key::ArrowLeft) { -1 } else { 0 },
                )
            });
            self.commit_edit(None);
            let (r, c) = self.jump_edge(dr, dc);
            let shift = ctx.input(|i| i.modifiers.shift);
            self.sel = (r, c);
            if !shift {
                self.sel_end = (r, c);
            }
            self.ensure_visible();
            return;
        }
        if ctx.input(|i| i.modifiers.command && i.key_pressed(Key::Num1)) {
            self.open_format_dialog();
            return;
        }
        if ctx.input(|i| i.modifiers.command && !i.modifiers.shift && i.key_pressed(Key::D)) {
            self.fill_cmd(true);
            return;
        }
        if ctx.input(|i| i.modifiers.command && !i.modifiers.shift && i.key_pressed(Key::R)) {
            self.fill_cmd(false);
            return;
        }
        let (mut dr, mut dc) = (0i64, 0i64);
        let (mut commit, mut start_edit, mut clear, mut cse) = (false, false, false, false);
        ctx.input(|i| {
            if i.key_pressed(Key::ArrowDown) { dr += 1 }
            if i.key_pressed(Key::ArrowUp) { dr -= 1 }
            if i.key_pressed(Key::ArrowRight) { dc += 1 }
            if i.key_pressed(Key::ArrowLeft) { dc -= 1 }
            if i.key_pressed(Key::Enter) {
                commit = true;
                dr = if i.modifiers.shift { -1 } else { 1 };
                cse = i.modifiers.command && i.modifiers.shift;
            }
            if i.key_pressed(Key::Tab) {
                commit = true;
                dc = if i.modifiers.shift { -1 } else { 1 };
            }
            if i.key_pressed(Key::F2) { start_edit = true }
            if i.key_pressed(Key::Delete) || i.key_pressed(Key::Backspace) { clear = true }
        });

        if commit && cse {
            self.cse_pending = true;
        }
        if clear {
            self.clear_values();
        }
        if commit || dr != 0 || dc != 0 {
            let nr = (self.sel.0 as i64 + dr).max(0) as u32;
            let nc = (self.sel.1 as i64 + dc).max(0) as u32;
            let extend = !commit
                && (dr != 0 || dc != 0)
                && ctx.input(|i| i.modifiers.shift);
            if extend {
                // Shift+方向：锚点留在 sel_end，只移动活动格
                self.sel = (nr, nc);
            } else {
                self.sel = (nr, nc);
                self.sel_end = (nr, nc);
                self.extra_sel.clear();
            }
            self.ensure_visible();
        }
        if start_edit {
            self.begin_edit(None);
        }
        // 直接打字就开始编辑
        if self.editing.is_none() {
            let typed = ctx.input(|i| {
                i.events.iter().find_map(|e| match e {
                    egui::Event::Text(t) if !t.is_empty() && !t.chars().next().unwrap().is_control() => {
                        Some(t.clone())
                    }
                    _ => None,
                })
            });
            if let Some(t) = typed {
                self.begin_edit(Some(t));
            }
        }
    }

    /// 画表格：行列标题、单元格、选区、远端光标

    /// 选区矩形列表：主选区 + Ctrl+点击追加的块
    fn sel_rects(&self) -> Vec<(u32, u32, u32, u32)> {
        let mut v: Vec<(u32, u32, u32, u32)> = self.extra_sel.clone();
        v.push(self.sel_rect());
        v
    }

    /// 规范化后的选区 (r1, c1, r2, c2)
    fn sel_rect(&self) -> (u32, u32, u32, u32) {
        let (r1, r2) = (self.sel.0.min(self.sel_end.0), self.sel.0.max(self.sel_end.0));
        let (c1, c2) = (self.sel.1.min(self.sel_end.1), self.sel.1.max(self.sel_end.1));
        (r1, c1, r2, c2)
    }

    /// 选区左上角的样式（工具栏按钮显示当前状态）
    /// 小数位 +1/−1：把当前区域的小数格式改成 n±1 位
    fn decimals(&mut self, delta: i32) {
        let cur = self.current_style();
        let mut f = if cur.format.is_empty() {
            "#,##0".to_string()
        } else {
            cur.format.clone()
        };
        let chars: Vec<char> = f.chars().collect();
        if let Some(dot) = chars.iter().position(|c| *c == '.') {
            let mut end = dot + 1;
            while end < chars.len() && (chars[end] == '0' || chars[end] == '#') {
                end += 1;
            }
            if delta > 0 {
                f.insert(end, '0');
            } else if end > dot + 1 {
                f.remove(end - 1);
            } else {
                return;
            }
        } else if delta > 0 {
            f.push_str(".0");
        } else {
            return;
        }
        self.apply_style(move |s| s.format = f.clone());
    }

    /// 自动求和：当前格上方连续数字 → =SUM(首:末)
    fn auto_sum(&mut self) {
        self.auto_func("SUM");
    }

    /// 自动求和 / 平均值 / 计数：都按「上方连续非空区域」生成公式
    fn auto_func(&mut self, func: &str) {
        let (r, c) = self.sel;
        let sheet = self.wb.sheet(self.sheet_idx);
        let mut top = r;
        while top > 0 {
            let nonblank = sheet
                .get(top - 1, c)
                .map(|x| !x.is_blank())
                .unwrap_or(false);
            if nonblank {
                top -= 1;
            } else {
                break;
            }
        }
        let formula = if top < r {
            format!("={func}({}:{})", cell_name(top, c), cell_name(r - 1, c))
        } else {
            format!("={func}(")
        };
        self.begin_edit(None);
        if let Some(ed) = self.editing.as_mut() {
            ed.buf = formula;
        }
        self.commit_edit(Some((1, 0)));
    }

    /// 只清内容，保留格式/批注（Excel「清除内容」）
fn clear_values(&mut self) {
        self.clear_rects(ClearPart::Contents);
    }

    /// 清除格式（保留内容）
    fn clear_formats(&mut self) {
        self.clear_rects(ClearPart::Formats);
    }

    /// 清除全部（内容 + 格式），一次事务、一步撤销
    fn clear_all(&mut self) {
        self.clear_rects(ClearPart::All);
    }

    /// 统一的 ClearContents 命令：所有非连续选区去重后一次事务完成
    fn clear_rects(&mut self, part: ClearPart) {
        let rects = self.sel_rects();
        let mut keys: Vec<(u32, u32)> = Vec::new();
        for (r1, c1, r2, c2) in rects.iter().copied() {
            keys.extend(sheetcore::undo::rect_keys(r1, c1, r2, c2));
        }
        keys.sort_unstable();
        keys.dedup();
        let what = match part {
            ClearPart::Contents => "清除内容",
            ClearPart::Formats => "清除格式",
            ClearPart::All => "清除全部",
        };
        if !self.write_preflight(&keys, what) {
            return;
        }
        let txn = self.txn_begin(&keys);
        for &(r, c) in keys.iter() {
            if part != ClearPart::Formats {
                self.wb.sheet_mut(self.sheet_idx).set(
                    r,
                    c,
                    sheetcore::model::Cell {
                        value: sheetcore::model::Value::Empty,
                        formula: None,
                    },
                );
            }
            if part != ClearPart::Contents {
                self.wb.sheet_mut(self.sheet_idx).set_style(r, c, 0);
            }
        }
        self.txn_end(what, txn);
        self.wb.dirty = true;
        self.doc_gen = self.doc_gen.wrapping_add(1);
        // 内容与格式是两条独立通道：清除全部必须同时发，不能只发内容
        if part != ClearPart::Contents {
            if let Some(net) = self.net.as_ref() {
                let items: Vec<(u32, u32, sheetcore::style::CellStyle)> = keys
                    .iter()
                    .map(|(r, c)| (*r, *c, sheetcore::style::CellStyle::default()))
                    .collect();
                net.broadcast_style(self.sheet_idx, items);
            }
        }
        if part != ClearPart::Formats {
            let keys3: Vec<(usize, u32, u32)> =
                keys.iter().map(|(r, c)| (self.sheet_idx, *r, *c)).collect();
            self.recalc_and_broadcast(&keys3);
        }
        self.status = format!("已{what}");
    }

    /// 单元格样式库的 5 个预设（真写入 CellStyle）
    fn apply_style_preset(&mut self, kind: &str) {
        match kind {
            "normal" => self.apply_style(|s| {
                let f = s.font.clone();
                *s = sheetcore::style::CellStyle {
                    font: f,
                    size: 11.0,
                    color: [0, 0, 0],
                    ..Default::default()
                };
            }),
            "title" => self.apply_style(|s| {
                s.bold = true;
                s.italic = false;
                s.size = 14.0;
                s.color = [31, 78, 121];
                s.fill = None;
            }),
            "heading" => self.apply_style(|s| {
                s.bold = true;
                s.size = 11.0;
                s.color = [31, 56, 100];
                s.fill = Some([217, 226, 243]);
            }),
            "good" => self.apply_style(|s| {
                s.bold = false;
                s.color = [0, 97, 0];
                s.fill = Some([198, 239, 206]);
            }),
            "bad" => self.apply_style(|s| {
                s.bold = false;
                s.color = [156, 0, 6];
                s.fill = Some([255, 199, 206]);
            }),
            _ => {}
        }
    }

    /// 填充：把选区第一行复制到其余行（值、公式、样式）
    fn fill_down(&mut self) {
        let (r1, c1, r2, c2) = self.sel_rect();
        if r2 <= r1 {
            self.status = "先选两行以上再填充".into();
            return;
        }
        let keys = sheetcore::undo::rect_keys(r1, c1, r2, c2);
        let txn = self.txn_begin(&keys);
        for cc in c1..=c2 {
            let src = self.wb.sheet(self.sheet_idx).get(r1, cc).cloned();
            let style_id = self.wb.sheet(self.sheet_idx).style_of(r1, cc);
            for rr in r1 + 1..=r2 {
                match &src {
                    Some(cell) => {
                        self.wb.sheet_mut(self.sheet_idx).set(rr, cc, cell.clone());
                    }
                    None => {
                        self.wb.sheet_mut(self.sheet_idx).remove(rr, cc);
                    }
                }
                self.wb.sheet_mut(self.sheet_idx).set_style(rr, cc, style_id);
            }
        }
        self.txn_end("填充", txn);
        self.status = "已向下填充".into();
    }

    /// 表格汇总行：加一行 SUBTOTAL(109,…)，再点一次去掉
    fn toggle_totals_row(&mut self, table_name: &str) {
        if self.edit_blocked() {
            return;
        }
        let Some(t) = self
            .wb
            .sheet(self.sheet_idx)
            .tables
            .iter()
            .find(|t| t.name == table_name)
            .cloned()
        else {
            return;
        };
        let (r1, c1, r2, c2) = t.range;
        let keys = sheetcore::undo::rect_keys(r1, c1, r2 + 1, c2);
        let txn = self.txn_begin(&keys);
        if t.totals_row {
            // 去掉：清掉汇总行，范围收回
            {
                let sh = self.wb.sheet_mut(self.sheet_idx);
                for c in c1..=c2 {
                    sh.remove(r2, c);
                }
                if let Some(tb) = sh.tables.iter_mut().find(|x| x.name == table_name) {
                    tb.totals_row = false;
                    tb.range.2 = r2.saturating_sub(1);
                }
                sh.tables_dirty = true;
                if let Some(f) = sh.filter.as_mut() {
                    if f.range.0 == r1 && f.range.1 == c1 {
                        f.range.2 = r2.saturating_sub(1);
                    }
                }
            }
            self.status = "已去掉汇总行".into();
        } else {
            let row = r2 + 1;
            {
                let sh = self.wb.sheet_mut(self.sheet_idx);
                sh.set(
                    row,
                    c1,
                    sheetcore::model::Cell {
                        value: sheetcore::model::Value::Text("总计".into()),
                        formula: None,
                    },
                );
                for c in (c1 + 1)..=c2 {
                    let a = sheetcore::model::cell_name(r1 + 1, c);
                    let b = sheetcore::model::cell_name(r2, c);
                    sh.set(
                        row,
                        c,
                        sheetcore::model::Cell {
                            value: sheetcore::model::Value::Empty,
                            formula: Some(format!("SUBTOTAL(109,{a}:{b})").into()),
                        },
                    );
                }
                if let Some(tb) = sh.tables.iter_mut().find(|x| x.name == table_name) {
                    tb.totals_row = true;
                    tb.range.2 = row;
                }
                sh.tables_dirty = true;
                if let Some(f) = sh.filter.as_mut() {
                    if f.range.0 == r1 && f.range.1 == c1 {
                        f.range.2 = r2;
                    }
                }
            }
            sheetcore::formula::recalc_all(&mut self.wb);
            self.status = "已加汇总行（SUBTOTAL 109，忽略筛选掉的行）".into();
        }
        self.txn_end("表格汇总行", txn);
        self.deps = sheetcore::formula::deps::Deps::build(&self.wb);
        self.doc_gen = self.doc_gen.wrapping_add(1);
        self.wb.dirty = true;
    }

    /// 拖动选区移动（dr/dc 可正可负）：值、样式、批注、富文本、超链接一起搬
    fn move_selection_by(&mut self, dr: i64, dc: i64) {
        if self.edit_blocked() {
            return;
        }
        let (r1, c1, r2, c2) = self.sel_rect();
        let nr1 = (r1 as i64 + dr).max(0) as u32;
        let nc1 = (c1 as i64 + dc).max(0) as u32;
        let nr2 = nr1 + (r2 - r1);
        let nc2 = nc1 + (c2 - c1);
        if (nr1, nc1) == (r1, c1) {
            return;
        }
        let mut keys = sheetcore::undo::rect_keys(r1, c1, r2, c2);
        keys.extend(sheetcore::undo::rect_keys(nr1, nc1, nr2, nc2));
        keys.sort_unstable();
        keys.dedup();
        if !self.write_preflight(&keys, "移动单元格") {
            return;
        }
        let txn = self.txn_begin(&keys);
        let mut cells: Vec<(u32, u32, sheetcore::model::Cell, Option<u16>)> = Vec::new();
        for r in r1..=r2 {
            for c in c1..=c2 {
                if let Some(cell) = self.wb.sheet(self.sheet_idx).get(r, c).cloned() {
                    let st = self.wb.sheet(self.sheet_idx).styles.get(&sheetcore::model::CellRef::new(r, c)).copied();
                    cells.push((r - r1, c - c1, cell, st));
                }
            }
        }
        let notes: Vec<_> = self
            .wb
            .sheet(self.sheet_idx)
            .notes
            .iter()
            .filter(|(k, _)| k.row >= r1 && k.row <= r2 && k.col >= c1 && k.col <= c2)
            .map(|(k, v)| ((k.row - r1, k.col - c1), v.clone()))
            .collect();
        let rich: Vec<_> = self
            .wb
            .sheet(self.sheet_idx)
            .rich
            .iter()
            .filter(|((r, c), _)| *r >= r1 && *r <= r2 && *c >= c1 && *c <= c2)
            .map(|((r, c), v)| ((r - r1, c - c1), v.clone()))
            .collect();
        let links: Vec<_> = self
            .wb
            .sheet(self.sheet_idx)
            .hyperlinks
            .iter()
            .filter(|((r, c), _)| *r >= r1 && *r <= r2 && *c >= c1 && *c <= c2)
            .map(|((r, c), v)| ((r - r1, c - c1), v.clone()))
            .collect();
        {
            let sh = self.wb.sheet_mut(self.sheet_idx);
            for r in r1..=r2 {
                for c in c1..=c2 {
                    sh.remove(r, c);
                    sh.styles.remove(&sheetcore::model::CellRef::new(r, c));
                }
            }
            // 先清掉源区域上的附属数据，再把快照写到目标（源/目标重叠也不会丢）
            for r in r1..=r2 {
                for c in c1..=c2 {
                    sh.notes.remove(&sheetcore::model::CellRef::new(r, c));
                    sh.rich.remove(&(r, c));
                    sh.hyperlinks.remove(&(r, c));
                }
            }
            for ((r, c), n) in notes {
                sh.notes.insert(sheetcore::model::CellRef::new(nr1 + r, nc1 + c), n);
            }
            for ((r, c), v) in rich {
                sh.rich.insert((nr1 + r, nc1 + c), v);
                sh.rich_dirty = true;
            }
            for ((r, c), v) in links {
                sh.hyperlinks.insert((nr1 + r, nc1 + c), v);
                sh.hyperlinks_dirty = true;
            }
            for (dr0, dc0, cell, st) in cells {
                let (r, c) = (nr1 + dr0, nc1 + dc0);
                let mut cell = cell;
                if let Some(f) = &cell.formula {
                    if dr >= 0 && dc >= 0 {
                        cell.formula = Some(
                            sheetcore::cf::shift_formula(f, dr as u32, dc as u32).into(),
                        );
                    }
                }
                sh.set(r, c, cell);
                if let Some(id) = st {
                    sh.set_style(r, c, id);
                }
            }
        }
        self.txn_end("移动单元格", txn);
        self.sel = (nr1, nc1);
        self.sel_end = (nr2, nc2);
        sheetcore::formula::recalc_all(&mut self.wb);
        self.deps = sheetcore::formula::deps::Deps::build(&self.wb);
        self.doc_gen = self.doc_gen.wrapping_add(1);
        self.wb.dirty = true;
        self.status = format!("已移动到 {}", sheetcore::model::cell_name(nr1, nc1));
    }

    /// Shift+拖动：把选区「插」到目标位置（整行下移 / 整列右移），Excel 的 shift 拖放
    fn shift_insert_by(&mut self, dr: i64, dc: i64) {
        if self.edit_blocked() {
            return;
        }
        let (r1, c1, r2, c2) = self.sel_rect();
        let nr1 = (r1 as i64 + dr).max(0) as u32;
        let nc1 = (c1 as i64 + dc).max(0) as u32;
        if (nr1, nc1) == (r1, c1) {
            return;
        }
        // 目标落在源块里就没意义
        if nr1 >= r1 && nr1 <= r2 && nc1 >= c1 && nc1 <= c2 {
            return;
        }
        let vertical = dr.abs() >= dc.abs();
        let mut gate = sheetcore::undo::rect_keys(r1, c1, r2, c2);
        for (k, _) in self.wb.sheet(self.sheet_idx).iter() {
            if (vertical && k.row >= nr1) || (!vertical && k.col >= nc1) {
                gate.push((k.row, k.col));
            }
        }
        for k in self.wb.sheet(self.sheet_idx).styles.keys() {
            if (vertical && k.row >= nr1) || (!vertical && k.col >= nc1) {
                gate.push((k.row, k.col));
            }
        }
        // 空目标格没有 Cell/Style 可枚举，但别人可能正锁着它；租约表本身是稀疏的
        for ((si, r, c), _) in self.locks.iter() {
            if si == self.sheet_idx && ((vertical && r >= nr1) || (!vertical && c >= nc1)) {
                gate.push((r, c));
            }
        }
        gate.sort_unstable();
        gate.dedup();
        if !self.write_preflight(&gate, "插入并移动") {
            return;
        }
        // 1) 快照
        let mut cells: Vec<(u32, u32, sheetcore::model::Cell, Option<u16>)> = Vec::new();
        for r in r1..=r2 {
            for c in c1..=c2 {
                if let Some(cell) = self.wb.sheet(self.sheet_idx).get(r, c).cloned() {
                    let st = self
                        .wb
                        .sheet(self.sheet_idx)
                        .styles
                        .get(&sheetcore::model::CellRef::new(r, c))
                        .copied();
                    cells.push((r - r1, c - c1, cell, st));
                }
            }
        }
        // 2) 清源
        {
            let sh = self.wb.sheet_mut(self.sheet_idx);
            for r in r1..=r2 {
                for c in c1..=c2 {
                    sh.remove(r, c);
                    sh.styles.remove(&sheetcore::model::CellRef::new(r, c));
                }
            }
        }
        // 3) 在目标处插入空行/空列（走结构操作，合并/格式/验证会跟着挪）
        let idx = self.sheet_idx;
        let op = if vertical {
            sheetcore::structural::Structural::InsertRows {
                at: nr1,
                n: r2 - r1 + 1,
            }
        } else {
            sheetcore::structural::Structural::InsertCols {
                at: nc1,
                n: c2 - c1 + 1,
            }
        };
        let snap = if self.wb.sheet(idx).len() <= 200_000 {
            Some(sheetcore::undo::snapshot_structure(&self.wb, idx, &op))
        } else {
            None
        };
        sheetcore::structural::apply_structural_wb(&mut self.wb, idx, &op);
        // 4) 写回目标
        {
            let sh = self.wb.sheet_mut(idx);
            for (dr0, dc0, mut cell, st) in cells {
                if let Some(f) = cell.formula.clone() {
                    if dr >= 0 && dc >= 0 {
                        cell.formula =
                            Some(sheetcore::cf::shift_formula(&f, dr as u32, dc as u32).into());
                    }
                }
                let (r, c) = if vertical {
                    (nr1 + dr0, c1 + dc0)
                } else {
                    (r1 + dr0, nc1 + dc0)
                };
                sh.set(r, c, cell);
                if let Some(id) = st {
                    sh.set_style(r, c, id);
                }
            }
        }
        if let Some(before) = snap {
            let after = before.capture_after(&self.wb);
            let label = if vertical { "插入行并移动" } else { "插入列并移动" };
            self.undo
                .push_structure(label.to_string(), before, after, (idx, self.sel.0, self.sel.1));
        }
        sheetcore::formula::recalc_all(&mut self.wb);
        self.deps = sheetcore::formula::deps::Deps::build(&self.wb);
        self.doc_gen = self.doc_gen.wrapping_add(1);
        self.wb.dirty = true;
        self.sel = (nr1, nc1);
        self.sel_end = (nr1 + (r2 - r1), nc1 + (c2 - c1));
        self.status = format!(
            "已插入到 {}（{}）",
            sheetcore::model::cell_name(nr1, nc1),
            if vertical { "整行下移" } else { "整列右移" }
        );
    }

    /// Ctrl+拖动选区边框：复制到新位置（源保留）
    fn copy_selection_by(&mut self, dr: i64, dc: i64) {
        if self.edit_blocked() {
            return;
        }
        let (r1, c1, r2, c2) = self.sel_rect();
        let nr1 = (r1 as i64 + dr).max(0) as u32;
        let nc1 = (c1 as i64 + dc).max(0) as u32;
        let nr2 = nr1 + (r2 - r1);
        let nc2 = nc1 + (c2 - c1);
        if (nr1, nc1) == (r1, c1) {
            return;
        }
        let mut keys = sheetcore::undo::rect_keys(nr1, nc1, nr2, nc2);
        keys.extend(sheetcore::undo::rect_keys(r1, c1, r2, c2));
        if !self.write_preflight(
            &sheetcore::undo::rect_keys(nr1, nc1, nr2, nc2),
            "复制单元格",
        ) {
            return;
        }
        let txn = self.txn_begin(&keys);
        // 先把源区域的快照取出来（不改源）
        let mut cells: Vec<(u32, u32, sheetcore::model::Cell, Option<u16>)> = Vec::new();
        for r in r1..=r2 {
            for c in c1..=c2 {
                if let Some(cell) = self.wb.sheet(self.sheet_idx).get(r, c).cloned() {
                    let st = self
                        .wb
                        .sheet(self.sheet_idx)
                        .styles
                        .get(&sheetcore::model::CellRef::new(r, c))
                        .copied();
                    cells.push((r - r1, c - c1, cell, st));
                }
            }
        }
        let notes: Vec<_> = self
            .wb
            .sheet(self.sheet_idx)
            .notes
            .iter()
            .filter(|(k, _)| k.row >= r1 && k.row <= r2 && k.col >= c1 && k.col <= c2)
            .map(|(k, v)| ((k.row - r1, k.col - c1), v.clone()))
            .collect();
        let rich: Vec<_> = self
            .wb
            .sheet(self.sheet_idx)
            .rich
            .iter()
            .filter(|((r, c), _)| *r >= r1 && *r <= r2 && *c >= c1 && *c <= c2)
            .map(|((r, c), v)| ((r - r1, c - c1), v.clone()))
            .collect();
        let links: Vec<_> = self
            .wb
            .sheet(self.sheet_idx)
            .hyperlinks
            .iter()
            .filter(|((r, c), _)| *r >= r1 && *r <= r2 && *c >= c1 && *c <= c2)
            .map(|((r, c), v)| ((r - r1, c - c1), v.clone()))
            .collect();
        {
            let sh = self.wb.sheet_mut(self.sheet_idx);
            // 目标区域先清空（Excel 复制粘贴也是覆盖）
            for r in nr1..=nr2 {
                for c in nc1..=nc2 {
                    sh.remove(r, c);
                    sh.styles.remove(&sheetcore::model::CellRef::new(r, c));
                    sh.notes.remove(&sheetcore::model::CellRef::new(r, c));
                    sh.rich.remove(&(r, c));
                    sh.hyperlinks.remove(&(r, c));
                }
            }
            for ((r, c), n) in notes {
                sh.notes.insert(sheetcore::model::CellRef::new(nr1 + r, nc1 + c), n);
            }
            for ((r, c), v) in rich {
                sh.rich.insert((nr1 + r, nc1 + c), v);
                sh.rich_dirty = true;
            }
            for ((r, c), v) in links {
                sh.hyperlinks.insert((nr1 + r, nc1 + c), v);
                sh.hyperlinks_dirty = true;
            }
            for (dr0, dc0, cell, st) in cells {
                let (r, c) = (nr1 + dr0, nc1 + dc0);
                let mut cell = cell;
                if let Some(f) = cell.formula.clone() {
                    // 相对引用按实际位移平移；往左上时 shift_formula 只接受无符号，保持原样更安全
                    if dr >= 0 && dc >= 0 {
                        cell.formula =
                            Some(sheetcore::cf::shift_formula(&f, dr as u32, dc as u32).into());
                    }
                }
                sh.set(r, c, cell);
                if let Some(id) = st {
                    sh.set_style(r, c, id);
                }
            }
        }
        self.txn_end("复制单元格", txn);
        self.sel = (nr1, nc1);
        self.sel_end = (nr2, nc2);
        sheetcore::formula::recalc_all(&mut self.wb);
        self.deps = sheetcore::formula::deps::Deps::build(&self.wb);
        self.doc_gen = self.doc_gen.wrapping_add(1);
        self.wb.dirty = true;
        self.status = format!("已复制到 {}", sheetcore::model::cell_name(nr1, nc1));
    }

    /// 插入/删除单元格（down_or_up: true=插入；horizontal: true=右移/左移）
    fn shift_cells(&mut self, insert: bool, horizontal: bool) {
        if self.edit_blocked() {
            return;
        }
        self.commit_edit(None);
        let rect = self.sel_rect();
        let used = self.wb.sheet(self.sheet_idx).used_bounds();
        let mut keys = match used {
            Some((_, _, r2, c2)) => sheetcore::undo::rect_keys(
                rect.0,
                rect.1,
                r2.max(rect.2),
                c2.max(rect.3),
            ),
            None => sheetcore::undo::rect_keys(rect.0, rect.1, rect.2, rect.3),
        };
        // 公式引用可能被改到选区外，撤销要能一起还原
        for (cref, cell) in self.wb.sheet(self.sheet_idx).iter() {
            if cell.formula.is_some() {
                keys.push((cref.row, cref.col));
            }
        }
        let txn = self.txn_begin(&keys);
        {
            let sh = self.wb.sheet_mut(self.sheet_idx);
            let shift = if horizontal {
                sheetcore::cells::Shift::Horizontal
            } else {
                sheetcore::cells::Shift::Vertical
            };
            if insert {
                sheetcore::cells::insert(sh, rect, shift, 1);
            } else {
                sheetcore::cells::delete(sh, rect, shift, 1);
            }
        }
        sheetcore::structural::apply_cell_shift_wb(&mut self.wb, self.sheet_idx, rect, horizontal, insert);
        self.txn_end(if insert { "插入单元格" } else { "删除单元格" }, txn);
        sheetcore::formula::recalc_all(&mut self.wb);
        self.deps = sheetcore::formula::deps::Deps::build(&self.wb);
        self.doc_gen = self.doc_gen.wrapping_add(1);
        self.wb.dirty = true;
        self.status = if insert {
            if horizontal { "已插入单元格（右侧右移）" } else { "已插入单元格（下方下移）" }.into()
        } else if horizontal {
            "已删除单元格（左侧左移）".into()
        } else {
            "已删除单元格（上方上移）".into()
        };
    }

    /// 只给选区外沿加边框（style: 1=细线 2=粗线）
    fn border_outer(&mut self, style: u8) {
        let (r1, c1, r2, c2) = self.sel_rect();
        self.apply_style_xy(|s, r, c| {
            let b = sheetcore::style::Border { style, color: [128, 128, 128] };
            if r == r1 { s.border[0] = b; }
            if c == c2 { s.border[1] = b; }
            if r == r2 { s.border[2] = b; }
            if c == c1 { s.border[3] = b; }
        });
    }

    /// 算一遍简转繁的差异（不动数据），供预览对话框显示
    fn zh_preview_scan(&mut self) {
        let v = self.zh_preview_variant;
        let mut rows = Vec::new();
        let scan_sheet = |si: usize,
                          r1: u32,
                          c1: u32,
                          r2: u32,
                          c2: u32,
                          out: &mut Vec<(usize, u32, u32, String, String)>| {
            let sh = self.wb.sheet(si);
            for r in r1..=r2 {
                for c in c1..=c2 {
                    let Some(cell) = sh.get(r, c) else { continue };
                    let sheetcore::model::Value::Text(t) = &cell.value else {
                        continue;
                    };
                    let new = sheetcore::zhconv::to_traditional_with(t, v);
                    if new.as_str() != t.as_ref() {
                        out.push((si, r, c, t.to_string(), new));
                    }
                }
            }
        };
        if self.zh_preview_all_sheets {
            let only = self.zh_preview_sheet;
            for si in 0..self.wb.sheets.len() {
                if let Some(only) = only {
                    if si != only {
                        continue;
                    }
                }
                let bounds = self.wb.sheet(si).used_bounds();
                if let Some((r1, c1, r2, c2)) = bounds {
                    if (r2 - r1) as u64 * (c2 - c1) as u64 <= 400_000 {
                        scan_sheet(si, r1, c1, r2, c2, &mut rows);
                    }
                }
                if rows.len() > 5000 {
                    break;
                }
            }
        } else {
            let (r1, c1, r2, c2) = self.sel_rect();
            if (r2 - r1) as u64 * (c2 - c1) as u64 <= 200_000 {
                scan_sheet(self.sheet_idx, r1, c1, r2, c2, &mut rows);
            }
        }
        self.zh_preview = rows;
    }

    /// 按预览列表逐条写入（跨表也用这个，一个撤销事务）
    fn zh_apply_preview(&mut self) {
        if self.edit_blocked() || self.zh_preview.is_empty() {
            return;
        }
        let v = self.zh_preview_variant;
        let items = self.zh_preview.clone();
        let cur = self.sheet_idx;
        let txn = self.txn_begin(&[(0, 0)]);
        let mut n = 0usize;
        let mut touched: Vec<usize> = Vec::new();
        for (si, r, c, old, _new) in items {
            let sh = self.wb.sheet_mut(si);
            let Some(cell) = sh.get(r, c).cloned() else {
                continue;
            };
            let sheetcore::model::Value::Text(t) = &cell.value else {
                continue;
            };
            if t.as_ref() != old.as_str() {
                continue;
            }
            let new = sheetcore::zhconv::to_traditional_with(t, v);
            let mut cell = cell;
            cell.value = sheetcore::model::Value::Text(new.into());
            sh.set(r, c, cell);
            n += 1;
            if !touched.contains(&si) {
                touched.push(si);
            }
        }
        self.sheet_idx = cur;
        self.txn_end("简转繁", txn);
        self.wb.dirty = true;
        self.doc_gen = self.doc_gen.wrapping_add(1);
        self.status = format!("简转繁：{n} 个单元格（{} 张表）", touched.len());
        self.zh_preview_dlg = false;
    }

    fn zh_preview_window(&mut self, ctx: &egui::Context) {
        if !self.zh_preview_dlg {
            return;
        }
        let mut open = true;
        let mut apply = false;
        let mut variant_changed = false;
        ui_kit::window(ctx, "简转繁预览", 660.0)
            .open(&mut open)
            .show(ctx, |ui| {
                ui.horizontal(|ui| {
                    if ui
                        .checkbox(&mut self.zh_preview_all_sheets, "所有工作表")
                        .changed()
                    {
                        self.zh_preview_sheet = None;
                        variant_changed = true;
                    }
                    if self.zh_preview_all_sheets {
                        let mut label = match self.zh_preview_sheet {
                            Some(i) => self.wb.sheet(i).name.clone(),
                            None => "全部表".to_string(),
                        };
                        egui::ComboBox::from_id_salt("zh_prev_sheet")
                            .selected_text(label.clone())
                            .width(96.0)
                            .show_ui(ui, |ui| {
                                if ui
                                    .selectable_value(&mut self.zh_preview_sheet, None, "全部表")
                                    .clicked()
                                {
                                    variant_changed = true;
                                    label = "全部表".into();
                                }
                                for i in 0..self.wb.sheets.len() {
                                    let name = self.wb.sheet(i).name.clone();
                                    if ui
                                        .selectable_value(
                                            &mut self.zh_preview_sheet,
                                            Some(i),
                                            &name,
                                        )
                                        .clicked()
                                    {
                                        variant_changed = true;
                                        label = name.clone();
                                    }
                                }
                            });
                    }
                    ui.separator();
                    ui.label("目标:");
                    variant_changed |= ui
                        .radio_value(
                            &mut self.zh_preview_variant,
                            sheetcore::zhconv::Variant::Generic,
                            "通用繁体",
                        )
                        .changed();
                    variant_changed |= ui
                        .radio_value(
                            &mut self.zh_preview_variant,
                            sheetcore::zhconv::Variant::Taiwan,
                            "台湾正体",
                        )
                        .changed();
                    variant_changed |= ui
                        .radio_value(
                            &mut self.zh_preview_variant,
                            sheetcore::zhconv::Variant::HongKong,
                            "香港繁体",
                        )
                        .changed();
                });
                ui.add_space(3.0);
                ui.label(
                    egui::RichText::new(format!(
                        "{} {} 个单元格会被改动（只列有差异的）",
                        if self.zh_preview_all_sheets {
                            "整簿内"
                        } else {
                            "选区内"
                        },
                        self.zh_preview.len()
                    ))
                    .size(11.5)
                    .color(ui_kit::TEXT_WEAK),
                );
                ui.add_space(2.0);
                egui::ScrollArea::vertical().max_height(330.0).show(ui, |ui| {
                    if self.zh_preview.is_empty() {
                        ui.label(egui::RichText::new("选区里没有需要转换的内容。").size(12.0));
                    }
                    for (si, r, c, old, new) in self.zh_preview.clone() {
                        ui.horizontal(|ui| {
                            let addr = if self.zh_preview_all_sheets {
                                let name = self.wb.sheet(si).name.clone();
                                format!("{name}!{}", cell_name(r, c))
                            } else {
                                cell_name(r, c)
                            };
                            ui.add_sized(
                                [110.0, 20.0],
                                egui::Label::new(
                                    egui::RichText::new(addr).size(11.5).monospace(),
                                )
                                .truncate(),
                            );
                            ui.add_sized(
                                [220.0, 20.0],
                                egui::Label::new(
                                    egui::RichText::new(old).size(11.5).color(ui_kit::TEXT_WEAK),
                                )
                                .truncate(),
                            );
                            ui.label(egui::RichText::new("→").size(11.5));
                            ui.add_sized(
                                [220.0, 20.0],
                                egui::Label::new(egui::RichText::new(new).size(11.5)).truncate(),
                            );
                        });
                    }
                });
                ui_kit::footer(ui, |ui| {
                    if ui
                        .add_enabled(
                            !self.zh_preview.is_empty(),
                            egui::Button::new("应用转换"),
                        )
                        .clicked()
                    {
                        apply = true;
                    }
                    if ui_kit::primary_button(ui, "取消").clicked() {
                        self.zh_preview_dlg = false;
                    }
                });
            });
        if variant_changed {
            let v = ui_prefs::variant_to_u8(self.zh_preview_variant);
            if self.prefs.zh_variant != v {
                self.prefs.zh_variant = v;
                self.prefs.save();
            }
            self.zh_preview_scan();
        }
        if apply {
            self.zh_apply_preview();
        }
        if !open {
            self.zh_preview_dlg = false;
        }
    }

    /// 只修指定的几格（双击列表行时用）
    fn proof_fix_cells(&mut self, cells: Vec<(u32, u32)>) {
        if self.edit_blocked() || cells.is_empty() {
            return;
        }
        let txn = self.txn_begin(&cells);
        let mut n = 0usize;
        for (r, c) in &cells {
            let sh = self.wb.sheet(self.sheet_idx);
            let Some(cell) = sh.get(*r, *c) else { continue };
            let sheetcore::model::Value::Text(t) = &cell.value else {
                continue;
            };
            let fixed = sheetcore::proof::fix_text(t, &self.proof_rules);
            if fixed.as_str() == t.as_ref() {
                continue;
            }
            let sh = self.wb.sheet_mut(self.sheet_idx);
            let mut cell = sh.get(*r, *c).cloned().unwrap_or_default();
            cell.value = sheetcore::model::Value::Text(fixed.into());
            sh.set(*r, *c, cell);
            n += 1;
        }
        self.txn_end("校对修正", txn);
        self.wb.dirty = true;
        self.doc_gen = self.doc_gen.wrapping_add(1);
        self.proof_rescan();
        self.status = format!("校对修正：{n} 个单元格");
    }

    /// 按当前规则修正：only_sel=true 只修当前选中的那一格
    fn proof_apply_fix(&mut self, only_sel: bool) {
        if self.edit_blocked() {
            return;
        }
        let mut targets: Vec<(u32, u32)> = if only_sel {
            let (r, c) = self.sel;
            self.proof_list
                .iter()
                .filter(|i| i.row == r && i.col == c)
                .map(|i| (i.row, i.col))
                .collect()
        } else {
            self.proof_list.iter().map(|i| (i.row, i.col)).collect()
        };
        targets.sort();
        targets.dedup();
        if targets.is_empty() {
            self.status = "没有可修正的单元格".into();
            return;
        }
        let txn = self.txn_begin(&targets);
        let mut n = 0usize;
        for (r, c) in &targets {
            let sh = self.wb.sheet(self.sheet_idx);
            let Some(cell) = sh.get(*r, *c) else { continue };
            let sheetcore::model::Value::Text(t) = &cell.value else {
                continue;
            };
            let fixed = sheetcore::proof::fix_text(t, &self.proof_rules);
            if fixed.as_str() == t.as_ref() {
                continue;
            }
            let sh = self.wb.sheet_mut(self.sheet_idx);
            let mut cell = sh.get(*r, *c).cloned().unwrap_or_default();
            cell.value = sheetcore::model::Value::Text(fixed.into());
            sh.set(*r, *c, cell);
            n += 1;
        }
        self.txn_end("校对修正", txn);
        self.wb.dirty = true;
        self.doc_gen = self.doc_gen.wrapping_add(1);
        self.proof_rescan();
        self.status = format!("校对修正：{n} 个单元格");
    }

    /// 收/展到第 k 级（Excel 左上角 1/2/3 按钮的语义）：级别 > k 的藏起来，≤ k 的露出来
    fn set_outline_level(&mut self, is_rows: bool, k: u8) {
        if self.edit_blocked() {
            return;
        }
        let (levels, n_hidden) = {
            let sh = self.wb.sheet(self.sheet_idx);
            let map = if is_rows {
                sh.row_levels.clone()
            } else {
                sh.col_levels.clone()
            };
            let mut hidden: Vec<u32> = Vec::new();
            for (idx, lv) in map.iter() {
                if *lv > k {
                    hidden.push(*idx);
                }
            }
            (map, hidden)
        };
        if levels.is_empty() {
            return;
        }
        let mut txn = Vec::new();
        {
            let sh = self.wb.sheet_mut(self.sheet_idx);
            let hid = if is_rows {
                &mut sh.hidden_rows_user
            } else {
                &mut sh.hidden_cols
            };
            for idx in levels.keys() {
                hid.remove(idx);
            }
            for idx in &n_hidden {
                hid.insert(*idx);
                txn.push(if is_rows {
                    (*idx, None)
                } else {
                    (0, Some(*idx))
                });
            }
        }
        self.wb.dirty = true;
        self.doc_gen = self.doc_gen.wrapping_add(1);
        for _ in txn {}
        self.status = format!(
            "{}分级显示：显示到第 {k} 级（隐藏 {} {}）",
            if is_rows { "行" } else { "列" },
            n_hidden.len(),
            if is_rows { "行" } else { "列" }
        );
    }

    /// 分级显示设置：明细位置（上/下、左/右）+ 是否显示分级符号
    fn outline_settings_window(&mut self, ctx: &egui::Context) {
        if !self.outline_set_dlg {
            return;
        }
        let mut open = true;
        let mut changed = false;
        let (mut below, mut right, mut symbols) = {
            let sh = self.wb.sheet(self.sheet_idx);
            (
                sh.outline_summary_below,
                sh.outline_summary_right,
                sh.outline_symbols,
            )
        };
        ui_kit::window(ctx, "设置分级显示", 420.0)
            .open(&mut open)
            .show(ctx, |ui| {
                ui.label(egui::RichText::new("明细数据的表示方式").size(12.0).strong());
                changed |= ui.radio_value(&mut below, true, "明细数据在下方").changed();
                changed |= ui.radio_value(&mut below, false, "明细数据在上方").changed();
                ui.add_space(4.0);
                changed |= ui.radio_value(&mut right, true, "明细数据在右侧").changed();
                changed |= ui.radio_value(&mut right, false, "明细数据在左侧").changed();
                ui.add_space(6.0);
                changed |= ui.checkbox(&mut symbols, "显示分级符号（+ / -）").changed();
                ui_kit::footer(ui, |ui| {
                    if ui_kit::primary_button(ui, "确定").clicked() {
                        self.outline_set_dlg = false;
                    }
                });
            });
        if changed {
            {
                let sh = self.wb.sheet_mut(self.sheet_idx);
                sh.outline_summary_below = below;
                sh.outline_summary_right = right;
                sh.outline_symbols = symbols;
                sh.outline_pr_dirty = true;
            }
            self.wb.dirty = true;
            self.doc_gen = self.doc_gen.wrapping_add(1);
            self.status = format!(
                "分级显示：明细{}方 / 明细{}侧 / 符号{}",
                if below { "下" } else { "上" },
                if right { "右" } else { "左" },
                if symbols { "显示" } else { "隐藏" }
            );
        }
        if !open {
            self.outline_set_dlg = false;
        }
    }

    /// 按当前范围重扫：整表或选区
    fn proof_rescan(&mut self) {
        let all = sheetcore::proof::scan(self.wb.sheet(self.sheet_idx), &self.proof_rules);
        if self.proof_only_sel {
            let (r1, c1, r2, c2) = self.sel_rect();
            self.proof_list = all
                .into_iter()
                .filter(|i| i.row >= r1 && i.row <= r2 && i.col >= c1 && i.col <= c2)
                .collect();
        } else {
            self.proof_list = all;
        }
    }

    fn open_proof(&mut self) {
        self.proof_rescan();
        self.proof_dlg = true;
        self.status = if self.proof_list.is_empty() {
            "没有发现排版问题".into()
        } else {
            format!("发现 {} 处排版问题", self.proof_list.len())
        };
    }

    fn proof_window(&mut self, ctx: &egui::Context) {
        if !self.proof_dlg {
            return;
        }
        let mut open = true;
        let mut jump: Option<(u32, u32)> = None;
        let mut changed = false;
        let mut fix_all = false;
        let mut fix_one = false;
        let mut fix_cells: Vec<(u32, u32)> = Vec::new();
        ui_kit::window(ctx, "拼写检查", 600.0)
            .open(&mut open)
            .show(ctx, |ui| {
                ui.horizontal(|ui| {
                    changed |= ui
                        .checkbox(&mut self.proof_only_sel, "只查选区")
                        .on_hover_text("不勾就查整张表")
                        .changed();
                    if ui
                        .checkbox(&mut self.prefs.proof_group, "按类型分组")
                        .changed()
                    {
                        self.prefs.save();
                        changed = true;
                    }
                    ui.separator();
                    changed |= ui
                        .checkbox(&mut self.proof_rules.double_space, "多个空格")
                        .changed();
                    changed |= ui
                        .checkbox(&mut self.proof_rules.edge_space, "首尾空格")
                        .changed();
                    changed |= ui
                        .checkbox(&mut self.proof_rules.full_width, "全角字母数字")
                        .changed();
                    changed |= ui
                        .checkbox(&mut self.proof_rules.repeat_punct, "重复标点")
                        .changed();
                    changed |= ui
                        .checkbox(&mut self.proof_rules.half_punct, "中文里的半角标点")
                        .changed();
                });
                ui.add_space(4.0);
                ui.label(
                    egui::RichText::new(format!(
                        "当前表共 {} 处（点一行跳到那个单元格）",
                        self.proof_list.len()
                    ))
                    .size(11.5)
                    .color(ui_kit::TEXT_WEAK),
                );
                ui.add_space(2.0);
                egui::ScrollArea::vertical().max_height(320.0).show(ui, |ui| {
                    if self.proof_list.is_empty() {
                        ui.label(egui::RichText::new("没有发现排版问题。").size(12.0));
                    }
                    // 按类型分组时先出一行小标题；顺序固定，方便对照
                    let group_mode = self.prefs.proof_group;
                    let mut items: Vec<sheetcore::proof::ProofIssue> = self.proof_list.clone();
                    if group_mode {
                        let order = |k: sheetcore::proof::ProofKind| -> u8 {
                            use sheetcore::proof::ProofKind::*;
                            match k {
                                EdgeSpace => 0,
                                DoubleSpace => 1,
                                FullWidth => 2,
                                RepeatPunct => 3,
                                HalfPunct => 4,
                            }
                        };
                        items.sort_by_key(|i| (order(i.kind), i.row, i.col));
                    }
                    let mut last_kind: Option<sheetcore::proof::ProofKind> = None;
                    for it in items {
                        if group_mode && last_kind != Some(it.kind) {
                            let n = self
                                .proof_list
                                .iter()
                                .filter(|x| x.kind == it.kind)
                                .count();
                            last_kind = Some(it.kind);
                            ui.add_space(2.0);
                            ui.label(
                                egui::RichText::new(format!("{}（{n}）", it.kind.detail()))
                                    .size(11.0)
                                    .strong()
                                    .color(ui_kit::ACCENT),
                            );
                        }
                        let row_resp = ui.horizontal(|ui| {
                            if ui
                                .add_sized(
                                    [64.0, 20.0],
                                    egui::Button::new(
                                        egui::RichText::new(cell_name(it.row, it.col))
                                            .size(11.5)
                                            .monospace(),
                                    )
                                    .frame(false),
                                )
                                .on_hover_text("双击就地修好这一格")
                                .clicked()
                            {
                                jump = Some((it.row, it.col));
                            }
                            ui.add_sized(
                                [150.0, 20.0],
                                egui::Label::new(egui::RichText::new(&it.text).size(11.5))
                                    .truncate(),
                            );
                            ui.label(
                                egui::RichText::new(it.kind.detail())
                                    .size(11.0)
                                    .color(ui_kit::TEXT_WEAK),
                            );
                        });
                        let resp = row_resp
                            .response
                            .interact(egui::Sense::click())
                            .on_hover_text("双击：跳过去并修好这一格");
                        if std::env::var("SC_PROOF_RECT").is_ok() {
                            let r = resp.rect;
                            eprintln!(
                                "[rect] {} center=({:.0},{:.0}) ppp={:.2} screen={:?}",
                                cell_name(it.row, it.col),
                                r.center().x,
                                r.center().y,
                                ui.ctx().pixels_per_point(),
                                ui.ctx().input(|i| i.pointer.latest_pos())
                            );
                        }
                        if std::env::var("SC_PROOF_RECT").is_ok()
                            && (resp.clicked() || resp.double_clicked())
                        {
                            eprintln!(
                                "[row] {} click={} dbl={}",
                                cell_name(it.row, it.col),
                                resp.clicked(),
                                resp.double_clicked()
                            );
                        }
                        if resp.double_clicked() {
                            jump = Some((it.row, it.col));
                            fix_cells.push((it.row, it.col));
                        }
                    }
                });
                ui.add_space(4.0);
                ui_kit::footer(ui, |ui| {
                    if ui
                        .add_enabled(
                            !self.proof_list.is_empty(),
                            egui::Button::new("修正全部"),
                        )
                        .on_hover_text("按当前规则修掉列表里的所有问题（可撤销）")
                        .clicked()
                    {
                        fix_all = true;
                    }
                    if ui
                        .add_enabled(
                            !self.proof_list.is_empty(),
                            egui::Button::new("修正此单元格"),
                        )
                        .clicked()
                    {
                        fix_one = true;
                    }
                    if ui.button("重新检查").clicked() {
                        self.proof_rescan();
                    }
                    if ui_kit::primary_button(ui, "关闭").clicked() {
                        self.proof_dlg = false;
                    }
                });
            });
        if !fix_cells.is_empty() {
            let cells = std::mem::take(&mut fix_cells);
            self.proof_fix_cells(cells);
        } else if fix_all {
            self.proof_apply_fix(false);
        } else if fix_one {
            self.proof_apply_fix(true);
        } else if changed {
            self.proof_list =
                sheetcore::proof::scan(self.wb.sheet(self.sheet_idx), &self.proof_rules);
        }
        if let Some((r, c)) = jump {
            self.sel = (r, c);
            self.sel_end = (r, c);
            self.ensure_visible();
        }
        if !open {
            self.proof_dlg = false;
        }
    }

    /// 中文简繁转换：把选区里的文本单元格整段转换（词组优先，见 core::zhconv）
    fn zh_convert(&mut self, to_trad: bool, variant: sheetcore::zhconv::Variant) {
        if to_trad && self.prefs.zh_variant != ui_prefs::variant_to_u8(variant) {
            self.prefs.zh_variant = ui_prefs::variant_to_u8(variant);
            self.prefs.save();
        }
        if self.edit_blocked() {
            return;
        }
        let (r1, c1, r2, c2) = self.sel_rect();
        if (r2 - r1) as u64 * (c2 - c1) as u64 > 200_000 {
            self.status = "选区太大，先选一块再转换".into();
            return;
        }
        let mut keys: Vec<(u32, u32)> = Vec::new();
        let mut work: Vec<(u32, u32, String)> = Vec::new();
        {
            let sh = self.wb.sheet(self.sheet_idx);
            for r in r1..=r2 {
                for c in c1..=c2 {
                    let Some(cell) = sh.get(r, c) else { continue };
                    let sheetcore::model::Value::Text(t) = &cell.value else {
                        continue;
                    };
                    let new = if to_trad {
                        sheetcore::zhconv::to_traditional_with(t, variant)
                    } else {
                        sheetcore::zhconv::to_simplified(t)
                    };
                    if new.as_str() != t.as_ref() {
                        keys.push((r, c));
                        work.push((r, c, new));
                    }
                }
            }
        }
        if work.is_empty() {
            self.status = "选区里没有需要转换的文本".into();
            return;
        }
        let txn = self.txn_begin(&keys);
        let n = work.len();
        for (r, c, text) in work {
            let sh = self.wb.sheet_mut(self.sheet_idx);
            let mut cell = sh.get(r, c).cloned().unwrap_or_default();
            cell.value = sheetcore::model::Value::Text(text.into());
            sh.set(r, c, cell);
        }
        self.txn_end(if to_trad { "简转繁" } else { "繁转简" }, txn);
        self.wb.dirty = true;
        self.doc_gen = self.doc_gen.wrapping_add(1);
        let label = if to_trad {
            match variant {
                sheetcore::zhconv::Variant::Generic => "简转繁（通用）",
                sheetcore::zhconv::Variant::Taiwan => "简转繁（台湾正体）",
                sheetcore::zhconv::Variant::HongKong => "简转繁（香港繁体）",
            }
        } else {
            "繁转简"
        };
        self.status = format!("{label}：已转换 {n} 个单元格");
    }

    /// 清除内容（保留格式，和 Excel「清除内容」一致）
fn clear_selection(&mut self) {
        self.clear_rects(ClearPart::Contents);
    }

    /// 字体/填充颜色面板（Excel 的主题色 + 标准色）
    fn color_popup_window(&mut self, ctx: &egui::Context) {
        let Some(for_font) = self.color_popup else { return };
        let title = if for_font { "字体颜色" } else { "填充颜色" };
        let mut open = true;
        let mut pick: Option<Color32> = None;
        let mut clear_fill = false;
        egui::Window::new(title)
            .id(egui::Id::new("color_popup"))
            .collapsible(false)
            .resizable(false)
            .default_pos(ctx.screen_rect().center() - egui::vec2(90.0, 120.0))
            .show(ctx, |ui| {
                let colors: [u32; 20] = [
                    0xFFFFFF, 0x000000, 0xE7E6E6, 0x44546A, 0x4472C4,
                    0xED7D31, 0xA5A5A5, 0xFFC000, 0x5B9BD5, 0x70AD47,
                    0x255E91, 0x9E480E, 0x636363, 0x997300, 0x264478,
                    0x43682B, 0xFF0000, 0xFFC0CB, 0xFFD700, 0x00B050,
                ];
                ui.spacing_mut().item_spacing = egui::vec2(3.0, 3.0);
                for row in 0..4 {
                    ui.horizontal(|ui| {
                        for col in 0..5 {
                            let hex = colors[row * 5 + col];
                            let c = Color32::from_rgb(
                                ((hex >> 16) & 0xFF) as u8,
                                ((hex >> 8) & 0xFF) as u8,
                                (hex & 0xFF) as u8,
                            );
                            let (rect, resp) =
                                ui.allocate_exact_size(egui::vec2(24.0, 20.0), egui::Sense::click());
                            ui.painter().rect_filled(rect, 2.0, c);
                            ui.painter().rect_stroke(
                                rect,
                                2.0,
                                egui::Stroke::new(1.0, Color32::from_rgb(190, 190, 190)),
                                egui::StrokeKind::Inside,
                            );
                            if resp.clicked() {
                                pick = Some(c);
                            }
                        }
                    });
                }
                ui.add_space(2.0);
                ui.separator();
                if !for_font && ui.button("无填充颜色").clicked() {
                    clear_fill = true;
                }
                if ui.button("更多颜色…").clicked() {
                    // 简易取色：打开系统色板
                    let mut c = if for_font {
                        Color32::from_rgb(
                            self.current_style().color[0],
                            self.current_style().color[1],
                            self.current_style().color[2],
                        )
                    } else {
                        let f = self.current_style().fill.unwrap_or([255, 255, 255]);
                        Color32::from_rgb(f[0], f[1], f[2])
                    };
                    if ui.color_edit_button_srgba(&mut c).changed() {
                        pick = Some(c);
                    }
                }
            });
        if ctx.input(|i| i.key_pressed(egui::Key::Escape)) {
            open = false;
        }
        if let Some(c) = pick {
            let rgb = [c.r(), c.g(), c.b()];
            if for_font {
                self.apply_style(move |s| s.color = rgb);
            } else {
                self.apply_style(move |s| s.fill = Some(rgb));
            }
            open = false;
        }
        if clear_fill {
            self.apply_style(|s| s.fill = None);
            open = false;
        }
        if !open {
            self.color_popup = None;
        }
    }

    fn current_style(&self) -> sheetcore::style::CellStyle {
        let id = self.wb.sheet(self.sheet_idx).style_of(self.sel.0, self.sel.1);
        self.wb.styles.get(id).clone()
    }

    /// 对选区每个格子套用样式改动；只影响显示，不触发重算
    fn apply_style<F: Fn(&mut sheetcore::style::CellStyle)>(&mut self, f: F) {
        self.apply_style_xy(move |st, _r, _c| f(st));
    }

    /// 同上，但闭包能拿到格子坐标（画边框要用）
    fn apply_style_xy<F: Fn(&mut sheetcore::style::CellStyle, u32, u32)>(&mut self, f: F) {
        if self.edit_blocked() {
            return;
        }
        let rects = self.sel_rects();
        let total: u64 = rects
            .iter()
            .map(|(r1, c1, r2, c2)| (r2 - r1 + 1) as u64 * (c2 - c1 + 1) as u64)
            .sum();
        if total > 200_000 {
            self.status = "选区太大（超过 20 万格），不给整块刷格式".into();
            return;
        }
        let mut keys: Vec<(u32, u32)> = Vec::new();
        for (r1, c1, r2, c2) in rects.iter() {
            keys.extend(sheetcore::undo::rect_keys(*r1, *c1, *r2, *c2));
        }
                keys.sort_unstable();
        keys.dedup();
        if !self.write_preflight(&keys, "设置格式") {
            return;
        }
let txn = self.txn_begin(&keys);
        let mut wire: Vec<(u32, u32, sheetcore::style::CellStyle)> = Vec::new();
        for (r1, c1, r2, c2) in rects.iter().copied() {
            for r in r1..=r2 {
                for c in c1..=c2 {
                    let old = self.wb.sheet(self.sheet_idx).style_of(r, c);
                    let mut st = self.wb.styles.get(old).clone();
                    f(&mut st, r, c);
                    let id = self.wb.styles.intern(st.clone());
                    self.wb.sheet_mut(self.sheet_idx).set_style(r, c, id);
                    wire.push((r, c, st));
                }
            }
        }
        if let Some(net) = self.net.as_ref() {
            net.broadcast_style(self.sheet_idx, wire);
        }
        self.txn_end("设置格式", txn);
        self.wb.dirty = true;
        self.doc_gen = self.doc_gen.wrapping_add(1);
    }

    /// 只给选区外沿加边框（内部各格不重复画）
    fn outer_border(&mut self, style: u8, color: [u8; 3]) {
        let (r1, c1, r2, c2) = self.sel_rect();
        self.apply_style_xy(move |st, r, c| {
            let mut b = st.border;
            // 左 右 上 下
            if c == c1 {
                b[0] = sheetcore::style::Border { style, color };
            }
            if c == c2 {
                b[1] = sheetcore::style::Border { style, color };
            }
            if r == r1 {
                b[2] = sheetcore::style::Border { style, color };
            }
            if r == r2 {
                b[3] = sheetcore::style::Border { style, color };
            }
            st.border = b;
        });
    }

    fn toggle_merge(&mut self, on: bool) {
        if self.edit_blocked() {
            return;
        }
        let (r1, c1, r2, c2) = self.sel_rect();
        if on && r1 == r2 && c1 == c2 {
            self.status = "请选择两个以上单元格再合并".into();
            return;
        }
        let keys = sheetcore::undo::rect_keys(r1, c1, r2, c2);
        if !self.write_preflight(&keys, if on { "合并单元格" } else { "取消合并" }) {
            return;
        }
        // 合并只保留左上角内容；其余非空格会被删掉，先让用户确认。
        let mut loss = 0u64;
        let mut anchor = sheetcore::model::Cell::default();
        let mut removed_cells: Vec<(u32, u32, sheetcore::model::Cell)> = Vec::new();
        {
            let sheet = self.wb.sheet(self.sheet_idx);
            anchor = sheet.get(r1, c1).cloned().unwrap_or_default();
            if on {
                for r in r1..=r2 {
                    for c in c1..=c2 {
                        if r == r1 && c == c1 {
                            continue;
                        }
                        if let Some(cell) = sheet.get(r, c) {
                            if !cell.is_blank() {
                                loss += 1;
                                removed_cells.push((r, c, cell.clone()));
                            }
                        }
                    }
                }
            }
        }
        let confirmed = on
            && loss > 0
            && self.merge_pending.as_ref().is_some_and(|p| {
                p.wb_epoch == self.wb_epoch
                    && p.doc_gen == self.doc_gen
                    && p.sheet == self.sheet_idx
                    && p.rect == (r1, c1, r2, c2)
                    && p.anchor == anchor
                    && p.removed == removed_cells
            });
        if on && loss > 0 && !confirmed {
            let shown = if anchor.value.display().is_empty() {
                "（空）".to_string()
            } else {
                anchor.value.display()
            };
            self.merge_pending = Some(MergePending {
                wb_epoch: self.wb_epoch,
                doc_gen: self.doc_gen,
                sheet: self.sheet_idx,
                rect: (r1, c1, r2, c2),
                anchor,
                removed: removed_cells.clone(),
            });
            self.status = format!(
                "合并只保留左上角「{shown}」的内容，其余 {loss} 格内容会被删除；再点一次合并确认"
            );
            return;
        }
        self.merge_pending = None;
        let before_merges = self.wb.sheet(self.sheet_idx).merges.clone();
        let deltas = self.txn_begin(&keys);
        {
            let sheet = self.wb.sheet_mut(self.sheet_idx);
            if on {
                for (r, c, _) in removed_cells.iter() {
                    sheet.set(*r, *c, sheetcore::model::Cell {
                        value: sheetcore::model::Value::Empty,
                        formula: None,
                    });
                }
                sheet.merge_range(r1, c1, r2, c2);
            } else {
                sheet.unmerge_range(r1, c1, r2, c2);
            }
        }
        let after_merges = self.wb.sheet(self.sheet_idx).merges.clone();
        let deltas = sheetcore::undo::finish(deltas, self.wb.sheet(self.sheet_idx));
        let changed = before_merges != after_merges || !deltas.is_empty();
        if changed {
            self.undo.push(sheetcore::undo::Action {
                label: if on { "合并单元格".into() } else { "取消合并".into() },
                merges: sheetcore::undo::MergeEdit::between(
                    self.sheet_idx,
                    &before_merges,
                    &after_merges,
                ),
                deltas,
                focus: (self.sheet_idx, self.sel.0, self.sel.1),
                snap_before: None,
                snap_after: None,
                by_site: 0,
                shapes: None,
                refresh_sizes: None,
            });
        }
        if let (Some(peer), Some(net)) = (self.peer.as_mut(), self.net.as_ref()) {
            for (r, c, _) in removed_cells.iter() {
                let cell = self.wb.sheet(self.sheet_idx).get(*r, *c).cloned().unwrap_or_default();
                let op = peer.local_set(self.sheet_idx, *r, *c, &cell);
                net.broadcast_op(op);
            }
            net.broadcast_merge(self.sheet_idx, (r1, c1, r2, c2), on);
        }
        self.wb.dirty = true;
        self.doc_gen = self.doc_gen.wrapping_add(1);
        self.deps = sheetcore::formula::deps::Deps::build(&self.wb);
        sheetcore::formula::recalc_all(&mut self.wb);
        self.status = if on { "已合并选区".into() } else { "已取消合并".into() };
    }

    /// 格式对话框点「确定」：先落格式，再执行挂起的合并动作。
    fn commit_fmt_merge(&mut self) {
        if let Some(on) = self.fmt_merge_pending.take() {
            self.toggle_merge(on);
        }
    }

    /// 格式刷：把源区域样式按行列重复铺到当前选区，一次撤销。
    fn apply_format_painter(&mut self) {
        let Some(p) = self.format_painter.clone() else { return };
        if p.wb_epoch != self.wb_epoch || p.sheet != self.sheet_idx {
            self.format_painter = None;
            self.painter_double = false;
            self.status = "文档或工作表已切换，格式刷已取消".into();
            return;
        }
        if self.edit_blocked() {
            return;
        }
        let (tr1, tc1, tr2, tc2) = self.sel_rect();
        let area = (tr2 - tr1 + 1) as u64 * (tc2 - tc1 + 1) as u64;
        if area > 200_000 {
            self.status = "目标区域太大（超过 20 万格），格式刷不执行".into();
            return;
        }
        let (sr1, sc1, sr2, sc2) = p.rect;
        let sh = (sr2 - sr1 + 1) as u32;
        let sw = (sc2 - sc1 + 1) as u32;
        if sh == 0 || sw == 0 {
            self.format_painter = None;
            return;
        }
        let keys = sheetcore::undo::rect_keys(tr1, tc1, tr2, tc2);
        if !self.write_preflight(&keys, "格式刷") {
            return;
        }
        let txn = self.txn_begin(&keys);
        let mut wire: Vec<(u32, u32, sheetcore::style::CellStyle)> = Vec::new();
        for r in tr1..=tr2 {
            for c in tc1..=tc2 {
                let i = ((r - tr1) % sh) as usize;
                let j = ((c - tc1) % sw) as usize;
                let sid = p.styles[i][j];
                self.wb.sheet_mut(self.sheet_idx).set_style(r, c, sid);
                wire.push((r, c, self.wb.styles.get(sid).clone()));
            }
        }
        if let Some(net) = self.net.as_ref() {
            net.broadcast_style(self.sheet_idx, wire);
        }
        self.txn_end("格式刷", txn);
        self.wb.dirty = true;
        self.doc_gen = self.doc_gen.wrapping_add(1);
        if p.continuous {
            self.status = "格式刷（连续）：继续选择目标区域，Esc 结束".into();
        } else {
            self.format_painter = None;
            self.status = "已套用格式".into();
        }
    }

    /// 格式工具栏（第二行）
    // ===== 功能区（Excel 式分组）=====

    /// Excel 的「文件」后台视图：左侧一列导航，右侧整块内容。
    /// 打开时盖住功能区和表格，标题栏保留。
    /// 富文本：选中文字后加粗/改色/改字号
    fn rich_dialog(&mut self, ctx: &egui::Context) {
        let Some(mut d) = self.rich_dlg.take() else { return };
        let mut open = true;
        let mut apply = false;
        ui_kit::window(ctx, "富文本", 420.0).open(&mut open).show(ctx, |ui| {
            ui.label("先选中文字，再点下面的按钮；不选表示整格");
            let text = sheetcore::richtext::runs_text(&d.runs);
            let mut buf = text.clone();
            let out = egui::TextEdit::multiline(&mut buf)
                .desired_rows(4)
                .desired_width(380.0)
                .show(ui);
            if let Some(range) = out.cursor_range {
                let a = range.primary.ccursor.index;
                let b = range.secondary.ccursor.index;
                d.sel = if a <= b { (a, b) } else { (b, a) };
            }
            if out.response.changed() {
                d.runs = vec![sheetcore::richtext::RichRun::plain(buf)];
            }
            let (start, end) = if d.sel.0 == d.sel.1 {
                (0, d.runs.iter().map(|r| r.text.chars().count()).sum())
            } else {
                d.sel
            };
            ui.horizontal(|ui| {
                if ui.button("加粗").clicked() {
                    sheetcore::richtext::apply_range(&mut d.runs, start, end, &|r| {
                        r.bold = !r.bold
                    });
                }
                if ui.button("斜体").clicked() {
                    sheetcore::richtext::apply_range(&mut d.runs, start, end, &|r| {
                        r.italic = !r.italic
                    });
                }
                for (name, c) in [("红", [192, 0, 0]), ("蓝", [0, 70, 180]), ("绿", [16, 124, 65])] {
                    if ui.button(name).clicked() {
                        sheetcore::richtext::apply_range(&mut d.runs, start, end, &move |r| {
                            r.color = Some(c)
                        });
                    }
                }
                if ui.button("恢复默认").clicked() {
                    sheetcore::richtext::apply_range(&mut d.runs, start, end, &|r| {
                        r.bold = false;
                        r.italic = false;
                        r.color = None;
                        r.size = None;
                        r.font = None;
                    });
                }
            });
            ui.horizontal(|ui| {
                ui.label("字号");
                let mut sz = d.size.max(11.0) as f64;
                if ui_kit::spin(ui, &mut sz, 6.0, 72.0, 1.0, 54.0) {
                    d.size = sz as f32;
                }
                if ui.button("应用到选中").clicked() {
                    let sz = d.size.max(6.0);
                    sheetcore::richtext::apply_range(&mut d.runs, start, end, &move |r| {
                        r.size = Some(sz)
                    });
                }
            });
            ui_kit::footer(ui, |ui| {
                if ui_kit::primary_button(ui, "确定").clicked() {
                    apply = true;
                }
                if ui_kit::secondary_button(ui, "取消").clicked() {
                    open = false;
                }
            });
        });
        if apply {
            let runs = std::mem::take(&mut d.runs);
            let text = sheetcore::richtext::runs_text(&runs);
            let key = (d.r, d.c);
            {
                let sheet = self.wb.sheet_mut(self.sheet_idx);
                sheet.rich.insert(key, runs);
                sheet.rich_dirty = true;
                sheet.set(
                    d.r,
                    d.c,
                    sheetcore::model::Cell {
                        value: sheetcore::model::Value::Text(text.into()),
                        formula: None,
                    },
                );
            }
            self.wb.dirty = true;
            self.doc_gen = self.doc_gen.wrapping_add(1);
            self.status = "富文本已应用（保存后 Excel 里能看到分段格式）".into();
            open = false;
        }
        if open {
            self.rich_dlg = Some(d);
        }
    }

    /// 打开超链接：外部地址交给系统默认程序，内部位置跳到对应表/格
    fn open_hyperlink(&mut self, link: &sheetcore::hyperlinks::Hyperlink) {
        if !link.location.is_empty() {
            let loc = link.location.trim_start_matches('#');
            if let Some((sheet, a1)) = loc.rsplit_once('!') {
                let sheet = sheet.trim_matches('\'');
                if let Some(i) = self.wb.sheets.iter().position(|s| s.name == sheet) {
                    self.sheet_idx = i;
                }
                if let Some((r, c)) = parse_a1_ref(a1) {
                    self.sel = (r, c);
                    self.sel_end = self.sel;
                    self.ensure_visible();
                }
            }
            return;
        }
        if link.target.is_empty() {
            return;
        }
        let _ = std::process::Command::new("rundll32")
            .args(["url.dll,FileProtocolHandler", &link.target])
            .spawn();
        self.status = format!("已打开 {}", link.target);
    }

    /// 插入超链接对话框
    fn hyperlink_dialog(&mut self, ctx: &egui::Context) {
        let Some((mut url, mut text)) = self.hyper_dlg.take() else { return };
        let mut open = true;
        let mut apply = false;
        let mut close = false;
        ui_kit::window(ctx, "插入超链接", 380.0).open(&mut open).show(ctx, |ui| {
            dlg_section(ui, "链接");
            ui_kit::field(ui, "地址", |ui| {
                let r = ui.add(egui::TextEdit::singleline(&mut url).desired_width(260.0));
                ui_kit::autofocus(ui, &r);
            });
            ui_kit::field(ui, "显示文字", |ui| {
                ui.add(egui::TextEdit::singleline(&mut text).desired_width(260.0));
            });
            if !self.link_err.is_empty() {
                ui.colored_label(egui::Color32::from_rgb(190, 40, 40), &self.link_err);
            }
            ui_kit::footer(ui, |ui| {
                if ui_kit::primary_button(ui, "插入").clicked() {
                    apply = true;
                }
                if ui_kit::secondary_button(ui, "取消").clicked() {
                    close = true;
                }
            });
        });
        if apply {
            let url = url.trim().to_string();
            if url.is_empty() {
                self.link_err = "地址不能为空".into();
            } else {
                let (r, c) = self.sel;
                let show = if text.trim().is_empty() { url.clone() } else { text.trim().to_string() };
                {
                    let sh = self.wb.sheet_mut(self.sheet_idx);
                    sh.set(
                        r,
                        c,
                        sheetcore::model::Cell {
                            value: sheetcore::model::Value::Text(show.into()),
                            formula: None,
                        },
                    );
                    sh.hyperlinks.insert(
                        (r, c),
                        sheetcore::hyperlinks::Hyperlink {
                            external: true,
                            target: url.clone(),
                            location: String::new(),
                            tooltip: String::new(),
                        },
                    );
                    sh.hyperlinks_dirty = true;
                }
                self.wb.dirty = true;
                self.doc_gen = self.doc_gen.wrapping_add(1);
                self.status = format!("已插入超链接 {}", url);
                self.hyper_dlg = None;
                self.link_err.clear();
                return;
            }
        }
        if close {
            self.hyper_dlg = None;
            self.link_err.clear();
        } else {
            self.hyper_dlg = Some((url, text));
        }
    }

    /// 关于窗口：版本、协作方式、常用快捷键、许可
    /// 把一个符号插进当前编辑框；没在编辑就先进入编辑、接在原内容后面
    fn insert_symbol(&mut self, ch: char) {
        if let Some(e) = self.editing.as_mut() {
            e.buf.push(ch);
            return;
        }
        let (r, c) = self.sel;
        let mut buf = self.wb.sheet(self.sheet_idx).value(r, c).display();
        buf.push(ch);
        self.editing = Some(EditState::new(buf));
    }

    /// 单元格当前数值（数字才算，其它返回 None）
    fn cell_num(&self, r: u32, c: u32) -> Option<f64> {
        match self.wb.sheet(self.sheet_idx).get(r, c).map(|x| x.value.clone()) {
            Some(sheetcore::model::Value::Number(n)) => Some(n),
            _ => None,
        }
    }

    /// 把一个数字写进格子并按依赖图重算受影响的公式（不记撤销，求解器内部用）
    fn poke_cell(&mut self, deps: &sheetcore::formula::deps::Deps, r: u32, c: u32, v: f64) {
        let sh = self.wb.sheet_mut(self.sheet_idx);
        let mut cell = sh.get(r, c).cloned().unwrap_or_default();
        cell.value = sheetcore::model::Value::Number(v);
        cell.formula = None;
        sh.set(r, c, cell);
        let keys = [(self.sheet_idx, r, c)];
        sheetcore::formula::recalc_dirty(&mut self.wb, deps, &keys);
    }

    /// 单变量求解：找可变格的值，让目标格的公式等于目标值。
    /// 用割线法（两点割线 + 必要时二分兜底），最多 60 次，每次只重算受影响的公式。
    fn goal_seek_run(&mut self, tr: u32, tc: u32, goal: f64, vr: u32, vc: u32) -> Result<f64, String> {
        let Some(orig) = self.cell_num(vr, vc) else {
            return Err("可变单元格里必须是一个数字".into());
        };
        // 依赖图必须现建：大文件加载后 app 里可能是空 deps，靠它重算等于什么都不算
        let deps = sheetcore::formula::deps::Deps::build(&self.wb);
        let f = |app: &mut Self, x: f64| -> Option<f64> {
            app.poke_cell(&deps, vr, vc, x);
            app.cell_num(tr, tc).map(|v| v - goal)
        };
        let mut x0 = orig;
        let mut f0 = f(self, x0).ok_or("目标单元格不是数字（公式可能出错）")?;
        if f0.abs() < 1e-9 {
            return Ok(x0);
        }
        let step = if x0.abs() > 1e-9 { x0.abs() * 0.1 } else { 1.0 };
        let mut x1 = x0 + step;
        let mut f1 = f(self, x1).ok_or("目标单元格不是数字")?;
        let mut lo = f32::NAN;
        let mut hi = f32::NAN;
        for _ in 0..60 {
            if f1.abs() < 1e-9 {
                return Ok(x1);
            }
            if f0.abs() < 1e-9 {
                return Ok(x0);
            }
            // 记下括住根的区间，割线法跳飞时用二分
            if f0 * f1 < 0.0 {
                lo = x0 as f32;
                hi = x1 as f32;
            }
            let denom = f1 - f0;
            let mut next = if denom.abs() > 1e-15 {
                x1 - f1 * (x1 - x0) / denom
            } else {
                f32::NAN as f64
            };
            if !next.is_finite() || (lo.is_finite() && hi.is_finite() && (next < lo.min(hi) as f64 || next > lo.max(hi) as f64)) {
                next = if lo.is_finite() && hi.is_finite() {
                    ((lo as f64) + (hi as f64)) * 0.5
                } else {
                    x1 + step
                };
            }
            x0 = x1;
            f0 = f1;
            x1 = next;
            f1 = f(self, x1).ok_or("目标单元格不是数字")?;
            if (x1 - x0).abs() < 1e-12 * (1.0 + x1.abs()) {
                break;
            }
        }
        if f1.abs() < 1e-6 {
            // 重算只改了模型里的值，保存时公式格的缓存值要按「已编辑」重写
            self.poke_cell(&deps, vr, vc, x1);
            if let Some(cell) = self.wb.sheet(self.sheet_idx).get(tr, tc).cloned() {
                self.wb.sheet_mut(self.sheet_idx).set(tr, tc, cell);
            }
            Ok(x1)
        } else {
            self.poke_cell(&deps, vr, vc, orig);
            Err(format!("没有找到解（最后一次偏差 {:.6}）", f1))
        }
    }

    /// 解析 "A1" / "$B$2" 形式的地址
    fn parse_addr(s: &str) -> Option<(u32, u32)> {
        parse_a1_ref(s.trim().trim_start_matches('$').replace('$', "").as_str())
    }

    /// 按当前规则扫一遍：公式错误 / 数字存为文本 各自可以关掉
    fn scan_issues(&self) -> Vec<sheetcore::errors::Issue> {
        sheetcore::errors::scan_wb(&self.wb, self.sheet_idx)
            .into_iter()
            .filter(|i| match i.kind {
                sheetcore::errors::IssueKind::NumberAsText => self.ec.check_text,
                _ => self.ec.check_errors,
            })
            .collect()
    }

    /// 打开错误检查：重扫一遍当前表
    fn open_error_check(&mut self) {
        self.error_list = self.scan_issues();
        self.error_dlg = true;
        self.status = if self.error_list.is_empty() {
            "这张表没发现错误".into()
        } else {
            format!("找到 {} 处问题", self.error_list.len())
        };
    }

    fn error_window(&mut self, ctx: &egui::Context) {
        if !self.error_dlg {
            return;
        }
        let mut open = true;
        let mut jump: Option<(u32, u32)> = None;
        let mut ignore_sel = false;
        let mut ignore_all = false;
        let mut reset_ignored = false;
        let mut options_clicked = false;
        ui_kit::window(ctx, "错误检查", 600.0)
            .open(&mut open)
            .show(ctx, |ui| {
                ui.label(
                    egui::RichText::new(format!(
                        "当前表共 {} 处（点一行跳到那个单元格）",
                        self.error_list.len()
                    ))
                    .size(11.5)
                    .color(ui_kit::TEXT_WEAK),
                );
                ui.add_space(4.0);
                if self.error_list.is_empty() {
                    ui.label(egui::RichText::new("没有发现错误。").size(12.0));
                }
                egui::ScrollArea::vertical().max_height(320.0).show(ui, |ui| {
                    for it in self.error_list.clone() {
                        ui.horizontal(|ui| {
                            let addr = cell_name(it.row, it.col);
                            if ui
                                .add_sized(
                                    [64.0, 20.0],
                                    egui::Button::new(
                                        egui::RichText::new(addr).size(11.5).monospace(),
                                    )
                                    .frame(false),
                                )
                                .clicked()
                            {
                                jump = Some((it.row, it.col));
                            }
                            ui.add_sized(
                                [120.0, 20.0],
                                egui::Label::new(
                                    egui::RichText::new(if it.text.is_empty() {
                                        "-"
                                    } else {
                                        it.text.as_str()
                                    })
                                    .size(11.5),
                                )
                                .truncate(),
                            );
                            ui.label(
                                egui::RichText::new(it.kind.detail())
                                    .size(11.0)
                                    .color(ui_kit::TEXT_WEAK),
                            );
                        });
                    }
                });
                ui.add_space(6.0);
                ui_kit::footer(ui, |ui| {
                    if ui.button("忽略此单元格").clicked() {
                        ignore_sel = true;
                    }
                    if ui.button("忽略全部").clicked() {
                        ignore_all = true;
                    }
                    if ui.button("重置忽略").clicked() {
                        reset_ignored = true;
                    }
                    if ui.button("选项…").clicked() {
                        options_clicked = true;
                    }
                    if ui.button("重新检查").clicked() {
                        self.error_list = self.scan_issues();
                    }
                    if ui_kit::primary_button(ui, "关闭").clicked() {
                        self.error_dlg = false;
                    }
                });
            });
        if let Some((r, c)) = jump {
            self.sel = (r, c);
            self.sel_end = (r, c);
            self.ensure_visible();
        }
        if ignore_sel {
            let (r, c) = self.sel;
            let sh = self.wb.sheet_mut(self.sheet_idx);
            sh.ignored_errors.insert((r, c));
            sh.ignored_errors_dirty = true;
            self.wb.dirty = true;
            self.doc_gen = self.doc_gen.wrapping_add(1);
            self.error_list = self.scan_issues();
            self.status = format!("已忽略 {} 的错误", sheetcore::model::cell_name(r, c));
        }
        if ignore_all {
            let all: Vec<(u32, u32)> = self.error_list.iter().map(|i| (i.row, i.col)).collect();
            {
                let sh = self.wb.sheet_mut(self.sheet_idx);
                for k in &all {
                    sh.ignored_errors.insert(*k);
                }
                sh.ignored_errors_dirty = true;
            }
            self.wb.dirty = true;
            self.doc_gen = self.doc_gen.wrapping_add(1);
            let n = all.len();
            self.error_list.clear();
            self.status = format!("已忽略 {n} 处错误");
        }
        if options_clicked {
            self.ec_options = true;
        }
        if reset_ignored {
            {
                let sh = self.wb.sheet_mut(self.sheet_idx);
                sh.ignored_errors.clear();
                sh.ignored_errors_dirty = true;
            }
            self.wb.dirty = true;
            self.doc_gen = self.doc_gen.wrapping_add(1);
            self.error_list = self.scan_issues();
            self.status = "已重置忽略的错误".into();
        }
        if !open {
            self.error_dlg = false;
        }
    }

    /// 错误检查选项：背景检查开关、标记颜色、两条规则的开关（Excel「错误检查选项」那一页）
    fn ec_options_window(&mut self, ctx: &egui::Context) {
        if !self.ec_options {
            return;
        }
        let mut open = true;
        let mut changed = false;
        let mut reset_all = false;
        ui_kit::window(ctx, "错误检查选项", 470.0)
            .open(&mut open)
            .show(ctx, |ui| {
                if ui
                    .checkbox(&mut self.ec.background, "启用背景错误检查（在单元格左上角标出来）")
                    .changed()
                {
                    changed = true;
                }
                ui.horizontal(|ui| {
                    ui.add_sized([80.0, 20.0], egui::Label::new("标记颜色:"));
                    for (name, rgb) in [
                        ("绿", [40u8, 160, 40]),
                        ("红", [200, 40, 40]),
                        ("蓝", [40, 80, 200]),
                        ("橙", [210, 120, 20]),
                    ] {
                        let on = self.ec.color == rgb;
                        if ui.selectable_label(on, name).clicked() {
                            self.ec.color = rgb;
                            changed = true;
                        }
                        let (r, _) = ui.allocate_exact_size(egui::vec2(14.0, 14.0), egui::Sense::hover());
                        ui.painter().rect_filled(
                            r,
                            2.0,
                            Color32::from_rgb(rgb[0], rgb[1], rgb[2]),
                        );
                    }
                });
                ui.add_space(6.0);
                ui.separator();
                ui.add_space(2.0);
                ui.label(egui::RichText::new("检查规则").size(12.0).strong());
                if ui
                    .checkbox(&mut self.ec.check_errors, "公式错误（#DIV/0!、#N/A、#NAME? 等）")
                    .changed()
                {
                    changed = true;
                }
                if ui
                    .checkbox(&mut self.ec.check_text, "数字以文本形式存储")
                    .changed()
                {
                    changed = true;
                }
                ui.add_space(6.0);
                if ui.button("重置所有忽略的错误").clicked() {
                    reset_all = true;
                }
                ui_kit::footer(ui, |ui| {
                    if ui_kit::primary_button(ui, "确定").clicked() {
                        self.ec_options = false;
                    }
                });
            });
        if reset_all {
            {
                let sh = self.wb.sheet_mut(self.sheet_idx);
                sh.ignored_errors.clear();
                sh.ignored_errors_dirty = true;
            }
            self.wb.dirty = true;
            changed = true;
            self.status = "已重置本表忽略的错误".into();
        }
        if changed {
            self.ec.save();
            self.error_marks_key = (u64::MAX, u64::MAX);
            if self.error_dlg {
                self.error_list = self.scan_issues();
            }
        }
        if !open {
            self.ec_options = false;
        }
    }

    /// 方案管理器：保存/显示/删除/摘要
    fn scenario_window(&mut self, ctx: &egui::Context) {
        if !self.scen_dlg {
            return;
        }
        let mut open = true;
        let mut do_add = false;
        let mut do_show = false;
        let mut do_del = false;
        let mut do_summary = false;
        let list = self.wb.sheet(self.sheet_idx).scenarios.clone();
        let mut sel = self.scen_sel;
        ui_kit::window(ctx, "方案管理器", 580.0)
            .open(&mut open)
            .show(ctx, |ui| {
                ui.label(
                    egui::RichText::new("这张表里保存的方案（点一条可以装载到下面的名称/备注）")
                        .size(11.5)
                        .color(ui_kit::TEXT_WEAK),
                );
                ui.add_space(3.0);
                egui::ScrollArea::vertical().max_height(150.0).show(ui, |ui| {
                    if list.is_empty() {
                        ui.label(egui::RichText::new("还没有方案").size(11.5));
                    }
                    for (i, sc) in list.iter().enumerate() {
                        let mut label = format!("{}（{} 个单元格）", sc.name, sc.cells.len());
                        if !sc.comment.is_empty() {
                            label.push_str(&format!(" — {}", sc.comment));
                        }
                        if ui.selectable_label(sel == Some(i), label).clicked() {
                            sel = Some(i);
                            self.scen_name = sc.name.clone();
                            self.scen_comment = sc.comment.clone();
                        }
                    }
                });
                ui.add_space(4.0);
                ui.separator();
                ui.horizontal(|ui| {
                    ui.add_sized([76.0, 20.0], egui::Label::new("名称:"));
                    ui.add(egui::TextEdit::singleline(&mut self.scen_name).desired_width(240.0));
                });
                ui.horizontal(|ui| {
                    ui.add_sized([76.0, 20.0], egui::Label::new("备注:"));
                    ui.add(egui::TextEdit::singleline(&mut self.scen_comment).desired_width(240.0));
                });
                ui.horizontal(|ui| {
                    ui.add_sized([76.0, 20.0], egui::Label::new("可变单元格:"));
                    ui.add(egui::TextEdit::singleline(&mut self.scen_range).desired_width(120.0));
                    ui.label(
                        egui::RichText::new("例如 A1:C3")
                            .size(11.0)
                            .color(ui_kit::TEXT_WEAK),
                    );
                });
                ui.horizontal(|ui| {
                    ui.add_sized([76.0, 20.0], egui::Label::new("结果单元格:"));
                    ui.add(egui::TextEdit::singleline(&mut self.scen_result).desired_width(120.0));
                    ui.label(
                        egui::RichText::new("可选；摘要里额外列出这些格子在每个方案下的值")
                            .size(11.0)
                            .color(ui_kit::TEXT_WEAK),
                    );
                });
                if !self.scen_msg.is_empty() {
                    ui.add_space(3.0);
                    ui.label(egui::RichText::new(&self.scen_msg).size(11.5));
                }
                ui_kit::footer(ui, |ui| {
                    if ui.button("添加/修改").clicked() {
                        do_add = true;
                    }
                    if ui.add_enabled(sel.is_some(), egui::Button::new("显示")).clicked() {
                        do_show = true;
                    }
                    if ui.add_enabled(sel.is_some(), egui::Button::new("删除")).clicked() {
                        do_del = true;
                    }
                    if ui.button("摘要").clicked() {
                        do_summary = true;
                    }
                    if ui_kit::primary_button(ui, "关闭").clicked() {
                        self.scen_dlg = false;
                    }
                });
            });
        self.scen_sel = sel;
        let rect = Self::parse_rect(&self.scen_range);
        if do_add {
            match (rect, self.scen_name.trim().is_empty()) {
                (Some(r), false) => {
                    let name = self.scen_name.trim().to_string();
                    let comment = self.scen_comment.trim().to_string();
                    let sc = sheetcore::scenarios::capture(
                        self.wb.sheet(self.sheet_idx),
                        &name,
                        &comment,
                        r,
                    );
                    let n = sc.cells.len();
                    {
                        let sh = self.wb.sheet_mut(self.sheet_idx);
                        if let Some(pos) = sh.scenarios.iter().position(|x| x.name == name) {
                            sh.scenarios[pos] = sc;
                        } else {
                            sh.scenarios.push(sc);
                        }
                        sh.scenarios_dirty = true;
                    }
                    self.wb.dirty = true;
                    self.scen_msg = format!("已保存方案「{name}」（{n} 个单元格）");
                    self.status = format!("方案「{name}」已保存");
                }
                (None, _) => self.scen_msg = "可变单元格地址写错了（例如 A1:C3）".into(),
                (_, true) => self.scen_msg = "名称不能为空".into(),
            }
        }
        if do_show {
            if let Some(i) = self.scen_sel {
                if let Some(sc) = self.wb.sheet(self.sheet_idx).scenarios.get(i).cloned() {
                    for ((r, c), v) in &sc.cells {
                        let val = sheetcore::scenarios::apply_value(v);
                        let sh = self.wb.sheet_mut(self.sheet_idx);
                        let mut cell = sh.get(*r, *c).cloned().unwrap_or_default();
                        cell.value = val;
                        cell.formula = None;
                        sh.set(*r, *c, cell);
                    }
                    self.wb.dirty = true;
                    self.doc_gen = self.doc_gen.wrapping_add(1);
                    self.deps = sheetcore::formula::deps::Deps::build(&self.wb);
                    sheetcore::formula::recalc_dirty(&mut self.wb, &self.deps, &[]);
                    sheetcore::formula::recalc_all(&mut self.wb);
                    self.scen_msg = format!("已显示方案「{}」", sc.name);
                    self.status = format!("已切换到方案「{}」", sc.name);
                }
            }
        }
        if do_del {
            if let Some(i) = self.scen_sel {
                let removed = {
                    let sh = self.wb.sheet_mut(self.sheet_idx);
                    if i < sh.scenarios.len() {
                        let n = sh.scenarios.remove(i).name;
                        sh.scenarios_dirty = true;
                        Some(n)
                    } else {
                        None
                    }
                };
                if let Some(n) = removed {
                    self.wb.dirty = true;
                    self.scen_sel = None;
                    self.scen_msg = format!("已删除方案「{n}」");
                }
            }
        }
        if do_summary {
            let res = if self.scen_result.trim().is_empty() {
                None
            } else {
                Self::parse_rect(&self.scen_result)
            };
            match self.build_scenario_summary(res) {
                Ok(name) => {
                    self.scen_msg = format!("已在「{name}」里生成摘要");
                    self.status = format!("方案摘要已生成：{name}");
                }
                Err(e) => self.scen_msg = e,
            }
        }
        if !open {
            self.scen_dlg = false;
        }
    }

    /// "A1:C3" / "A1" → (r1, c1, r2, c2)
    fn parse_rect(s: &str) -> Option<(u32, u32, u32, u32)> {
        let t = s.trim();
        if t.is_empty() {
            return None;
        }
        if let Some(r) = sheetcore::table::parse_a1(t) {
            return Some(r);
        }
        parse_a1_ref(t).map(|(r, c)| (r, c, r, c))
    }

    /// 生成「方案摘要」工作表（和 Excel 一样：每行一个方案）。
    /// 带 `results` 时，还会把每个方案下这些格子的计算结果一起写进去。
    fn build_scenario_summary(
        &mut self,
        results: Option<(u32, u32, u32, u32)>,
    ) -> Result<String, String> {
        let list = self.wb.sheet(self.sheet_idx).scenarios.clone();
        if list.is_empty() {
            return Err("还没有方案，先保存一个".into());
        }
        let mut keys: Vec<(u32, u32)> = Vec::new();
        for sc in &list {
            for (k, _) in &sc.cells {
                if !keys.contains(k) {
                    keys.push(*k);
                }
            }
        }
        keys.sort();
        let result_cells: Vec<(u32, u32)> = match results {
            Some((r1, c1, r2, c2)) => {
                let mut v = Vec::new();
                for r in r1..=r2 {
                    for c in c1..=c2 {
                        v.push((r, c));
                    }
                }
                v
            }
            None => Vec::new(),
        };
        // 先把「所有方案会动的格子」的当前值记下来，算完恢复
        let snapshot: Vec<((u32, u32), sheetcore::model::Value)> = keys
            .iter()
            .map(|(r, c)| {
                (
                    (*r, *c),
                    self.wb
                        .sheet(self.sheet_idx)
                        .get(*r, *c)
                        .map(|x| x.value.clone())
                        .unwrap_or_default(),
                )
            })
            .collect();
        // 逐个方案代值、重算、抓结果
        let mut rows: Vec<Vec<Vec<sheetcore::model::Value>>> = Vec::new();
        let deps = sheetcore::formula::deps::Deps::build(&self.wb);
        for sc in &list {
            for ((r, c), v) in &sc.cells {
                let val = sheetcore::scenarios::apply_value(v);
                let sh = self.wb.sheet_mut(self.sheet_idx);
                let mut cell = sh.get(*r, *c).cloned().unwrap_or_default();
                cell.value = val;
                cell.formula = None;
                sh.set(*r, *c, cell);
            }
            let seeds: Vec<_> = sc
                .cells
                .iter()
                .map(|((r, c), _)| (self.sheet_idx, *r, *c))
                .collect();
            sheetcore::formula::recalc_dirty(&mut self.wb, &deps, &seeds);
            let vals: Vec<sheetcore::model::Value> = result_cells
                .iter()
                .map(|(r, c)| {
                    self.wb
                        .sheet(self.sheet_idx)
                        .get(*r, *c)
                        .map(|x| x.value.clone())
                        .unwrap_or_default()
                })
                .collect();
            rows.push(vec![vals]);
        }
        // 恢复原状
        for ((r, c), v) in snapshot {
            let sh = self.wb.sheet_mut(self.sheet_idx);
            let mut cell = sh.get(r, c).cloned().unwrap_or_default();
            cell.value = v;
            sh.set(r, c, cell);
        }
        sheetcore::formula::recalc_all(&mut self.wb);

        let mut base = "方案摘要".to_string();
        let mut n = 1;
        while self.wb.sheets.iter().any(|s| s.name == base) {
            n += 1;
            base = format!("方案摘要{n}");
        }
        let mut sh = sheetcore::model::Sheet::new(&base);
        let mut put = |sh: &mut sheetcore::model::Sheet,
                       r: u32,
                       c: u32,
                       v: sheetcore::model::Value| {
            sh.set(
                r,
                c,
                sheetcore::model::Cell {
                    value: v,
                    formula: None,
                },
            );
        };
        put(&mut sh, 0, 0, sheetcore::model::Value::Text("方案摘要".into()));
        for (i, (r, c)) in keys.iter().enumerate() {
            put(
                &mut sh,
                1,
                i as u32 + 1,
                sheetcore::model::Value::Text(cell_name(*r, *c).into()),
            );
        }
        for (j, (r, c)) in result_cells.iter().enumerate() {
            put(
                &mut sh,
                1,
                keys.len() as u32 + j as u32 + 1,
                sheetcore::model::Value::Text(cell_name(*r, *c).into()),
            );
        }
        for (i, sc) in list.iter().enumerate() {
            let row = i as u32 + 2;
            put(&mut sh, row, 0, sheetcore::model::Value::Text(sc.name.clone().into()));
            for (j, k) in keys.iter().enumerate() {
                let v = sc
                    .cells
                    .iter()
                    .find(|(kk, _)| kk == k)
                    .map(|(_, v)| sheetcore::scenarios::apply_value(v))
                    .unwrap_or_default();
                put(&mut sh, row, j as u32 + 1, v);
            }
            for (j, v) in rows[i][0].iter().enumerate() {
                put(
                    &mut sh,
                    row,
                    keys.len() as u32 + j as u32 + 1,
                    v.clone(),
                );
            }
        }
        let idx = self.wb.sheets.len();
        if !sheetcore::sheet_ops::insert_sheet(&mut self.wb, idx, sh) {
            return Err("新建摘要表失败".into());
        }
        self.sheet_idx = idx;
        self.sel = (0, 0);
        self.sel_end = (0, 0);
        self.finish_sheet_change();
        self.wb.dirty = true;
        self.doc_gen = self.doc_gen.wrapping_add(1);
        Ok(base)
    }

    fn goal_window(&mut self, ctx: &egui::Context) {
        if !self.goal_dlg {
            return;
        }
        let mut open = true;
        let mut solve = false;
        ui_kit::window(ctx, "单变量求解", 420.0)
            .open(&mut open)
            .show(ctx, |ui| {
                ui.horizontal(|ui| {
                    ui.add_sized([84.0, 20.0], egui::Label::new("目标单元格:"));
                    ui.add(egui::TextEdit::singleline(&mut self.goal_target).desired_width(150.0));
                });
                ui.horizontal(|ui| {
                    ui.add_sized([84.0, 20.0], egui::Label::new("目标值:"));
                    ui.add(egui::TextEdit::singleline(&mut self.goal_goal).desired_width(150.0));
                });
                ui.horizontal(|ui| {
                    ui.add_sized([84.0, 20.0], egui::Label::new("可变单元格:"));
                    ui.add(egui::TextEdit::singleline(&mut self.goal_input).desired_width(150.0));
                });
                if !self.goal_msg.is_empty() {
                    ui.add_space(4.0);
                    ui.label(egui::RichText::new(&self.goal_msg).size(11.5));
                }
                ui_kit::footer(ui, |ui| {
                    if ui_kit::primary_button(ui, "求解").clicked() {
                        solve = true;
                    }
                    if ui_kit::secondary_button(ui, "取消").clicked() {
                        self.goal_dlg = false;
                    }
                });
            });
        if solve {
            let t = Self::parse_addr(&self.goal_target);
            let v = Self::parse_addr(&self.goal_input);
            let goal = self.goal_goal.trim().parse::<f64>();
            match (t, v, goal) {
                (Some((tr, tc)), Some((vr, vc)), Ok(g)) => {
                    let txn_keys = [(vr, vc)];
                    let txn = self.txn_begin(&txn_keys.into_iter().map(|(r, c)| (r, c)).collect::<Vec<_>>());
                    match self.goal_seek_run(tr, tc, g, vr, vc) {
                        Ok(x) => {
                            self.goal_msg = format!(
                                "求解成功：{}{} = {:.6}",
                                sheetcore::model::cell_name(vr, vc),
                                "，",
                                x
                            );
                            self.txn_end("单变量求解", txn);
                            self.wb.dirty = true;
                            self.doc_gen = self.doc_gen.wrapping_add(1);
                            self.status = format!("单变量求解：{}{} = {:.6}", sheetcore::model::cell_name(vr, vc), "", x);
                        }
                        Err(e) => self.goal_msg = e,
                    }
                }
                _ => self.goal_msg = "单元格地址或目标值写错了".into(),
            }
        }
        if !open {
            self.goal_dlg = false;
        }
    }

    /// 模拟运算表（列式单变量）：选区第一列是输入值，第二列顶行是公式，
    /// 按每个输入值代入后把结果填到第二列。
    /// 模拟运算表：列式单变量 / 行式单变量 / 双变量三种版式，按选区形状自动判断。
    /// - 双变量：公式在选区左上角，第一行是行输入值，第一列是列输入值
    /// - 列式单变量：公式在选区右上格的上方，第一列是输入值、第二列出结果
    /// - 行式单变量：公式在选区左下格的左边，第一行是输入值、第二行出结果
    fn data_table_run(
        &mut self,
        row_in: Option<(u32, u32)>,
        col_in: Option<(u32, u32)>,
    ) -> Result<(String, usize), String> {
        let (r1, c1, r2, c2) = self.sel_rect();
        let has_formula = |app: &Self, r: i64, c: i64| -> bool {
            if r < 0 || c < 0 {
                return false;
            }
            app.wb
                .sheet(app.sheet_idx)
                .get(r as u32, c as u32)
                .and_then(|x| x.formula.clone())
                .is_some()
        };
        // 判定版式
        let mode = if has_formula(self, r1 as i64, c1 as i64) && c2 > c1 && r2 > r1 {
            "two"
        } else if has_formula(self, r1 as i64 - 1, c2 as i64) {
            "col"
        } else if has_formula(self, r1 as i64 + 1, c1 as i64) {
            "row"
        } else {
            return Err(
                "认不出版式：双变量要求公式在选区左上角；                  单变量（列）要求公式在结果列上方；                 单变量（行）要求公式在结果行左侧"
                    .into(),
            );
        };
        let need_row = mode == "row" || mode == "two";
        let need_col = mode == "col" || mode == "two";
        if need_row && row_in.is_none() {
            return Err("这个版式需要「行输入引用单元格」".into());
        }
        if need_col && col_in.is_none() {
            return Err("这个版式需要「列输入引用单元格」".into());
        }
        let (fcell, results_src): ((u32, u32), Vec<(u32, u32, Option<f64>, Option<f64>)>) = match mode {
            "two" => {
                let mut cells = Vec::new();
                for r in (r1 + 1)..=r2 {
                    for c in (c1 + 1)..=c2 {
                        let rv = self.cell_num(r, c1);
                        let cv = self.cell_num(r1, c);
                        cells.push((r, c, rv, cv));
                    }
                }
                ((r1, c1), cells)
            }
            "col" => {
                let mut cells = Vec::new();
                for r in r1..=r2 {
                    let cv = self.cell_num(r, c1);
                    cells.push((r, c2, None, cv));
                }
                ((r1 - 1, c2), cells)
            }
            _ => {
                let mut cells = Vec::new();
                for c in (c1 + 1)..=c2 {
                    let rv = self.cell_num(r1, c);
                    cells.push((r1 + 1, c, rv, None));
                }
                ((r1 + 1, c1), cells)
            }
        };
        if results_src.iter().all(|(_, _, rv, cv)| rv.is_none() && cv.is_none()) {
            return Err("选区里没有可用的输入值".into());
        }
        let deps = sheetcore::formula::deps::Deps::build(&self.wb);
        let orig_row = row_in.and_then(|(r, c)| self.cell_num(r, c));
        let orig_col = col_in.and_then(|(r, c)| self.cell_num(r, c));
        let mut done = 0usize;
        for (r, c, rv, cv) in results_src {
            if let (Some((ri, ci)), Some(v)) = (row_in, rv) {
                self.poke_cell(&deps, ri, ci, v);
            }
            if let (Some((ci2, cj2)), Some(v)) = (col_in, cv) {
                self.poke_cell(&deps, ci2, cj2, v);
            }
            let out = self
                .wb
                .sheet(self.sheet_idx)
                .get(fcell.0, fcell.1)
                .map(|x| x.value.clone())
                .unwrap_or_default();
            let sh = self.wb.sheet_mut(self.sheet_idx);
            let mut cell = sh.get(r, c).cloned().unwrap_or_default();
            cell.value = out;
            cell.formula = None;
            sh.set(r, c, cell);
            done += 1;
        }
        if let (Some((ri, ci)), Some(v)) = (row_in, orig_row) {
            self.poke_cell(&deps, ri, ci, v);
        }
        if let (Some((ci2, cj2)), Some(v)) = (col_in, orig_col) {
            self.poke_cell(&deps, ci2, cj2, v);
        }
        let label = match mode {
            "two" => "双变量",
            "col" => "单变量（列）",
            _ => "单变量（行）",
        };
        Ok((label.to_string(), done))
    }

    fn dtable_window(&mut self, ctx: &egui::Context) {
        if !self.dtable_dlg {
            return;
        }
        let mut open = true;
        let mut run = false;
        ui_kit::window(ctx, "模拟运算表", 480.0)
            .open(&mut open)
            .show(ctx, |ui| {
                ui.label(
                    egui::RichText::new(
                        "双变量：公式在选区左上角，首行是行输入值、首列是列输入值。
                         单变量（列）：公式在结果列上方，第一列是输入值。
                         单变量（行）：公式在结果行左侧，第一行是输入值。",
                    )
                    .size(11.5)
                    .color(ui_kit::TEXT_WEAK),
                );
                ui.add_space(4.0);
                ui.horizontal(|ui| {
                    ui.add_sized([110.0, 20.0], egui::Label::new("行输入单元格:"));
                    ui.add(egui::TextEdit::singleline(&mut self.dtable_row).desired_width(120.0));
                });
                ui.horizontal(|ui| {
                    ui.add_sized([110.0, 20.0], egui::Label::new("列输入单元格:"));
                    ui.add(egui::TextEdit::singleline(&mut self.dtable_col).desired_width(120.0));
                });
                if !self.dtable_msg.is_empty() {
                    ui.add_space(4.0);
                    ui.label(egui::RichText::new(&self.dtable_msg).size(11.5));
                }
                ui_kit::footer(ui, |ui| {
                    if ui_kit::primary_button(ui, "确定").clicked() {
                        run = true;
                    }
                    if ui_kit::secondary_button(ui, "取消").clicked() {
                        self.dtable_dlg = false;
                    }
                });
            });
        if run {
            let rin = if self.dtable_row.trim().is_empty() {
                None
            } else {
                Self::parse_addr(&self.dtable_row)
            };
            let cin = if self.dtable_col.trim().is_empty() {
                None
            } else {
                Self::parse_addr(&self.dtable_col)
            };
            match self.data_table_run(rin, cin) {
                Ok((label, n)) => {
                    self.dtable_msg = format!("{label}：已填 {n} 个结果");
                    self.wb.dirty = true;
                    self.doc_gen = self.doc_gen.wrapping_add(1);
                    self.status = format!("模拟运算表（{label}）：已填 {n} 个结果");
                }
                Err(e) => self.dtable_msg = e,
            }
        }
        if !open {
            self.dtable_dlg = false;
        }
    }

